def _parse_operator_discord_ids(*raw_values: Any) -> tuple[str, ...]:
    ids: list[str] = []
    seen: set[str] = set()
    for raw in raw_values:
        for chunk in str(raw or "").replace(";", ",").split(","):
            digits = "".join(ch for ch in str(chunk).strip() if ch.isdigit())
            if not digits or digits in seen:
                continue
            seen.add(digits)
            ids.append(digits)
    return tuple(ids)


