def _read_json(path: Path) -> dict[str, Any]:
    try:
        if path.exists() and path.is_file():
            payload = json.loads(path.read_text(encoding="utf-8-sig"))
            return payload if isinstance(payload, dict) else {}
    except Exception:
        pass
    return {}

def _json_ready(value: Any) -> Any:
    try:
        return json.loads(json.dumps(value, ensure_ascii=False, default=str))
    except Exception:
        return value

def _read_json_limited(path: Path, max_bytes: int) -> dict[str, Any]:
    try:
        if not path.exists() or not path.is_file():
            return {}
        if path.stat().st_size > max_bytes:
            return {}
        return json.loads(path.read_text(encoding="utf-8-sig"))
    except Exception:
        return {}

def _write_json(path: Path, payload: dict[str, Any]):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")

def _workspace_path_candidates(rel_path: str) -> list[Path]:
    clean = str(rel_path or "").strip().replace("\\", "/").lstrip("/")
    if not clean:
        return [WORKSPACE_ROOT]
    cwd = Path.cwd()
    candidates = [WORKSPACE_ROOT / clean]
    if not clean.startswith("payload/"):
        candidates.append(WORKSPACE_ROOT / "payload" / clean)
    candidates.append(cwd / clean)
    if not clean.startswith("payload/"):
        candidates.append(cwd / "payload" / clean)
    out: list[Path] = []
    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate)
        if key in seen:
            continue
        seen.add(key)
        out.append(candidate)
    return out

def _first_existing_workspace_path(rel_path: str) -> Optional[Path]:
    for candidate in _workspace_path_candidates(rel_path):
        if candidate.exists():
            return candidate
    return None

def _workspace_compose_manifest_candidates() -> list[Path]:
    out: list[Path] = []
    seen: set[str] = set()
    for rel_path in ("server-compose.yml", "docker-compose.yml", "docker-compose.yaml"):
        for candidate in _workspace_path_candidates(rel_path):
            key = str(candidate)
            if key in seen:
                continue
            seen.add(key)
            out.append(candidate)
    return out

def _first_existing_workspace_compose_manifest() -> Optional[Path]:
    for candidate in _workspace_compose_manifest_candidates():
        if candidate.exists():
            return candidate
    return None

