def load_feature_contracts() -> dict[str, Any]:
    default = _default_feature_contracts()
    disk = _read_json(FEATURE_CONTRACT_PATH)
    if not isinstance(disk.get("features"), list):
        _write_json(FEATURE_CONTRACT_PATH, default)
        return default
    merged: list[dict[str, Any]] = []
    existing = {
        str(row.get("id") or "").strip(): row
        for row in disk.get("features", [])
        if isinstance(row, dict) and str(row.get("id") or "").strip()
    }
    for feature in default.get("features", []):
        feature_id = str(feature.get("id") or "").strip()
        current = existing.pop(feature_id, {})
        merged.append({**feature, **current})
    for feature_id in sorted(existing.keys()):
        merged.append(existing[feature_id])
    payload = {**default, **disk, "features": merged, "updated_at": int(time.time())}
    if disk != payload:
        _write_json(FEATURE_CONTRACT_PATH, payload)
    return payload

def _maintenance_mode_key(value: Any) -> str:
    mode = str(value or "normal").strip().lower()
    if mode not in {"normal", "diagnose", "repair_safe", "freeze"}:
        return "normal"
    return mode

def _maintenance_policy(mode: str) -> dict[str, Any]:
    key = _maintenance_mode_key(mode)
    policies = {
        "normal": {
            "write_allowed": True,
            "service_actions_allowed": True,
            "self_apply_allowed": True,
            "autopilot_actions_allowed": True,
            "description": "Normal runtime. Write lanes, service control, and safe auto-recovery are allowed.",
        },
        "diagnose": {
            "write_allowed": False,
            "service_actions_allowed": False,
            "self_apply_allowed": False,
            "autopilot_actions_allowed": False,
            "description": "Diagnostics only. Read and inspect, but do not mutate code or restart services.",
        },
        "repair_safe": {
            "write_allowed": True,
            "service_actions_allowed": True,
            "self_apply_allowed": True,
            "autopilot_actions_allowed": False,
            "description": "Manual repair lane. Controlled writes and service actions are allowed, but autopilot stays hands-off.",
        },
        "freeze": {
            "write_allowed": False,
            "service_actions_allowed": False,
            "self_apply_allowed": False,
            "autopilot_actions_allowed": False,
            "description": "Change freeze. Preserve state until an operator explicitly resumes a writable mode.",
        },
    }
    return {"mode": key, **policies[key]}

def _default_maintenance_mode() -> dict[str, Any]:
    policy = _maintenance_policy("normal")
    now_ts = int(time.time())
    return {
        "mode": policy["mode"],
        "reason": "",
        "note": "",
        "random_health_checks": True,
        "set_by": "system",
        "started_at": now_ts,
        "updated_at": now_ts,
        "policy": policy,
    }

def load_maintenance_mode() -> dict[str, Any]:
    default = _default_maintenance_mode()
    disk = _read_json(MAINTENANCE_MODE_PATH)
    payload = {**default, **(disk if isinstance(disk, dict) else {})}
    payload["mode"] = _maintenance_mode_key(payload.get("mode"))
    payload["policy"] = _maintenance_policy(payload["mode"])
    payload["random_health_checks"] = bool(payload.get("random_health_checks", True))
    if not int(payload.get("started_at") or 0):
        payload["started_at"] = int(time.time())
    payload["updated_at"] = int(time.time())
    if disk != payload:
        _write_json(MAINTENANCE_MODE_PATH, payload)
    return payload

def save_maintenance_mode(
    mode: str,
    *,
    reason: str = "",
    note: str = "",
    random_health_checks: bool | None = None,
    set_by: str = "",
) -> dict[str, Any]:
    current = load_maintenance_mode()
    mode_key = _maintenance_mode_key(mode)
    now_ts = int(time.time())
    started_at = int(current.get("started_at") or now_ts)
    if mode_key != str(current.get("mode") or "normal").strip().lower():
        started_at = now_ts
    payload = {
        "mode": mode_key,
        "reason": str(reason or "").strip()[:240],
        "note": str(note or "").strip()[:2400],
        "random_health_checks": bool(current.get("random_health_checks", True) if random_health_checks is None else random_health_checks),
        "set_by": str(set_by or current.get("set_by") or "operator").strip()[:120] or "operator",
        "started_at": started_at,
        "updated_at": now_ts,
        "policy": _maintenance_policy(mode_key),
    }
    _write_json(MAINTENANCE_MODE_PATH, payload)
    return payload

