def _is_allowed_cloud_model(model_name: str) -> bool:
    allowed = {"gpt-5.2", "gpt-5.3", "gpt-5.3-codex", "gpt-5.4", "gpt-5.4-mini", "gpt-5.5"}
    return str(model_name or "").strip() in allowed

def _sanitize_runtime_policy(raw: Any) -> dict[str, Any]:
    payload = _default_runtime_policy()
    if isinstance(raw, dict):
        for key, value in raw.items():
            if isinstance(value, dict) and isinstance(payload.get(key), dict):
                payload[key].update(value)
            else:
                payload[key] = value
    execution_profile = str(payload.get("execution_profile") or "pro_only").strip().lower()
    payload["execution_profile"] = execution_profile if execution_profile in {"pro_only", "api_enabled"} else "pro_only"
    payload["workers_paused"] = bool(payload.get("workers_paused", False))
    payload["worker_pause_reason"] = str(payload.get("worker_pause_reason", "")).strip()[:240]
    payload["cloud_model_floor"] = "gpt-5.2"
    for key, fallback in _default_runtime_policy()["openai_models"].items():
        model_name = str((payload.get("openai_models") or {}).get(key, fallback)).strip()
        payload["openai_models"][key] = model_name if _is_allowed_cloud_model(model_name) else fallback
    for key, fallback in _default_runtime_policy()["codex_models"].items():
        model_name = str((payload.get("codex_models") or {}).get(key, fallback)).strip()
        payload["codex_models"][key] = model_name if _is_allowed_cloud_model(model_name) else fallback
    for key, fallback in _default_runtime_policy()["rate_limits"].items():
        try:
            value = int((payload.get("rate_limits") or {}).get(key, fallback))
        except Exception:
            value = fallback
        if "per_hour" in key:
            value = max(1, min(value, 120))
        else:
            value = max(1, min(value, 30))
        payload["rate_limits"][key] = value
    payload.setdefault("darius_queue", {})
    for key, fallback in _default_runtime_policy()["darius_queue"].items():
        try:
            value = int((payload.get("darius_queue") or {}).get(key, fallback))
        except Exception:
            value = int(fallback)
        if "per_service" in key or "parallel" in key:
            value = max(1, min(value, 4))
        elif "max_backoff" in key:
            value = max(DARIUS_ASSIGNMENT_BASE_COOLDOWN_SEC, min(value, 86400))
        else:
            value = max(60, min(value, 86400))
        payload["darius_queue"][key] = value
    payload.setdefault("orchestration", {})
    orchestration_defaults = _default_runtime_policy()["orchestration"]
    for key, fallback in orchestration_defaults.items():
        current = (payload.get("orchestration") or {}).get(key, fallback)
        if isinstance(fallback, dict):
            nested = dict(fallback)
            if isinstance(current, dict):
                nested.update(current)
            payload["orchestration"][key] = nested
        else:
            payload["orchestration"][key] = current
    try:
        payload["orchestration"]["zeus_heavy_sweep_sec"] = max(
            3600,
            min(int(payload["orchestration"].get("zeus_heavy_sweep_sec") or DEFAULT_ZEUS_HEAVY_SWEEP_SEC), 86400),
        )
    except Exception:
        payload["orchestration"]["zeus_heavy_sweep_sec"] = DEFAULT_ZEUS_HEAVY_SWEEP_SEC
    try:
        payload["orchestration"]["life_ops_internal_review_sec"] = max(
            900,
            min(int(payload["orchestration"].get("life_ops_internal_review_sec") or DEFAULT_LIFE_OPS_INTERNAL_REVIEW_SEC), 86400),
        )
    except Exception:
        payload["orchestration"]["life_ops_internal_review_sec"] = DEFAULT_LIFE_OPS_INTERNAL_REVIEW_SEC
    outreach_mode = str(payload["orchestration"].get("life_ops_user_outreach_mode") or "waking_hours_only").strip().lower()
    payload["orchestration"]["life_ops_user_outreach_mode"] = outreach_mode if outreach_mode in {"waking_hours_only", "always", "manual_only"} else "waking_hours_only"
    waking = payload["orchestration"].get("life_ops_waking_hours")
    if not isinstance(waking, dict):
        waking = {}
    try:
        start_hour = max(0, min(int(waking.get("start_hour") or DEFAULT_LIFE_OPS_WAKE_START_HOUR), 23))
    except Exception:
        start_hour = DEFAULT_LIFE_OPS_WAKE_START_HOUR
    try:
        end_hour = max(0, min(int(waking.get("end_hour") or DEFAULT_LIFE_OPS_WAKE_END_HOUR), 23))
    except Exception:
        end_hour = DEFAULT_LIFE_OPS_WAKE_END_HOUR
    payload["orchestration"]["life_ops_waking_hours"] = {
        "timezone": str(waking.get("timezone") or "America/New_York").strip() or "America/New_York",
        "start_hour": start_hour,
        "end_hour": end_hour,
    }
    brain_cfg = payload["orchestration"].get("brain")
    if not isinstance(brain_cfg, dict):
        brain_cfg = {}
    brain_defaults = orchestration_defaults["brain"]
    brain_cfg = {**brain_defaults, **brain_cfg}
    brain_cfg["enabled"] = bool(brain_cfg.get("enabled", True))
    provider = str(brain_cfg.get("provider") or "ollama").strip().lower()
    brain_cfg["provider"] = provider if provider in {"ollama", "openai", "custom"} else "ollama"
    brain_cfg["model"] = str(brain_cfg.get("model") or MODEL_PRESENCE).strip() or MODEL_PRESENCE
    try:
        brain_cfg["interval_sec"] = max(30, min(int(brain_cfg.get("interval_sec") or 180), 3600))
    except Exception:
        brain_cfg["interval_sec"] = 180
    brain_cfg["persist_memory"] = bool(brain_cfg.get("persist_memory", True))
    brain_cfg["persist_state"] = bool(brain_cfg.get("persist_state", True))
    brain_cfg["hermes_local_enabled"] = bool(brain_cfg.get("hermes_local_enabled", True))
    payload["orchestration"]["brain"] = brain_cfg
    maintenance_cfg = payload["orchestration"].get("memory_maintenance")
    if not isinstance(maintenance_cfg, dict):
        maintenance_cfg = {}
    maintenance_defaults = orchestration_defaults["memory_maintenance"]
    maintenance_cfg = {**maintenance_defaults, **maintenance_cfg}
    maintenance_cfg["enabled"] = bool(maintenance_cfg.get("enabled", True))
    maintenance_cfg["timezone"] = str(maintenance_cfg.get("timezone") or "America/New_York").strip() or "America/New_York"
    try:
        maintenance_cfg["run_hour_local"] = max(0, min(int(maintenance_cfg.get("run_hour_local") or 4), 23))
    except Exception:
        maintenance_cfg["run_hour_local"] = 4
    try:
        maintenance_cfg["run_minute_local"] = max(0, min(int(maintenance_cfg.get("run_minute_local") or 15), 59))
    except Exception:
        maintenance_cfg["run_minute_local"] = 15
    for flag in (
        "compact_service_threads",
        "bootstrap_service_threads",
        "rebuild_workspace_atlas",
        "save_memory_note",
        "reset_brain_session",
    ):
        maintenance_cfg[flag] = bool(maintenance_cfg.get(flag, maintenance_defaults.get(flag, True)))
    payload["orchestration"]["memory_maintenance"] = maintenance_cfg
    payload["orchestration"]["codex_thread_template_version"] = str(
        payload["orchestration"].get("codex_thread_template_version") or PROJECT_CODEX_TEMPLATE_VERSION
    ).strip() or PROJECT_CODEX_TEMPLATE_VERSION
    return payload

def load_runtime_policy() -> dict[str, Any]:
    disk = _read_json(RUNTIME_POLICY_PATH)
    payload = _sanitize_runtime_policy(disk)
    if payload != disk:
        _write_json(RUNTIME_POLICY_PATH, payload)
    return payload

def save_runtime_policy_fields(
    *,
    execution_profile: str = "",
    workers_paused: bool | None = None,
    worker_pause_reason: str = "",
    openai_models: Optional[dict[str, Any]] = None,
    codex_models: Optional[dict[str, Any]] = None,
    rate_limits: Optional[dict[str, Any]] = None,
    orchestration: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    payload = load_runtime_policy()
    if execution_profile.strip():
        payload["execution_profile"] = execution_profile.strip().lower()
    if workers_paused is not None:
        payload["workers_paused"] = bool(workers_paused)
    if worker_pause_reason.strip():
        payload["worker_pause_reason"] = worker_pause_reason.strip()[:240]
    elif workers_paused is False:
        payload["worker_pause_reason"] = ""
    if isinstance(openai_models, dict):
        payload.setdefault("openai_models", {}).update(openai_models)
    if isinstance(codex_models, dict):
        payload.setdefault("codex_models", {}).update(codex_models)
    if isinstance(rate_limits, dict):
        payload.setdefault("rate_limits", {}).update(rate_limits)
    if isinstance(orchestration, dict):
        payload.setdefault("orchestration", {}).update(orchestration)
    payload = _sanitize_runtime_policy(payload)
    _write_json(RUNTIME_POLICY_PATH, payload)
    return payload

def runtime_worker_pause_state() -> dict[str, Any]:
    policy = load_runtime_policy()
    return {
        "paused": bool(policy.get("workers_paused", False)),
        "reason": str(policy.get("worker_pause_reason", "")).strip(),
        "path": str(RUNTIME_POLICY_PATH),
        "execution_profile": str(policy.get("execution_profile") or "pro_only").strip(),
    }

def current_execution_profile() -> str:
    return str(load_runtime_policy().get("execution_profile") or "pro_only").strip().lower() or "pro_only"

def current_active_executor() -> str:
    return "darius" if current_execution_profile() == "pro_only" else "server_codex"

def current_fallback_executor() -> str:
    return "server_codex" if current_execution_profile() == "pro_only" else "darius"

def current_recommended_executor() -> str:
    if current_execution_profile() == "pro_only":
        return "darius"
    return "server_codex" if bool(CODEX_CLI_AUTH_READY) and bool(CODEX_CLI_EXEC_READY) and not bool(current_codex_cli_exec_error()) else "darius"

def local_model_runtime_summary() -> dict[str, Any]:
    active = resolve_active_models()
    rows: dict[str, Any] = {}
    local_count = 0
    for role, cfg in active.items():
        if not isinstance(cfg, dict):
            continue
        provider = str(cfg.get("provider") or "ollama").strip() or "ollama"
        model = str(cfg.get("model") or "").strip()
        row = {"provider": provider, "model": model, "local": provider != "openai"}
        if row["local"]:
            local_count += 1
        rows[str(role or "default").strip() or "default"] = row
    return {"available": local_count > 0, "local_role_count": local_count, "roles": rows}

