def workspace_connection_ref(ref_key: str) -> dict[str, Any]:
    wanted = str(ref_key or "").strip()
    if not wanted:
        return {}
    registry = load_workspace_connections_profile()
    for row in registry.get("nodes", []):
        if not isinstance(row, dict):
            continue
        if str(row.get("key") or "").strip() == wanted:
            return {**row, "kind": str(row.get("kind") or "node").strip() or "node"}
    for row in registry.get("connections", []):
        if not isinstance(row, dict):
            continue
        if str(row.get("key") or "").strip() == wanted:
            return row
    return {}


def workspace_atlas_project(project_key: str) -> dict[str, Any]:
    wanted = normalize_project_key(project_key)
    if not wanted:
        return {}
    snapshot = load_workspace_atlas_snapshot()
    for row in snapshot.get("projects", []):
        if not isinstance(row, dict):
            continue
        if normalize_project_key(row.get("project_key")) == wanted:
            return row
    return {}


def olympus_project_profile_for_workspace_project(project_key: str) -> dict[str, Any]:
    normalized = normalize_project_key(project_key)
    if not normalized:
        return {}
    registry_row = workspace_registry_project(normalized)
    registry_root = str(registry_row.get("root_path") or "").strip().replace("\\", "/").rstrip("/")
    best: dict[str, Any] = {}
    best_score = -1
    for row in load_olympus_project_profiles():
        score = 0
        row_key = normalize_project_key(row.get("key"))
        aliases = [normalize_project_key(alias) for alias in row.get("aliases", [])] if isinstance(row.get("aliases"), list) else []
        row_root = str(row.get("root_path") or "").strip().replace("\\", "/").rstrip("/")
        if row_key == normalized:
            score += 80
        if normalized in aliases:
            score += 60
        if registry_root and row_root and registry_root == row_root:
            score += 120
        if score > best_score:
            best = row
            best_score = score
    return best if best_score > 0 else {}


def rebuild_workspace_atlas(project_key: str = "") -> dict[str, Any]:
    if not WORKSPACE_ATLAS_BUILDER_PATH.exists():
        raise FileNotFoundError(f"Atlas builder not found: {WORKSPACE_ATLAS_BUILDER_PATH}")
    python_bin = shutil.which("python3") or shutil.which("python") or "python3"
    cmd = [python_bin, str(WORKSPACE_ATLAS_BUILDER_PATH), "--apply"]
    wanted = normalize_project_key(project_key)
    if wanted:
        cmd.extend(["--project-key", wanted])
    proc = subprocess.run(cmd, capture_output=True, text=True)
    if proc.returncode != 0:
        raise RuntimeError((proc.stderr or proc.stdout or "atlas rebuild failed").strip())
    return load_workspace_atlas_snapshot()

