def _service_thread_blueprint(service_key: str) -> dict[str, Any]:
    normalized = str(service_key or "").strip().lower()
    return dict(_service_thread_blueprints().get(normalized, {}))

def _service_thread_pack_paths(service_key: str) -> dict[str, Path]:
    root = SERVICE_THREAD_ROOT / str(service_key or "").strip().lower()
    return {
        "root": root,
        "rules": root / "rules.md",
        "memory": root / "memory.json",
        "tests": root / "tests.md",
        "must_keep_features": root / "must_keep_features.json",
        "ownership": root / "ownership.json",
    }

def _service_thread_contract_rows(service_key: str) -> list[dict[str, Any]]:
    blueprint = _service_thread_blueprint(service_key)
    compose_alias = str(blueprint.get("profile_key") or service_key).strip()
    rows: list[dict[str, Any]] = []
    contracts = load_feature_contracts().get("features", [])
    for row in contracts if isinstance(contracts, list) else []:
        if not isinstance(row, dict):
            continue
        compose = [str(item).strip() for item in (row.get("compose_services") or []) if str(item).strip()]
        if compose_alias in compose or str(service_key or "").strip() in compose:
            rows.append(
                {
                    "id": str(row.get("id") or "").strip(),
                    "name": str(row.get("name") or "").strip(),
                    "must_keep": bool(row.get("must_keep", False)),
                    "notes": str(row.get("notes") or "").strip(),
                }
            )
    return rows

def _service_thread_rules_text(service_key: str, blueprint: dict[str, Any]) -> str:
    owned_paths = [str(item).strip() for item in (blueprint.get("owned_paths") or []) if str(item).strip()]
    contracts = _service_thread_contract_rows(service_key)
    lines = [
        f"# {str(blueprint.get('display_name') or pretty_label(service_key)).strip()}",
        "",
        "## Operating mode",
        "- Execution profile defaults to `pro_only`.",
        "- Zeus plans, reviews, and routes.",
        "- Darius is the only cloud/Codex write lane.",
        "- Local models can summarize, review, verify, and triage.",
        "",
        "## Non-negotiables",
        "- Never remove an existing feature.",
        "- Respect file checkout locks before any write.",
        "- Keep public summaries sanitized. No secrets or chain-of-thought.",
        "- Persist durable summaries back into `memory.json` after work completes or is blocked.",
        "",
        "## Owned paths",
    ]
    lines.extend([f"- `{item}`" for item in owned_paths] or ["- `(none registered)`"])
    lines.extend(["", "## Must-keep features"])
    lines.extend([f"- `{row.get('id')}`: {row.get('name')}" for row in contracts] or ["- `(no feature contracts matched yet)`"])
    return "\n".join(lines).strip() + "\n"

def _service_thread_tests_text(service_key: str, blueprint: dict[str, Any]) -> str:
    tests = [str(item).strip() for item in (blueprint.get("tests") or []) if str(item).strip()]
    return "\n".join([f"# {str(blueprint.get('display_name') or pretty_label(service_key)).strip()} verification", ""] + [f"- {item}" for item in tests]).strip() + "\n"

def _service_thread_memory_payload(service_key: str, blueprint: dict[str, Any], existing: Optional[dict[str, Any]] = None) -> dict[str, Any]:
    payload = existing if isinstance(existing, dict) else {}
    rows = payload.get("recent_summaries") if isinstance(payload.get("recent_summaries"), list) else []
    blockers = payload.get("blockers") if isinstance(payload.get("blockers"), list) else []
    decisions = payload.get("decisions") if isinstance(payload.get("decisions"), list) else []
    return {
        "version": "2026-03-14",
        "service_key": service_key,
        "display_name": str(blueprint.get("display_name") or pretty_label(service_key)).strip(),
        "thread_id": str(payload.get("thread_id") or f"svc_{service_key.replace('-', '_')}").strip(),
        "executor": str(blueprint.get("executor") or "darius").strip() or "darius",
        "recent_summaries": [row for row in rows if isinstance(row, dict)][-24:],
        "blockers": [row for row in blockers if isinstance(row, dict)][-24:],
        "decisions": [row for row in decisions if isinstance(row, dict)][-24:],
        "updated_at": int(time.time()),
        "last_compacted_at": int(payload.get("last_compacted_at") or 0),
    }

def _service_thread_ownership_payload(service_key: str, blueprint: dict[str, Any]) -> dict[str, Any]:
    return {
        "service_key": service_key,
        "checkout_root": "workspace",
        "checkout_path": str(blueprint.get("checkout_target") or "").strip(),
        "checkout_scope_kind": "tree",
        "owned_paths": [str(item).strip() for item in (blueprint.get("owned_paths") or []) if str(item).strip()],
    }

def _service_thread_pack_preview(service_key: str, max_chars: int = 1200) -> dict[str, Any]:
    paths = _service_thread_pack_paths(service_key)
    out: dict[str, Any] = {"service_key": service_key}
    for key in ("rules", "tests"):
        path = paths[key]
        out[f"{key}_path"] = str(path)
        if path.exists():
            out[f"{key}_preview"] = path.read_text(encoding="utf-8", errors="ignore")[:max_chars]
    for key in ("memory", "must_keep_features", "ownership"):
        path = paths[key]
        out[f"{key}_path"] = str(path)
        payload = _read_json(path)
        if payload:
            out[key] = payload
    return out

def _default_service_thread_registry() -> dict[str, Any]:
    return {"version": "2026-03-14", "updated_at": int(time.time()), "execution_profile": current_execution_profile(), "threads": []}

def _default_darius_assignment_state() -> dict[str, Any]:
    return {"version": "2026-03-14", "updated_at": int(time.time()), "rows": []}

def _export_darius_service_thread_context(registry_payload: dict[str, Any], assignment_payload: dict[str, Any]):
    DARIUS_EXPORT_THREAD_REGISTRY_PATH.parent.mkdir(parents=True, exist_ok=True)
    DARIUS_EXPORT_ASSIGNMENTS_PATH.parent.mkdir(parents=True, exist_ok=True)
    DARIUS_EXPORT_PROJECT_MEMORY_PATH.parent.mkdir(parents=True, exist_ok=True)
    DARIUS_EXPORT_REPO_RULES_PATH.parent.mkdir(parents=True, exist_ok=True)
    DARIUS_EXPORT_THREAD_REGISTRY_PATH.write_text(json.dumps(registry_payload, indent=2, ensure_ascii=False), encoding="utf-8")
    DARIUS_EXPORT_ASSIGNMENTS_PATH.write_text(json.dumps(assignment_payload, indent=2, ensure_ascii=False), encoding="utf-8")
    project_memory = {
        "version": "2026-03-14",
        "executionProfile": current_execution_profile(),
        "activeExecutor": current_active_executor(),
        "recommendedExecutor": current_recommended_executor(),
        "serviceThreads": registry_payload.get("threads", []),
        "assignmentSummary": {
            "count": len([row for row in (assignment_payload.get("rows") or []) if isinstance(row, dict)]),
            "open_count": len([row for row in (assignment_payload.get("rows") or []) if isinstance(row, dict) and str(row.get("status") or "").strip().lower() in DARIUS_ASSIGNMENT_QUEUE_ACTIVE_STATES]),
        },
        "updatedAt": int(time.time()),
    }
    DARIUS_EXPORT_PROJECT_MEMORY_PATH.write_text(json.dumps(project_memory, indent=2, ensure_ascii=False), encoding="utf-8")
    rules = [
        "# Darius Repo Rules",
        "",
        "- Default execution profile is `pro_only`.",
        "- Zeus orchestrates and reviews; Darius executes cloud/Codex write work.",
        "- Never remove existing features.",
        "- Respect checkout locks before editing.",
        "- Use the persistent service thread packs as the durable source of truth.",
        "- Persist only summaries, decisions, blockers, and artifact refs. No chain-of-thought.",
    ]
    DARIUS_EXPORT_REPO_RULES_PATH.write_text("\n".join(rules).strip() + "\n", encoding="utf-8")

def bootstrap_service_threads(force: bool = False) -> dict[str, Any]:
    existing = _read_json(SERVICE_THREAD_REGISTRY_PATH)
    registry_map = {}
    for row in (existing.get("threads") or []) if isinstance(existing, dict) else []:
        if isinstance(row, dict) and str(row.get("service_key") or "").strip():
            registry_map[str(row.get("service_key")).strip()] = dict(row)
    rows: list[dict[str, Any]] = []
    for service_key in SERVICE_THREAD_SERVICE_KEYS:
        blueprint = _service_thread_blueprint(service_key)
        if not blueprint:
            continue
        pack_paths = _service_thread_pack_paths(service_key)
        for key in ("rules", "memory", "tests", "must_keep_features", "ownership"):
            pack_paths[key].parent.mkdir(parents=True, exist_ok=True)
        existing_memory = _read_json(pack_paths["memory"])
        memory_payload = _service_thread_memory_payload(service_key, blueprint, existing_memory)
        ownership_payload = _service_thread_ownership_payload(service_key, blueprint)
        must_keep_payload = {"service_key": service_key, "updated_at": int(time.time()), "features": _service_thread_contract_rows(service_key)}
        if force or not pack_paths["rules"].exists():
            pack_paths["rules"].write_text(_service_thread_rules_text(service_key, blueprint), encoding="utf-8")
        if force or not pack_paths["tests"].exists():
            pack_paths["tests"].write_text(_service_thread_tests_text(service_key, blueprint), encoding="utf-8")
        _write_json(pack_paths["must_keep_features"], must_keep_payload)
        _write_json(pack_paths["ownership"], ownership_payload)
        _write_json(pack_paths["memory"], memory_payload)
        current = registry_map.get(service_key, {})
        rows.append(
            {
                "service_key": service_key,
                "display_name": str(blueprint.get("display_name") or olympus_service_display_name(str(blueprint.get("profile_key") or service_key), pretty_label(service_key))).strip(),
                "executor": str(blueprint.get("executor") or "darius").strip() or "darius",
                "thread_id": str(current.get("thread_id") or memory_payload.get("thread_id") or f"svc_{service_key.replace('-', '_')}").strip(),
                "rules_path": str(pack_paths["rules"]),
                "memory_path": str(pack_paths["memory"]),
                "tests_path": str(pack_paths["tests"]),
                "must_keep_features_path": str(pack_paths["must_keep_features"]),
                "owned_paths": ownership_payload.get("owned_paths", []),
                "checkout_root": ownership_payload.get("checkout_root"),
                "checkout_path": ownership_payload.get("checkout_path"),
                "checkout_scope_kind": ownership_payload.get("checkout_scope_kind"),
                "active_assignment_id": str(current.get("active_assignment_id") or "").strip(),
                "cooldown_until": int(current.get("cooldown_until") or 0),
                "failure_streak": int(current.get("failure_streak") or 0),
                "last_compacted_at": int(memory_payload.get("last_compacted_at") or current.get("last_compacted_at") or 0),
                "updated_at": int(time.time()),
            }
        )
    payload = {"version": "2026-03-14", "updated_at": int(time.time()), "execution_profile": current_execution_profile(), "threads": rows}
    _write_json(SERVICE_THREAD_REGISTRY_PATH, payload)
    assignments = _read_json(DARIUS_ASSIGNMENT_QUEUE_PATH)
    if not isinstance(assignments.get("rows"), list):
        assignments = _default_darius_assignment_state()
        _write_json(DARIUS_ASSIGNMENT_QUEUE_PATH, assignments)
    _export_darius_service_thread_context(payload, assignments)
    return {"status": "ok", "registry_path": str(SERVICE_THREAD_REGISTRY_PATH), "rows": rows, "threads": rows, "count": len(rows), "execution_profile": current_execution_profile()}

def load_service_thread_registry() -> dict[str, Any]:
    payload = _read_json(SERVICE_THREAD_REGISTRY_PATH)
    if not isinstance(payload.get("threads"), list) or len(payload.get("threads") or []) < len(SERVICE_THREAD_SERVICE_KEYS):
        return bootstrap_service_threads(force=False)
    payload["execution_profile"] = current_execution_profile()
    return payload

def save_service_thread_registry(payload: dict[str, Any]) -> dict[str, Any]:
    current = payload if isinstance(payload, dict) else _default_service_thread_registry()
    current["updated_at"] = int(time.time())
    current["execution_profile"] = current_execution_profile()
    _write_json(SERVICE_THREAD_REGISTRY_PATH, current)
    _export_darius_service_thread_context(current, load_darius_assignment_state())
    return current

def get_service_thread_entry(service_key: str) -> dict[str, Any]:
    wanted = str(service_key or "").strip().lower()
    if not wanted:
        return {}
    registry = load_service_thread_registry()
    for row in registry.get("threads", []) if isinstance(registry, dict) else []:
        if isinstance(row, dict) and str(row.get("service_key") or "").strip().lower() == wanted:
            return row
    return {}

def _darius_assignment_status(value: Any) -> str:
    key = str(value or "queued").strip().lower()
    return key if key in {"queued", "claimed", "running", "review", "blocked", "completed", "rejected", "cancelled"} else "queued"

def _darius_review_status(value: Any) -> str:
    key = str(value or "pending").strip().lower()
    return key if key in {"pending", "approved", "rejected", "waived"} else "pending"

def _assignment_fingerprint(service_key: str, goal: str, scope: str = "", source: str = "", project_key: str = "") -> str:
    compact_goal = re.sub(r"\s+", " ", str(goal or "").strip().lower())[:120]
    return f"{str(service_key or '').strip().lower()}::{str(project_key or '').strip().lower()}::{str(scope or '').strip().lower()}::{str(source or '').strip().lower()}::{compact_goal}"[:191]

def load_darius_assignment_state() -> dict[str, Any]:
    payload = _read_json(DARIUS_ASSIGNMENT_QUEUE_PATH)
    rows = payload.get("rows") if isinstance(payload.get("rows"), list) else None
    if rows is None:
        payload = _default_darius_assignment_state()
        _write_json(DARIUS_ASSIGNMENT_QUEUE_PATH, payload)
        rows = []
    payload["rows"] = [row for row in rows if isinstance(row, dict)]
    return payload

def save_darius_assignment_state(payload: dict[str, Any]) -> dict[str, Any]:
    current = payload if isinstance(payload, dict) else _default_darius_assignment_state()
    current["updated_at"] = int(time.time())
    current["rows"] = [row for row in (current.get("rows") or []) if isinstance(row, dict)]
    _write_json(DARIUS_ASSIGNMENT_QUEUE_PATH, current)
    _export_darius_service_thread_context(load_service_thread_registry(), current)
    return current

def list_darius_assignments(service_key: str = "", status: str = "", limit: int = 80, include_completed: bool = True) -> dict[str, Any]:
    state = load_darius_assignment_state()
    wanted_service = str(service_key or "").strip().lower()
    wanted_status = _darius_assignment_status(status) if str(status or "").strip() else ""
    rows: list[dict[str, Any]] = []
    for row in state.get("rows", []):
        if not isinstance(row, dict):
            continue
        if wanted_service and str(row.get("service_key") or "").strip().lower() != wanted_service:
            continue
        current_status = _darius_assignment_status(row.get("status"))
        if wanted_status and current_status != wanted_status:
            continue
        if not include_completed and current_status in {"completed", "rejected", "cancelled"}:
            continue
        rows.append(row)
    rows.sort(key=lambda item: (int(item.get("updated_at") or item.get("created_at") or 0), str(item.get("assignment_id") or "")), reverse=True)
    active_rows = [row for row in rows if _darius_assignment_status(row.get("status")) in DARIUS_ASSIGNMENT_QUEUE_ACTIVE_STATES]
    return {
        "status": "ok",
        "rows": rows[: max(1, min(int(limit or 80), 400))],
        "summary": {
            "count": len(rows),
            "open_count": len(active_rows),
            "blocked_count": len([row for row in rows if _darius_assignment_status(row.get("status")) == "blocked"]),
            "review_count": len([row for row in rows if _darius_assignment_status(row.get("status")) == "review"]),
        },
        "path": str(DARIUS_ASSIGNMENT_QUEUE_PATH),
    }

def _service_thread_update(service_key: str, updater):
    registry = load_service_thread_registry()
    rows = registry.get("threads", [])
    updated_rows: list[dict[str, Any]] = []
    target: dict[str, Any] = {}
    for row in rows if isinstance(rows, list) else []:
        current = dict(row) if isinstance(row, dict) else {}
        if str(current.get("service_key") or "").strip().lower() == str(service_key or "").strip().lower():
            current = updater(current) or current
            current["updated_at"] = int(time.time())
            target = current
        updated_rows.append(current)
    registry["threads"] = updated_rows
    save_service_thread_registry(registry)
    return target

def _service_thread_active_write_assignment(rows: list[dict[str, Any]], service_key: str, exclude_assignment_id: str = "") -> dict[str, Any]:
    for row in rows:
        if not isinstance(row, dict):
            continue
        if exclude_assignment_id and str(row.get("assignment_id") or "").strip() == exclude_assignment_id:
            continue
        if str(row.get("service_key") or "").strip().lower() != str(service_key or "").strip().lower():
            continue
        if not bool(row.get("allow_write", False)):
            continue
        if _darius_assignment_status(row.get("status")) in DARIUS_ASSIGNMENT_EXECUTION_STATES:
            return row
    return {}

def _global_active_write_assignments(rows: list[dict[str, Any]], exclude_assignment_id: str = "") -> list[dict[str, Any]]:
    active: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        if exclude_assignment_id and str(row.get("assignment_id") or "").strip() == exclude_assignment_id:
            continue
        if not bool(row.get("allow_write", False)):
            continue
        if _darius_assignment_status(row.get("status")) in DARIUS_ASSIGNMENT_EXECUTION_STATES:
            active.append(row)
    return active

def _compact_service_thread_memory(service_key: str, assignment: dict[str, Any], note: str = "") -> dict[str, Any]:
    blueprint = _service_thread_blueprint(service_key)
    paths = _service_thread_pack_paths(service_key)
    current = _read_json(paths["memory"])
    payload = _service_thread_memory_payload(service_key, blueprint, current)
    summary_row = {
        "assignment_id": str(assignment.get("assignment_id") or "").strip(),
        "status": _darius_assignment_status(assignment.get("status")),
        "review_status": _darius_review_status(assignment.get("review_status")),
        "goal": _trim_codex_text(assignment.get("goal", ""), 320),
        "summary": _trim_codex_text(assignment.get("result_summary", "") or assignment.get("goal", ""), 900),
        "artifacts": [str(item).strip() for item in (assignment.get("artifacts") or []) if str(item).strip()][:20],
        "updated_at": int(time.time()),
        "note": _trim_codex_text(note, 320),
    }
    payload["recent_summaries"] = ([row for row in (payload.get("recent_summaries") or []) if isinstance(row, dict)] + [summary_row])[-24:]
    if summary_row["status"] in {"blocked", "rejected"}:
        payload["blockers"] = ([row for row in (payload.get("blockers") or []) if isinstance(row, dict)] + [summary_row])[-24:]
    payload["last_compacted_at"] = int(time.time())
    payload["updated_at"] = int(time.time())
    _write_json(paths["memory"], payload)
    _service_thread_update(
        service_key,
        lambda row: {
            **row,
            "last_compacted_at": payload["last_compacted_at"],
            "active_assignment_id": "" if str(row.get("active_assignment_id") or "").strip() == str(assignment.get("assignment_id") or "").strip() else str(row.get("active_assignment_id") or "").strip(),
        },
    )
    return payload

async def run_memory_maintenance(
    *,
    reason: str = "",
    force: bool = False,
    compact_threads: bool = True,
    bootstrap_threads: bool = True,
    rebuild_atlas: bool = True,
    save_memory_note: bool = True,
) -> dict[str, Any]:
    ts = int(time.time())
    registry = bootstrap_service_threads(force=force) if bootstrap_threads else load_service_thread_registry()
    maintenance_rows: list[dict[str, Any]] = []
    for entry in registry.get("threads", []) if isinstance(registry, dict) and compact_threads else []:
        if not isinstance(entry, dict):
            continue
        service_key = str(entry.get("service_key") or "").strip().lower()
        if not service_key:
            continue
        blueprint = _service_thread_blueprint(service_key)
        if not blueprint:
            continue
        paths = _service_thread_pack_paths(service_key)
        current = _read_json(paths["memory"])
        payload = _service_thread_memory_payload(service_key, blueprint, current)
        decision_row = {
            "ts": ts,
            "decision": "daily_memory_maintenance",
            "reason": str(reason or "daily_memory_maintenance").strip()[:240] or "daily_memory_maintenance",
            "summary": "Service thread memory compacted and normalized.",
            "source": "assistant-core",
        }
        payload["decisions"] = ([row for row in (payload.get("decisions") or []) if isinstance(row, dict)] + [decision_row])[-24:]
        payload["last_compacted_at"] = ts
        payload["updated_at"] = ts
        _write_json(paths["memory"], payload)
        _service_thread_update(
            service_key,
            lambda row: {
                **row,
                "last_compacted_at": ts,
                "updated_at": ts,
            },
        )
        maintenance_rows.append(
            {
                "service_key": service_key,
                "display_name": str(entry.get("display_name") or pretty_label(service_key)).strip() or pretty_label(service_key),
                "recent_summaries": len(payload.get("recent_summaries") or []),
                "blockers": len(payload.get("blockers") or []),
                "decisions": len(payload.get("decisions") or []),
                "memory_path": str(paths["memory"]),
                "last_compacted_at": ts,
            }
        )
    atlas_summary: dict[str, Any]
    if rebuild_atlas:
        try:
            atlas = rebuild_workspace_atlas("")
            atlas_summary = {
                "status": "ok",
                "atlas_path": str(atlas.get("atlas_path") or ""),
                "json_path": str(atlas.get("json_path") or ""),
                "project_count": int(atlas.get("project_count") or 0),
            }
        except Exception as exc:
            atlas_summary = {"status": "error", "detail": str(exc)}
    else:
        atlas_summary = {"status": "skipped"}
    receipt = {
        "status": "ok",
        "reason": str(reason or "daily_memory_maintenance").strip()[:240] or "daily_memory_maintenance",
        "executed_at": ts,
        "service_thread_count": len(maintenance_rows),
        "service_threads": maintenance_rows,
        "compact_service_threads": bool(compact_threads),
        "bootstrap_threads": bool(bootstrap_threads),
        "rebuild_workspace_atlas": bool(rebuild_atlas),
        "atlas": atlas_summary,
    }
    receipt_path = MEMORY_MAINTENANCE_ROOT / f"maintenance-{ts}.json"
    _write_json(receipt_path, receipt)
    receipt["receipt_path"] = str(receipt_path)
    summary = (
        f"Memory maintenance compacted {len(maintenance_rows)} service threads; "
        f"atlas={atlas_summary.get('status', 'unknown')}."
    )
    activity_log("assistant-core", "memory_maintenance", "ok", "Memory maintenance completed", summary, receipt)
    cognition_log("assistant-core", "core", "memory", "Memory maintenance completed", summary, receipt)
    _append_runtime_diagnostic_receipt(
        {
            "event": "memory_maintenance",
            "stage": "daily_compaction",
            "severity": "warn" if atlas_summary.get("status") == "error" else "info",
            "scene": "assistant-core",
            "route": "memory/maintenance/run",
            "connection": {"service_thread_count": len(maintenance_rows)},
            "summary": summary,
            "details": json.dumps(_json_ready(receipt), ensure_ascii=False),
        }
    )
    if save_memory_note:
        await save_memory(
            "MEMORY MAINTENANCE\n"
            f"reason={receipt['reason']}\n"
            f"service_thread_count={len(maintenance_rows)}\n"
            f"atlas_status={atlas_summary.get('status', 'unknown')}\n"
            f"receipt={receipt_path}"
        )
    return receipt

def _apply_service_thread_backoff(service_key: str, failed: bool) -> dict[str, Any]:
    def updater(row: dict[str, Any]) -> dict[str, Any]:
        streak = int(row.get("failure_streak") or 0)
        if failed:
            streak += 1
            cooldown = min(DARIUS_ASSIGNMENT_MAX_BACKOFF_SEC, DARIUS_ASSIGNMENT_BASE_COOLDOWN_SEC * max(1, 2 ** max(0, streak - 1)))
            row["cooldown_until"] = int(time.time()) + int(cooldown)
            row["failure_streak"] = streak
        else:
            row["cooldown_until"] = 0
            row["failure_streak"] = 0
        return row
    return _service_thread_update(service_key, updater)

def _ensure_darius_assignment_checkout(assignment: dict[str, Any], entry: dict[str, Any], agent_key: str = "") -> dict[str, Any]:
    if not bool(assignment.get("allow_write", False)):
        return {"status": "not_required"}
    checkout_path = str(entry.get("checkout_path") or "").strip()
    if not checkout_path:
        return {"status": "not_required"}
    actor = agent_key or f"darius_assignment:{str(assignment.get('assignment_id') or '').strip()}"
    result = request_file_checkout(
        "workspace",
        checkout_path,
        agent_key=actor,
        session_id=str(assignment.get("thread_id") or entry.get("thread_id") or "").strip(),
        note=str(assignment.get("goal") or entry.get("display_name") or "").strip()[:600],
        scope_kind=str(entry.get("checkout_scope_kind") or "tree").strip() or "tree",
        lease_seconds=DARIUS_ASSIGNMENT_DEFAULT_LEASE_SEC,
    )
    if result.get("lock") and isinstance(result.get("lock"), dict):
        assignment["checkout_lock_id"] = str(result.get("lock", {}).get("checkout_id") or "").strip()
    return result

def _release_darius_assignment_checkout(assignment: dict[str, Any], entry: dict[str, Any], agent_key: str = ""):
    if not bool(assignment.get("allow_write", False)):
        return
    checkout_path = str(entry.get("checkout_path") or "").strip()
    if not checkout_path:
        return
    actor = agent_key or f"darius_assignment:{str(assignment.get('assignment_id') or '').strip()}"
    try:
        release_file_checkout(
            "workspace",
            checkout_path,
            checkout_id=str(assignment.get("checkout_lock_id") or "").strip(),
            agent_key=actor,
            completion_note=str(assignment.get("result_summary") or assignment.get("status") or "").strip()[:600],
            scope_kind=str(entry.get("checkout_scope_kind") or "tree").strip() or "tree",
        )
    except Exception:
        pass

def _codex_request_service_key(project_key: str = "", workdir: str = "", goal: str = "") -> str:
    normalized_project = normalize_project_key(project_key)
    profile = olympus_project_profile_for_workspace_project(normalized_project) if normalized_project else {}
    routing_rules = profile.get("routing_rules", {}) if isinstance(profile, dict) else {}
    blob = "\n".join([str(project_key or ""), str(workdir or ""), str(goal or "")]).lower()
    allow_discord_lane = any(
        marker in blob
        for marker in (
            "discord lane allowed: true",
            "allow_discord_lane=true",
            "community_guild_bootstrap",
            "wave-7-community",
        )
    )
    skip_discord_route = bool(routing_rules.get("mission_work_must_skip_discord")) and not allow_discord_lane
    if "admin-api" in blob or "/admin/" in blob:
        return "admin-api"
    if "self-upgrade" in blob or "upgrade-agent" in blob or "proposal/apply" in blob:
        return "lumi-upgrade-agent"
    if skip_discord_route:
        if "codenamedarius" in blob or "unity" in blob or "darius" in blob:
            return "darius"
        if "luminax-ui" in blob or "mount olympus" in blob or "welcome2olympus" in blob or "sites/" in blob:
            return "mount-olympus-ui"
        return str(routing_rules.get("fallback_executor") or "assistant-core").strip() or "assistant-core"
    if "discord-ops-bot" in blob or "discord guild" in blob or "community guild" in blob or "hermes ops" in blob:
        return "discord-ops-bot"
    if "discord" in blob or "hermes" in blob or "luminax" in blob:
        return "discord-bot"
    if "codenamedarius" in blob or "unity" in blob or "darius" in blob:
        return "darius"
    if "luminax-ui" in blob or "mount olympus" in blob or "welcome2olympus" in blob or "sites/" in blob:
        return "mount-olympus-ui"
    return "assistant-core"

def build_execution_profile_payload() -> dict[str, Any]:
    bootstrap_service_threads(force=False)
    queue = list_darius_assignments(include_completed=False)
    routes = _load_darius_routes()
    exec_error = current_codex_cli_exec_error()
    login_ready = bool(CODEX_CLI_AUTH_READY)
    registry = load_service_thread_registry()
    return {
        "status": "ok",
        "execution_profile": current_execution_profile(),
        "active_executor": current_active_executor(),
        "fallback_executor": current_fallback_executor(),
        "recommended_executor": current_recommended_executor(),
        "local_models": local_model_runtime_summary(),
        "codex": {
            "login_ready": login_ready,
            "exec_ready": login_ready and bool(CODEX_CLI_EXEC_READY) and not bool(exec_error),
            "exec_error": exec_error or None,
            "auth_error": CODEX_CLI_AUTH_LAST_ERROR[:300] or None,
            "auth_mode": CODEX_CLI_AUTH_LAST_MODE or None,
        },
        "darius": {
            "available": bool(DARIUS_EXPORT_ROOT.exists()) or bool(routes),
            "route_count": len([row for row in routes.values() if isinstance(row, dict)]),
            "queue_summary": queue.get("summary", {}),
        },
        "service_threads": {
            "count": len(registry.get("threads", [])),
            "cooldown_count": len([row for row in registry.get("threads", []) if isinstance(row, dict) and int(row.get("cooldown_until") or 0) > int(time.time())]),
        },
        "runtime_policy": load_runtime_policy(),
    }

def create_darius_assignment(
    *,
    service_key: str,
    project_key: str = "",
    goal: str,
    scope: str = "implement",
    requested_by: str = "operator",
    source: str = "assistant-core",
    allow_write: bool = True,
    priority: int = 50,
    thread_id: str = "",
    meta: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    bootstrap_service_threads(force=False)
    normalized_service = str(service_key or "").strip().lower()
    if normalized_service not in SERVICE_THREAD_SERVICE_KEYS:
        raise HTTPException(status_code=400, detail="Invalid service_key for Darius assignment")
    safe_goal = str(goal or "").strip()
    if not safe_goal:
        raise HTTPException(status_code=400, detail="goal is required")
    entry = get_service_thread_entry(normalized_service)
    if not entry:
        raise HTTPException(status_code=404, detail="Service thread not found")
    now_ts = int(time.time())
    cooldown_until = int(entry.get("cooldown_until") or 0)
    fingerprint = _assignment_fingerprint(normalized_service, safe_goal, scope, source, project_key)
    state = load_darius_assignment_state()
    rows = state.get("rows", [])
    duplicate = next(
        (
            row
            for row in rows
            if isinstance(row, dict)
            and str(row.get("fingerprint") or "").strip() == fingerprint
            and _darius_assignment_status(row.get("status")) in DARIUS_ASSIGNMENT_QUEUE_ACTIVE_STATES
        ),
        None,
    )
    if duplicate:
        return {"status": "deduped", "assignment": duplicate, "service_thread": entry}
    if cooldown_until > now_ts:
        upsert_system_incident(
            f"darius-assignment-cooldown:{normalized_service}",
            source_service="assistant-core",
            fingerprint=f"darius-assignment-cooldown:{normalized_service}",
            severity="medium",
            summary=f"{entry.get('display_name') or normalized_service} is cooling down after a failed run",
            detail=f"Assignment suppressed until {datetime.fromtimestamp(cooldown_until).isoformat()} for service {normalized_service}.",
            feature_ids=["codex_bridge"],
            evidence={"service_key": normalized_service, "cooldown_until": cooldown_until},
        )
        return {
            "status": "suppressed",
            "service_thread": entry,
            "cooldown_until": cooldown_until,
            "detail": f"{entry.get('display_name') or normalized_service} is cooling down before the next Darius run.",
        }
    assignment = {
        "assignment_id": f"darius_assignment_{uuid.uuid4().hex[:12]}",
        "service_key": normalized_service,
        "project_key": normalize_project_key(project_key),
        "goal": safe_goal,
        "scope": str(scope or "implement").strip() or "implement",
        "requested_by": str(requested_by or "operator").strip() or "operator",
        "source": str(source or "assistant-core").strip() or "assistant-core",
        "allow_write": bool(allow_write),
        "checkout_lock_id": "",
        "thread_id": str(thread_id or entry.get("thread_id") or "").strip(),
        "status": "queued",
        "priority": max(1, min(int(priority or 50), 100)),
        "created_at": now_ts,
        "updated_at": now_ts,
        "result_summary": "",
        "artifacts": [],
        "review_status": "pending",
        "verification_summary": "",
        "fingerprint": fingerprint,
        "meta": meta if isinstance(meta, dict) else {},
    }
    if bool(allow_write):
        checkout = _ensure_darius_assignment_checkout(assignment, entry)
        checkout_status = str(checkout.get("status") or "").strip().lower()
        if checkout_status in {"blocked", "queued"}:
            assignment["status"] = "blocked"
            assignment["result_summary"] = str(checkout.get("detail") or "Write checkout is blocked").strip()
            upsert_system_incident(
                f"darius-assignment-checkout:{normalized_service}",
                source_service="assistant-core",
                fingerprint=f"darius-assignment-checkout:{normalized_service}",
                severity="medium",
                summary=f"Darius assignment checkout blocked for {normalized_service}",
                detail=assignment["result_summary"],
                feature_ids=["codex_bridge", "file_checkout"],
                evidence={"assignment_id": assignment["assignment_id"], "checkout": checkout},
            )
    rows.append(assignment)
    state["rows"] = rows
    save_darius_assignment_state(state)
    return {"status": "ok", "assignment": assignment, "service_thread": entry}

def claim_darius_assignment(assignment_id: str, *, agent_id: str, thread_id: str = "", local_thread_id: str = "", project_key: str = "") -> dict[str, Any]:
    safe_assignment_id = str(assignment_id or "").strip()
    if not safe_assignment_id:
        raise HTTPException(status_code=400, detail="assignment_id is required")
    state = load_darius_assignment_state()
    rows = state.get("rows", [])
    target = next((row for row in rows if isinstance(row, dict) and str(row.get("assignment_id") or "").strip() == safe_assignment_id), None)
    if not target:
        raise HTTPException(status_code=404, detail="Darius assignment not found")
    entry = get_service_thread_entry(target.get("service_key"))
    if not entry:
        raise HTTPException(status_code=404, detail="Service thread not found for assignment")
    if bool(target.get("allow_write", False)):
        same_service_active = _service_thread_active_write_assignment(rows, str(target.get("service_key") or "").strip(), exclude_assignment_id=safe_assignment_id)
        if same_service_active:
            raise HTTPException(status_code=409, detail=f"Another write assignment is already active for {target.get('service_key')}")
        max_global = int((load_runtime_policy().get("darius_queue") or {}).get("max_parallel_cloud_runs") or 1)
        active_global = _global_active_write_assignments(rows, exclude_assignment_id=safe_assignment_id)
        if len(active_global) >= max_global:
            raise HTTPException(status_code=409, detail="The global Darius cloud execution lane is already busy")
        checkout = _ensure_darius_assignment_checkout(target, entry, agent_key=f"darius_assignment:{safe_assignment_id}")
        if str(checkout.get("status") or "").strip().lower() not in {"checked_out", "not_required"}:
            target["status"] = "blocked"
            target["updated_at"] = int(time.time())
            target["result_summary"] = str(checkout.get("detail") or "Checkout could not be acquired").strip()
            save_darius_assignment_state(state)
            raise HTTPException(status_code=409, detail=target["result_summary"] or "Checkout could not be acquired")
    target["status"] = "claimed"
    target["updated_at"] = int(time.time())
    target["claimed_by"] = str(agent_id or "").strip()
    if thread_id.strip():
        target["thread_id"] = thread_id.strip()
    if local_thread_id.strip():
        target["local_thread_id"] = local_thread_id.strip()
    _service_thread_update(
        str(target.get("service_key") or "").strip(),
        lambda row: {**row, "active_assignment_id": safe_assignment_id, "thread_id": str(target.get("thread_id") or row.get("thread_id") or "").strip()},
    )
    save_darius_assignment_state(state)
    return {"status": "ok", "assignment": target, "service_thread": entry, "pack": _service_thread_pack_preview(str(target.get("service_key") or "").strip())}

def complete_darius_assignment(
    assignment_id: str,
    *,
    agent_id: str = "",
    status: str = "review",
    summary: str = "",
    verification_summary: str = "",
    artifact_paths: Optional[list[str]] = None,
    review_status: str = "pending",
    message: str = "",
) -> dict[str, Any]:
    safe_assignment_id = str(assignment_id or "").strip()
    state = load_darius_assignment_state()
    rows = state.get("rows", [])
    target = next((row for row in rows if isinstance(row, dict) and str(row.get("assignment_id") or "").strip() == safe_assignment_id), None)
    if not target:
        raise HTTPException(status_code=404, detail="Darius assignment not found")
    current_status = _darius_assignment_status(target.get("status"))
    if current_status not in {"claimed", "running"}:
        raise HTTPException(status_code=409, detail="Darius assignment must be claimed or running before completion")
    current_claimed_by = str(target.get("claimed_by") or "").strip()
    requested_by = str(agent_id or "").strip()
    if current_claimed_by and requested_by and requested_by != current_claimed_by:
        raise HTTPException(status_code=409, detail="Darius assignment is claimed by a different agent")
    next_status = _darius_assignment_status(status)
    if next_status in {"queued", "claimed", "running"}:
        next_status = "review"
    target["status"] = next_status
    target["updated_at"] = int(time.time())
    target["claimed_by"] = str(agent_id or target.get("claimed_by") or "").strip()
    target["result_summary"] = str(summary or message or target.get("result_summary") or "").strip()
    target["verification_summary"] = str(verification_summary or target.get("verification_summary") or "").strip()
    target["artifacts"] = [str(item).strip() for item in (artifact_paths or target.get("artifacts") or []) if str(item).strip()][:40]
    target["review_status"] = _darius_review_status(review_status)
    target["completed_at"] = int(time.time())
    save_darius_assignment_state(state)
    entry = get_service_thread_entry(str(target.get("service_key") or "").strip())
    _release_darius_assignment_checkout(target, entry, agent_key=f"darius_assignment:{safe_assignment_id}")
    _apply_service_thread_backoff(str(target.get("service_key") or "").strip(), failed=next_status in {"blocked", "rejected"})
    memory = _compact_service_thread_memory(str(target.get("service_key") or "").strip(), target, note="Darius execution summary captured.")
    return {"status": "ok", "assignment": target, "service_thread": entry, "memory": memory}

def reject_darius_assignment(assignment_id: str, *, agent_id: str = "", reason: str = "", review_status: str = "rejected") -> dict[str, Any]:
    safe_assignment_id = str(assignment_id or "").strip()
    state = load_darius_assignment_state()
    rows = state.get("rows", [])
    target = next((row for row in rows if isinstance(row, dict) and str(row.get("assignment_id") or "").strip() == safe_assignment_id), None)
    if not target:
        raise HTTPException(status_code=404, detail="Darius assignment not found")
    target["status"] = "rejected"
    target["updated_at"] = int(time.time())
    target["review_status"] = _darius_review_status(review_status)
    target["result_summary"] = str(reason or target.get("result_summary") or "Rejected").strip()
    target["claimed_by"] = str(agent_id or target.get("claimed_by") or "").strip()
    save_darius_assignment_state(state)
    entry = get_service_thread_entry(str(target.get("service_key") or "").strip())
    _release_darius_assignment_checkout(target, entry, agent_key=f"darius_assignment:{safe_assignment_id}")
    _apply_service_thread_backoff(str(target.get("service_key") or "").strip(), failed=True)
    memory = _compact_service_thread_memory(str(target.get("service_key") or "").strip(), target, note="Assignment rejected before adoption.")
    return {"status": "ok", "assignment": target, "service_thread": entry, "memory": memory}

def workspace_registry_project(project_key: str) -> dict[str, Any]:
    normalized = normalize_project_key(project_key)
    if not normalized:
        return {}
    registry = load_workspace_registry_profile()
    for row in registry.get("projects", []) if isinstance(registry.get("projects"), list) else []:
        if not isinstance(row, dict):
            continue
        if normalize_project_key(row.get("project_key")) == normalized:
            return row
    return {}

def olympus_role_profile(role_key: str) -> dict[str, Any]:
    identity = load_olympus_identity_profile()
    roles = identity.get("roles") if isinstance(identity.get("roles"), dict) else {}
    row = roles.get(str(role_key or "").strip()) if isinstance(roles.get(str(role_key or "").strip()), dict) else {}
    return row if isinstance(row, dict) else {}

def olympus_job_templates_path() -> Path:
    identity = load_olympus_identity_profile()
    configured = str(identity.get("job_templates_path") or "config/olympus-job-templates.json").strip()
    candidate = Path(configured)
    if candidate.is_absolute():
        return candidate
    return (WORKSPACE_ROOT / configured.replace("\\", "/")).resolve()

def load_olympus_job_templates_profile() -> dict[str, Any]:
    default = {"version": "2026-03-13", "templates": []}
    path = olympus_job_templates_path()
    disk = _read_json(path)
    payload = {**default, **(disk if isinstance(disk, dict) else {})}
    if not isinstance(payload.get("templates"), list):
        payload["templates"] = []
    if disk != payload:
        _write_json(path, payload)
    return payload

def olympus_job_template_profile(template_key: str) -> dict[str, Any]:
    normalized = str(template_key or "").strip().lower()
    if not normalized:
        return {}
    for row in load_olympus_job_templates_profile().get("templates", []):
        if not isinstance(row, dict):
            continue
        key = str(row.get("key") or "").strip().lower()
        aliases = [str(alias or "").strip().lower() for alias in row.get("legacy_aliases", [])] if isinstance(row.get("legacy_aliases"), list) else []
        if key == normalized or normalized in aliases:
            return row
    return {}

def load_project_starter_templates_profile() -> dict[str, Any]:
    default = {
        "version": PROJECT_CODEX_TEMPLATE_VERSION,
        "codex_thread_defaults": {
            "required": True,
            "template_version": PROJECT_CODEX_TEMPLATE_VERSION,
            "structure": ["thread.json", "instructions.md", "suggestions/", "receipts/", "artifacts/"],
            "worker_mandate": {
                "no_slop_no_filler": True,
                "self_correction_required": True,
                "review_first": True,
                "documentation_hygiene_required": True,
            },
        },
        "templates": [],
    }
    disk = _read_json(PROJECT_STARTER_TEMPLATES_PATH)
    payload = {**default, **(disk if isinstance(disk, dict) else {})}
    codex_defaults = payload.get("codex_thread_defaults") if isinstance(payload.get("codex_thread_defaults"), dict) else {}
    payload["codex_thread_defaults"] = {
        **default["codex_thread_defaults"],
        **codex_defaults,
        "worker_mandate": {
            **default["codex_thread_defaults"]["worker_mandate"],
            **(codex_defaults.get("worker_mandate") if isinstance(codex_defaults.get("worker_mandate"), dict) else {}),
        },
    }
    if not isinstance(payload.get("templates"), list):
        payload["templates"] = []
    if disk != payload:
        _write_json(PROJECT_STARTER_TEMPLATES_PATH, payload)
    return payload

