def enforce_worker_pause(action: str) -> dict[str, Any]:
    policy = load_runtime_policy()
    if bool(policy.get("workers_paused", False)):
        raise HTTPException(
            status_code=409,
            detail=f"{action} paused. {str(policy.get('worker_pause_reason') or 'Worker pause is active.').strip()}",
        )
    return policy

def _runtime_rate_window_key(bucket: str, seconds: int, now_ts: int | None = None) -> tuple[str, int]:
    now_value = int(now_ts or time.time())
    window = max(60, int(seconds or 60))
    anchor = now_value - (now_value % window)
    return f"runtime_rate:{bucket}:{window}:{anchor}", anchor

def _runtime_rate_counter(bucket: str, seconds: int, limit: int) -> dict[str, Any]:
    try:
        key, anchor = _runtime_rate_window_key(bucket, seconds)
        count = int(redis_client.incr(key))
        if count == 1:
            redis_client.expire(key, max(int(seconds or 60) + 60, 120))
        remaining = max(0, int(limit or 0) - count)
        reset_at = anchor + max(60, int(seconds or 60))
        return {"count": count, "limit": int(limit or 0), "remaining": remaining, "reset_at": reset_at}
    except Exception as exc:
        raise HTTPException(status_code=503, detail=f"Runtime rate limiter unavailable: {exc}") from exc

def enforce_runtime_rate_limit(kind: str) -> dict[str, Any]:
    policy = load_runtime_policy()
    limits = policy.get("rate_limits") if isinstance(policy.get("rate_limits"), dict) else {}
    window_specs: list[tuple[int, int]] = []
    if kind == "codex":
        window_specs = [
            (3600, int(limits.get("codex_runs_per_hour", 12) or 12)),
            (600, int(limits.get("codex_runs_per_10_min", 3) or 3)),
        ]
    elif kind == "research":
        window_specs = [
            (3600, int(limits.get("research_jobs_per_hour", 8) or 8)),
            (600, int(limits.get("research_jobs_per_10_min", 2) or 2)),
        ]
    counters: list[dict[str, Any]] = []
    for seconds, limit in window_specs:
        counter = _runtime_rate_counter(kind, seconds, limit)
        counter["window_seconds"] = seconds
        counters.append(counter)
        if int(counter.get("count") or 0) > int(counter.get("limit") or 0):
            wait_seconds = max(1, int(counter.get("reset_at") or time.time()) - int(time.time()))
            raise HTTPException(
                status_code=429,
                detail=f"{kind} rate limit reached for the current {seconds}-second window. Retry in about {wait_seconds} seconds.",
            )
    return {"status": "ok", "kind": kind, "counters": counters}

def _codex_scope_model_key(scope: str, allow_write: bool) -> str:
    if not allow_write:
        return "readonly"
    lowered = str(scope or "").strip().lower()
    if lowered in {"inspect", "review", "audit"}:
        return "review"
    if lowered in {"repair", "fix", "hotfix", "regression"}:
        return "repair"
    return "implement"

def select_codex_model(scope: str, allow_write: bool, explicit_model: str = "") -> str:
    requested = str(explicit_model or "").strip()
    if requested and _is_allowed_cloud_model(requested):
        return requested
    policy = load_runtime_policy()
    codex_models = policy.get("codex_models") if isinstance(policy.get("codex_models"), dict) else {}
    key = _codex_scope_model_key(scope, allow_write)
    selected = str(codex_models.get(key) or "").strip()
    return selected if _is_allowed_cloud_model(selected) else (OPENAI_CHAT_MODEL_CODER or "gpt-5.5")

def enforce_maintenance_guard(
    action: str,
    *,
    write_intent: bool = False,
    service_action: bool = False,
    self_apply: bool = False,
) -> dict[str, Any]:
    state = load_maintenance_mode()
    policy = state.get("policy") if isinstance(state.get("policy"), dict) else _maintenance_policy(state.get("mode", "normal"))
    mode = str(state.get("mode") or "normal").strip().lower()
    blocked = False
    if write_intent and not bool(policy.get("write_allowed", False)):
        blocked = True
    if service_action and not bool(policy.get("service_actions_allowed", False)):
        blocked = True
    if self_apply and not bool(policy.get("self_apply_allowed", False)):
        blocked = True
    if blocked:
        raise HTTPException(
            status_code=409,
            detail=f"{action} blocked while maintenance mode '{mode}' is active. {policy.get('description', '').strip()}",
        )
    return state

def _parse_route_catalog_from_source(rel_path: str) -> set[str]:
    path = _first_existing_workspace_path(rel_path)
    if not path or not path.exists():
        return set()
    try:
        text = path.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return set()
    return {
        match.group(1).strip()
        for match in re.finditer(r'@app\.(?:get|post|put|delete|patch)\("([^"]+)"', text)
        if str(match.group(1) or "").strip()
    }

def _compose_service_catalog() -> set[str]:
    path = _first_existing_workspace_compose_manifest()
    if not path or not path.exists():
        return set()
    try:
        text = path.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return set()
    return {
        match.group(1).strip()
        for match in re.finditer(r"(?m)^\s{2}([A-Za-z0-9_-]+):\s*$", text)
        if str(match.group(1) or "").strip()
    }

def _feature_contract_checks(
    feature: dict[str, Any],
    assistant_routes: set[str],
    admin_routes: set[str],
    compose_services: set[str],
    file_cache: dict[str, str],
) -> dict[str, Any]:
    checks: list[dict[str, Any]] = []
    for route in feature.get("assistant_routes", []) if isinstance(feature.get("assistant_routes"), list) else []:
        route_path = str(route or "").strip()
        if not route_path:
            continue
        checks.append({"kind": "assistant_route", "target": route_path, "status": "ok" if route_path in assistant_routes else "missing"})
    for route in feature.get("admin_routes", []) if isinstance(feature.get("admin_routes"), list) else []:
        route_path = str(route or "").strip()
        if not route_path:
            continue
        checks.append({"kind": "admin_route", "target": route_path, "status": "ok" if route_path in admin_routes else "missing"})
    for service in feature.get("compose_services", []) if isinstance(feature.get("compose_services"), list) else []:
        service_name = str(service or "").strip()
        if not service_name:
            continue
        checks.append({"kind": "compose_service", "target": service_name, "status": "ok" if service_name in compose_services else "missing"})
    for marker in feature.get("ui_markers", []) if isinstance(feature.get("ui_markers"), list) else []:
        if not isinstance(marker, dict):
            continue
        rel_path = str(marker.get("path") or "").strip()
        pattern = str(marker.get("pattern") or "").strip()
        if not rel_path or not pattern:
            continue
        source_path = _first_existing_workspace_path(rel_path)
        cache_key = str(source_path) if source_path else rel_path
        if cache_key not in file_cache:
            try:
                file_cache[cache_key] = source_path.read_text(encoding="utf-8", errors="ignore") if source_path else ""
            except Exception:
                file_cache[cache_key] = ""
        checks.append(
            {
                "kind": "ui_marker",
                "target": f"{rel_path} :: {pattern}",
                "status": "ok" if pattern in file_cache.get(cache_key, "") else "missing",
            }
        )
    missing = [row for row in checks if row.get("status") != "ok"]
    return {
        "id": str(feature.get("id") or "").strip(),
        "name": str(feature.get("name") or "").strip(),
        "must_keep": bool(feature.get("must_keep", True)),
        "status": "ok" if not missing else "degraded",
        "missing_checks": missing,
        "checks": checks,
        "notes": str(feature.get("notes") or "").strip(),
    }

def verify_feature_contracts(feature_id: str = "") -> dict[str, Any]:
    contracts = load_feature_contracts()
    filter_id = str(feature_id or "").strip().lower()
    assistant_routes = {str(getattr(route, "path", "") or "").strip() for route in app.routes if str(getattr(route, "path", "") or "").strip()}
    admin_routes = _parse_route_catalog_from_source("admin-api/main.py")
    compose_services = _compose_service_catalog()
    file_cache: dict[str, str] = {}
    rows: list[dict[str, Any]] = []
    for feature in contracts.get("features", []) if isinstance(contracts.get("features"), list) else []:
        if not isinstance(feature, dict):
            continue
        current_id = str(feature.get("id") or "").strip().lower()
        if filter_id and current_id != filter_id:
            continue
        rows.append(_feature_contract_checks(feature, assistant_routes, admin_routes, compose_services, file_cache))
    degraded = [row for row in rows if row.get("status") != "ok"]
    missing_checks = sum(len(row.get("missing_checks") or []) for row in rows)
    return {
        "status": "ok" if not degraded else "degraded",
        "summary": {
            "feature_count": len(rows),
            "preserved_count": len([row for row in rows if row.get("status") == "ok"]),
            "degraded_count": len(degraded),
            "missing_check_count": missing_checks,
            "verified_at": int(time.time()),
        },
        "rows": rows,
        "path": str(FEATURE_CONTRACT_PATH),
    }

def infer_incident_feature_ids(source_service: str, contracts: Optional[dict[str, Any]] = None) -> list[str]:
    target_service = str(source_service or "").strip()
    if not target_service:
        return []
    current = contracts or load_feature_contracts()
    feature_ids: list[str] = []
    for feature in current.get("features", []) if isinstance(current.get("features"), list) else []:
        if not isinstance(feature, dict):
            continue
        services = {
            str(name or "").strip()
            for name in feature.get("compose_services", [])
            if isinstance(feature.get("compose_services"), list) and str(name or "").strip()
        }
        if target_service in services:
            feature_ids.append(str(feature.get("id") or "").strip())
    return [feature_id for feature_id in feature_ids if feature_id][:12]

def _truncate_text(text: Any, max_chars: int) -> str:
    raw = str(text or "")
    if max_chars <= 0 or len(raw) <= max_chars:
        return raw
    keep = max(0, max_chars - 32)
    return raw[:keep].rstrip() + "\n...[truncated]"

def _read_text_preview(path: Path, max_chars: int) -> str:
    try:
        if not path.exists() or not path.is_file():
            return ""
        with open(path, "r", encoding="utf-8", errors="ignore") as handle:
            return handle.read(max_chars)
    except Exception:
        return ""

def _prune_files(root: Path, pattern: str, keep: int):
    rows = sorted(root.glob(pattern), key=lambda p: p.stat().st_mtime, reverse=True)
    for item in rows[max(1, keep):]:
        try:
            item.unlink()
        except Exception:
            continue

def _value_present(value: Any) -> bool:
    return value not in (None, "", [], {})

def load_skills_registry_entries() -> list[dict[str, Any]]:
    data = _read_json(SKILL_REGISTRY_PATH)
    raw = data.get("skills", []) if isinstance(data, dict) else []
    out: list[dict[str, Any]] = []
    if not isinstance(raw, list):
        return out
    for item in raw[:600]:
        if isinstance(item, dict):
            key = str(item.get("key", "")).strip() or str(item.get("name", "")).strip()
            if not key:
                continue
            out.append(
                {
                    "key": key,
                    "description": str(item.get("description", "")).strip(),
                    "status": str(item.get("status", "active")).strip().lower() or "active",
                    "source": "skills_registry",
                    "owner": str(item.get("owner", "")).strip(),
                    "notes": str(item.get("notes", "")).strip(),
                }
            )
        else:
            key = str(item).strip()
            if key:
                out.append({"key": key, "description": "", "status": "active", "source": "skills_registry", "owner": "", "notes": ""})
    return out

def load_planned_skill_memory() -> list[dict[str, Any]]:
    data = _read_json(PLANNED_SKILL_MEMORY_PATH)
    raw = data.get("planned_skills", []) if isinstance(data, dict) else []
    out: list[dict[str, Any]] = []
    if not isinstance(raw, list):
        return out
    for item in raw[:600]:
        if not isinstance(item, dict):
            continue
        key = str(item.get("key", "")).strip()
        if not key:
            continue
        status = str(item.get("status", "planned")).strip().lower() or "planned"
        if status in {"active", "ready"}:
            status = "planned"
        out.append(
            {
                "key": key,
                "description": str(item.get("description", "")).strip(),
                "status": status,
                "source": "planned_memory",
                "owner": str(item.get("owner", "")).strip(),
                "notes": str(item.get("notes", "")).strip(),
                "updated_at": int(item.get("updated_at", 0) or 0),
            }
        )
    return out

def save_planned_skill_memory(rows: list[dict[str, Any]]):
    payload = {"updated_at": int(time.time()), "planned_skills": rows[:2000]}
    _write_json(PLANNED_SKILL_MEMORY_PATH, payload)

def merge_skill_views() -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    merged: dict[str, dict[str, Any]] = {}
    for item in load_skills_registry_entries() + load_planned_skill_memory():
        key = str(item.get("key", "")).strip()
        if not key:
            continue
        current = merged.get(key)
        if current is None:
            merged[key] = item
            continue
        current_status = str(current.get("status", "")).strip().lower()
        incoming_status = str(item.get("status", "")).strip().lower()
        # Prefer active/ready entries over planned placeholders.
        current_rank = 2 if current_status in {"active", "ready", "available"} else 1
        incoming_rank = 2 if incoming_status in {"active", "ready", "available"} else 1
        if incoming_rank >= current_rank:
            merged[key] = item
    skills = sorted(merged.values(), key=lambda x: x.get("key", ""))
    active = [s for s in skills if str(s.get("status", "")).strip().lower() in {"active", "ready", "available"}]
    planned = [s for s in skills if s not in active]
    return active, planned, skills

def employee_state_doc() -> dict[str, Any]:
    data = _read_json(EMPLOYEE_STATE_PATH)
    if not isinstance(data, dict):
        data = {}
    data.setdefault("active_projects", [])
    data.setdefault("agents", [])
    normalized_agents: list[dict[str, Any]] = []
    for row in data.get("agents", []):
        if isinstance(row, dict):
            normalized_agents.append(normalize_employee_agent_record(row))
    data["agents"] = normalized_agents
    queues = data.get("queues")
    if not isinstance(queues, dict):
        queues = {}
    queues.setdefault("pending_assignments", [])
    queues.setdefault("in_progress", [])
    queues.setdefault("completed", [])
    data["queues"] = queues
    return data

def write_employee_state(data: dict[str, Any]):
    _write_json(EMPLOYEE_STATE_PATH, data)

def _employee_int(value: Any, default: int = 0) -> int:
    try:
        return int(str(value).strip())
    except Exception:
        return default

def normalize_employee_agent_record(row: dict[str, Any]) -> dict[str, Any]:
    data = dict(row or {})
    now_ts = int(time.time())
    meta = data.get("meta")
    if not isinstance(meta, dict):
        meta = {}
    queue_status = data.get("queue_status")
    if not isinstance(queue_status, dict):
        queue_status = {}
    updated_at = _employee_int(data.get("updated_at"), now_ts)
    heartbeat_at = _employee_int(data.get("heartbeat_at"), updated_at)
    last_review_cycle = _employee_int(data.get("last_review_cycle"), 0)
    last_supervisor_check_at = _employee_int(data.get("last_supervisor_check_at"), 0)
    followup_due_at = _employee_int(data.get("followup_due_at"), 0)
    idle_seconds = max(0, _employee_int(data.get("idle_seconds"), 0))
    agent_key = str(data.get("agent_key") or "").strip().lower()
    project_key = normalize_project_key(data.get("project_key") or meta.get("project_key") or "")
    supervisor_key = str(data.get("supervisor_key") or meta.get("supervisor_key") or "").strip().lower()
    record = {
        "agent_key": agent_key,
        "display_name": str(data.get("display_name") or agent_key or "agent").strip() or "agent",
        "role_type": str(data.get("role_type") or "agent").strip() or "agent",
        "status": str(data.get("status") or "ready").strip() or "ready",
        "always_on": bool(data.get("always_on", data.get("full_time", False))),
        "full_time": bool(data.get("full_time", data.get("always_on", False))),
        "skills": [str(item).strip() for item in data.get("skills", []) if str(item).strip()] if isinstance(data.get("skills"), list) else [],
        "meta": meta,
        "project_key": project_key,
        "supervisor_key": supervisor_key,
        "heartbeat_at": heartbeat_at,
        "idle_seconds": idle_seconds,
        "current_assignment": str(data.get("current_assignment") or "").strip(),
        "queue_status": queue_status,
        "queue_check_at": _employee_int(data.get("queue_check_at"), 0),
        "followup_due_at": followup_due_at,
        "last_review_cycle": last_review_cycle,
        "last_supervisor_check_at": last_supervisor_check_at,
        "stale_assignment_followup_status": str(data.get("stale_assignment_followup_status") or "").strip(),
        "updated_at": updated_at,
        "notes": str(data.get("notes") or "").strip(),
    }
    return record

def ensure_employee_profile(
    agent_key: str,
    display_name: str,
    role_type: str,
    status: str = "ready",
    always_on: bool = False,
    skills: Optional[list[str]] = None,
    meta: Optional[dict[str, Any]] = None,
    project_key: str = "",
    supervisor_key: str = "",
    heartbeat_at: int | None = None,
    current_assignment: str = "",
    queue_status: Optional[dict[str, Any]] = None,
    queue_check_at: int | None = None,
    followup_due_at: int | None = None,
    last_review_cycle: int | None = None,
    last_supervisor_check_at: int | None = None,
    stale_assignment_followup_status: str = "",
) -> dict[str, Any]:
    data = employee_state_doc()
    agents = data.get("agents", [])
    if not isinstance(agents, list):
        agents = []
        data["agents"] = agents
    existing = next((a for a in agents if isinstance(a, dict) and str(a.get("agent_key", "")).strip() == agent_key), None)
    existing_record = normalize_employee_agent_record(existing or {})
    merged_meta = dict(existing_record.get("meta") or {})
    if isinstance(meta, dict):
        merged_meta.update(meta)
    normalized_project = normalize_project_key(project_key or existing_record.get("project_key") or merged_meta.get("project_key") or "")
    normalized_supervisor = str(supervisor_key or existing_record.get("supervisor_key") or merged_meta.get("supervisor_key") or "").strip().lower()
    record = normalize_employee_agent_record(
        {
            **existing_record,
        "agent_key": agent_key,
        "display_name": display_name,
        "role_type": role_type,
        "status": status,
        "always_on": bool(always_on),
            "full_time": bool(existing_record.get("full_time", always_on)),
            "skills": skills or existing_record.get("skills") or [],
            "meta": merged_meta,
            "project_key": normalized_project,
            "supervisor_key": normalized_supervisor,
            "heartbeat_at": heartbeat_at if heartbeat_at is not None else existing_record.get("heartbeat_at", int(time.time())),
            "current_assignment": current_assignment or existing_record.get("current_assignment") or "",
            "queue_status": queue_status if isinstance(queue_status, dict) else existing_record.get("queue_status") or {},
            "queue_check_at": queue_check_at if queue_check_at is not None else existing_record.get("queue_check_at", 0),
            "followup_due_at": followup_due_at if followup_due_at is not None else existing_record.get("followup_due_at", 0),
            "last_review_cycle": last_review_cycle if last_review_cycle is not None else existing_record.get("last_review_cycle", 0),
            "last_supervisor_check_at": last_supervisor_check_at if last_supervisor_check_at is not None else existing_record.get("last_supervisor_check_at", 0),
            "stale_assignment_followup_status": stale_assignment_followup_status or existing_record.get("stale_assignment_followup_status") or "",
            "updated_at": int(time.time()),
        }
    )
    if existing is None:
        agents.append(record)
    else:
        existing.update(record)
        record = existing
    write_employee_state(data)
    return record

