def default_model_runtime_map() -> dict[str, dict[str, str]]:
    if OPENAI_PRIMARY_ROUTING and OPENAI_ENABLE and OPENAI_API_KEY:
        runtime_policy = load_runtime_policy()
        openai_models = runtime_policy.get("openai_models") if isinstance(runtime_policy.get("openai_models"), dict) else {}
        return {
            "default": {"provider": "openai", "model": str(openai_models.get("reasoning") or OPENAI_CHAT_MODEL_REASONING or OPENAI_CHAT_MODEL_FAST).strip()},
            "fast": {"provider": "openai", "model": str(openai_models.get("fast") or OPENAI_CHAT_MODEL_FAST).strip()},
            "reasoning": {"provider": "openai", "model": str(openai_models.get("reasoning") or OPENAI_CHAT_MODEL_REASONING).strip()},
            "coder": {"provider": "openai", "model": str(openai_models.get("coder") or OPENAI_CHAT_MODEL_CODER).strip()},
            "presence": {"provider": "ollama", "model": MODEL_PRESENCE},
            "hermes": {"provider": "ollama", "model": MODEL_HERMES},
        }
    return {
        "default": {"provider": "ollama", "model": MODEL_DEFAULT},
        "fast": {"provider": "ollama", "model": MODEL_FAST},
        "reasoning": {"provider": "ollama", "model": MODEL_REASONING},
        "coder": {"provider": "ollama", "model": MODEL_CODER},
        "presence": {"provider": "ollama", "model": MODEL_PRESENCE},
        "hermes": {"provider": "ollama", "model": MODEL_HERMES},
    }

def load_model_prefabs() -> list[dict[str, Any]]:
    data = _read_json(MODEL_CATALOG_PATH)
    raw = data.get("prefabs", []) if isinstance(data, dict) else []
    return [item for item in raw if isinstance(item, dict) and str(item.get("prefab_key", "")).strip()]

def load_model_prefab_overrides() -> dict[str, Any]:
    data = _read_json(MODEL_PREFAB_OVERRIDE_PATH)
    return data if isinstance(data, dict) else {}

def save_model_prefab_overrides(payload: dict[str, Any]):
    MODEL_PREFAB_OVERRIDE_PATH.parent.mkdir(parents=True, exist_ok=True)
    MODEL_PREFAB_OVERRIDE_PATH.write_text(json.dumps(payload, indent=2), encoding="utf-8")

def resolve_active_models() -> dict[str, dict[str, str]]:
    runtime = default_model_runtime_map()
    safe_runtime = json.loads(json.dumps(runtime))
    override = load_model_prefab_overrides()
    active = override.get("active_models", {})
    if isinstance(active, dict):
        for role in ["default", "fast", "reasoning", "coder", "presence", "hermes"]:
            item = active.get(role)
            if not isinstance(item, dict):
                continue
            provider = str(item.get("provider", runtime[role]["provider"])).strip() or runtime[role]["provider"]
            model = str(item.get("model", runtime[role]["model"])).strip() or runtime[role]["model"]
            if provider == "openai":
                provider = safe_runtime[role]["provider"]
                model = safe_runtime[role]["model"]
            runtime[role] = {"provider": provider, "model": model}
    return runtime

OLLAMA_MODEL_CACHE_TTL_SEC = max(30, int(os.getenv("OLLAMA_MODEL_CACHE_TTL_SEC", "300") or 300))
_OLLAMA_MODEL_CACHE_LOCK = asyncio.Lock()
_OLLAMA_MODEL_CACHE_TS = 0.0
_OLLAMA_MODEL_CACHE: dict[str, str] = {}

def _normalize_ollama_model_key(raw: str) -> str:
    value = str(raw or "").strip().lower()
    return value

def _register_ollama_model_key(store: dict[str, str], raw: str):
    value = str(raw or "").strip()
    if not value:
        return
    normalized = _normalize_ollama_model_key(value)
    if normalized:
        store.setdefault(normalized, value)
    base = value.split(":", 1)[0].strip().lower()
    if base:
        store.setdefault(base, value)

async def _available_ollama_models(force_refresh: bool = False) -> dict[str, str]:
    global _OLLAMA_MODEL_CACHE_TS, _OLLAMA_MODEL_CACHE
    now_ts = time.time()
    if not force_refresh and _OLLAMA_MODEL_CACHE and (now_ts - _OLLAMA_MODEL_CACHE_TS) < OLLAMA_MODEL_CACHE_TTL_SEC:
        return dict(_OLLAMA_MODEL_CACHE)
    async with _OLLAMA_MODEL_CACHE_LOCK:
        now_ts = time.time()
        if not force_refresh and _OLLAMA_MODEL_CACHE and (now_ts - _OLLAMA_MODEL_CACHE_TS) < OLLAMA_MODEL_CACHE_TTL_SEC:
            return dict(_OLLAMA_MODEL_CACHE)
        discovered: dict[str, str] = {}
        try:
            async with httpx.AsyncClient(timeout=20) as client:
                r = await client.get(f"{OLLAMA_HOST}/api/tags")
                r.raise_for_status()
                payload = r.json()
            rows = payload.get("models", []) if isinstance(payload, dict) else []
            if isinstance(rows, list):
                for row in rows:
                    if not isinstance(row, dict):
                        continue
                    _register_ollama_model_key(discovered, str(row.get("name") or ""))
                    _register_ollama_model_key(discovered, str(row.get("model") or ""))
            _OLLAMA_MODEL_CACHE = discovered
            _OLLAMA_MODEL_CACHE_TS = now_ts
        except Exception as e:
            activity_log(
                "assistant-core",
                "ollama_model_inventory",
                "warn",
                "Unable to refresh Ollama model inventory",
                str(e),
                {"ollama_host": OLLAMA_HOST},
            )
            if _OLLAMA_MODEL_CACHE:
                return dict(_OLLAMA_MODEL_CACHE)
        return dict(_OLLAMA_MODEL_CACHE)

def _candidate_ollama_models(requested: str, role_hint: str = "") -> list[str]:
    active = resolve_active_models()
    requested_clean = str(requested or "").strip()
    role_key = role_hint if role_hint in {"default", "fast", "reasoning", "coder", "presence", "hermes"} else ""
    ordered: list[str] = []
    if requested_clean:
        ordered.append(requested_clean)
    if role_key:
        cfg = active.get(role_key, {})
        if isinstance(cfg, dict) and str(cfg.get("provider") or "ollama").strip() != "openai":
            ordered.append(str(cfg.get("model") or "").strip())
    for fallback_role in ["presence", "hermes", "reasoning", "coder", "default", "fast"]:
        cfg = active.get(fallback_role, {})
        if not isinstance(cfg, dict):
            continue
        if str(cfg.get("provider") or "ollama").strip() == "openai":
            continue
        ordered.append(str(cfg.get("model") or "").strip())
    ordered.extend(
        [
            MODEL_REASONING,
            MODEL_CODER,
            MODEL_DEFAULT,
            MODEL_FAST,
            "qwen2.5-coder:32b-instruct",
            "qwen2.5:14b",
            "phi3:mini",
        ]
    )
    deduped: list[str] = []
    seen: set[str] = set()
    for item in ordered:
        value = str(item or "").strip()
        if not value:
            continue
        normalized = _normalize_ollama_model_key(value)
        if normalized in seen:
            continue
        seen.add(normalized)
        deduped.append(value)
    return deduped

async def resolve_ollama_model(requested: str, role_hint: str = "", force_refresh: bool = False) -> tuple[str, dict[str, Any]]:
    requested_clean = str(requested or "").strip() or MODEL_FAST
    available = await _available_ollama_models(force_refresh=force_refresh)
    if not available:
        return requested_clean, {
            "requested": requested_clean,
            "resolved": requested_clean,
            "fallback_applied": False,
            "reason": "inventory_unavailable",
            "role_hint": role_hint or None,
        }
    for candidate in _candidate_ollama_models(requested_clean, role_hint=role_hint):
        matched = available.get(_normalize_ollama_model_key(candidate)) or available.get(candidate.split(":", 1)[0].lower())
        if not matched:
            continue
        return matched, {
            "requested": requested_clean,
            "resolved": matched,
            "fallback_applied": matched != requested_clean,
            "reason": "installed_match" if matched == requested_clean else "installed_fallback",
            "role_hint": role_hint or None,
            "inventory_count": len({v for v in available.values()}),
        }
    first_available = sorted({v for v in available.values()})[0]
    return first_available, {
        "requested": requested_clean,
        "resolved": first_available,
        "fallback_applied": first_available != requested_clean,
        "reason": "first_available",
        "role_hint": role_hint or None,
        "inventory_count": len({v for v in available.values()}),
    }

def model_name(role: str) -> str:
    role_key = role if role in {"default", "fast", "reasoning", "coder", "presence", "hermes"} else "fast"
    return resolve_active_models().get(role_key, {}).get("model", MODEL_FAST)

def model_provider(role: str) -> str:
    role_key = role if role in {"default", "fast", "reasoning", "coder", "presence", "hermes"} else "fast"
    return resolve_active_models().get(role_key, {}).get("provider", "ollama")

def load_personality_profile() -> dict[str, Any]:
    data = _read_json(PERSONALITY_PROFILE_PATH)
    return data if isinstance(data, dict) else {}

def active_personality_prompt() -> str:
    profile = load_personality_profile()
    ai_name = str(profile.get("ai_name", MAIN_CONNECTOR_NAME)).strip() or MAIN_CONNECTOR_NAME
    prompt = str(profile.get("personality_prompt", "")).strip()
    features = profile.get("feature_flags", {}) if isinstance(profile.get("feature_flags"), dict) else {}
    voice_cfg = profile.get("voice", {}) if isinstance(profile.get("voice"), dict) else {}
    parts: list[str] = []
    if prompt:
        parts.append(f"Active personality profile for {ai_name}: {prompt}")
    enabled = sorted([k for k, v in features.items() if bool(v)])
    if enabled:
        parts.append("Enabled personality-linked features: " + ", ".join(enabled[:20]))
    voice_bits = []
    if str(voice_cfg.get("default_voice", "")).strip():
        voice_bits.append(f"voice={str(voice_cfg.get('default_voice')).strip()}")
    if str(voice_cfg.get("style", "")).strip():
        voice_bits.append(f"style={str(voice_cfg.get('style')).strip()}")
    if voice_bits:
        parts.append("Voice defaults: " + ", ".join(voice_bits))
    return "\n".join(parts)

