def resolve_discord_channel_binding(guild_id: str = "", channel_id: str = "", project_key: str = "") -> dict[str, Any]:
    ensure_discord_policy_tables()
    conn = db_conn()
    cur = conn.cursor(dictionary=True)
    normalized = normalize_project_key(project_key)
    sql = (
        "SELECT guild_id, project_key, category_id, category_name, text_channel_id, text_channel_name, "
        "voice_channel_id, voice_channel_name, visibility_mode, status, meta_json "
        "FROM discord_channel_bindings WHERE status='active'"
    )
    params: list[Any] = []
    if guild_id:
        sql += " AND guild_id=%s"
        params.append(str(guild_id).strip())
    if channel_id:
        sql += " AND (text_channel_id=%s OR voice_channel_id=%s)"
        params.extend([str(channel_id).strip(), str(channel_id).strip()])
    elif normalized:
        sql += " AND project_key=%s"
        params.append(normalized)
    sql += " ORDER BY updated_at DESC LIMIT 1"
    cur.execute(sql, tuple(params))
    row = cur.fetchone() or {}
    cur.close()
    conn.close()
    if isinstance(row, dict):
        row["meta_json"] = _json_mysql_value(row.get("meta_json"), {})
    return row if isinstance(row, dict) else {}

def load_discord_ops_blueprints_profile() -> dict[str, Any]:
    payload = _read_json(DISCORD_OPS_BLUEPRINTS_PATH)
    if not isinstance(payload, dict):
        return {"version": PROJECT_CODEX_TEMPLATE_VERSION, "templates": []}
    if not isinstance(payload.get("templates"), list):
        payload["templates"] = []
    return payload

def discord_ops_blueprint_profile(blueprint_key: str = "", project_key: str = "") -> dict[str, Any]:
    payload = load_discord_ops_blueprints_profile()
    normalized_key = str(blueprint_key or "").strip().lower()
    normalized_project = normalize_project_key(project_key)
    for row in payload.get("templates", []):
        if not isinstance(row, dict):
            continue
        key = str(row.get("key") or "").strip().lower()
        aliases = [str(alias or "").strip().lower() for alias in row.get("aliases", [])] if isinstance(row.get("aliases"), list) else []
        if normalized_key and (key == normalized_key or normalized_key in aliases):
            return row
    for row in payload.get("templates", []):
        if not isinstance(row, dict):
            continue
        if normalized_project and normalize_project_key(row.get("project_key")) == normalized_project:
            return row
    return {}

def _discord_community_status(value: str, fallback: str = "template_only") -> str:
    clean = str(value or "").strip().lower() or fallback
    if clean not in COMMUNITY_GUILD_STATUS_VALUES:
        clean = fallback
    return clean

def _discord_community_receipt_kind(value: str, fallback: str = "feedback") -> str:
    clean = str(value or "").strip().lower() or fallback
    if clean not in COMMUNITY_RECEIPT_KIND_VALUES:
        clean = fallback
    return clean

def _community_owner_route(profile_row: dict[str, Any], *, fallback_project_key: str = "") -> dict[str, Any]:
    routing = profile_row.get("community_owner_routing") if isinstance(profile_row.get("community_owner_routing"), dict) else {}
    notify_via_raw = routing.get("notify_via")
    notify_via = [str(item or "").strip() for item in notify_via_raw] if isinstance(notify_via_raw, list) else []
    if not notify_via:
        notify_via = ["owner_dm", "project_task"]
    owner_ids = _parse_operator_discord_ids(
        routing.get("owner_discord_ids", ""),
        ",".join(DEFAULT_OPERATOR_DISCORD_USER_IDS),
    )
    return {
        "owner_name": str(routing.get("owner_name") or DEFAULT_OPERATOR_NAME).strip() or DEFAULT_OPERATOR_NAME,
        "owner_portal_user_id": str(
            routing.get("owner_portal_user_id")
            or routing.get("portal_user_id")
            or DEFAULT_OPERATOR_PORTAL_USER_ID
        ).strip()
        or DEFAULT_OPERATOR_PORTAL_USER_ID,
        "owner_discord_ids": list(owner_ids),
        "notify_via": notify_via,
        "project_key": normalize_project_key(routing.get("project_key") or fallback_project_key) or normalize_project_key(fallback_project_key),
        "escalation_label": str(routing.get("escalation_label") or "the owner owner route").strip() or "the owner owner route",
    }

def _community_receipt_contract(profile_row: dict[str, Any]) -> list[str]:
    configured = profile_row.get("community_receipt_kinds")
    if not isinstance(configured, list):
        configured = [
            "feedback",
            "bug_report",
            "feature_request",
            "patch_notes",
            "poll_open",
            "poll_close",
        ]
    ordered: list[str] = []
    for item in configured:
        kind = _discord_community_receipt_kind(item, fallback="")
        if kind and kind not in ordered:
            ordered.append(kind)
    return ordered or ["feedback", "bug_report", "feature_request", "patch_notes", "poll_open", "poll_close"]

def project_community_metadata(project_key: str) -> dict[str, Any]:
    key = normalize_project_key(project_key)
    if not key:
        return {}
    profile_row = olympus_project_profile_for_workspace_project(key)
    branding = profile_row.get("discord_branding") if isinstance(profile_row.get("discord_branding"), dict) else {}
    default_enabled = key in PUBLIC_COMMUNITY_PROJECT_KEYS
    default_status = "ready_to_bootstrap" if default_enabled else ("internal_only" if key in INTERNAL_ONLY_COMMUNITY_PROJECT_KEYS else "template_only")
    enabled = bool(profile_row.get("community_guild_enabled")) if "community_guild_enabled" in profile_row else default_enabled
    blueprint_key = (
        str(profile_row.get("community_guild_blueprint_key") or "").strip()
        or str(branding.get("community_guild_blueprint_key") or "").strip()
        or (f"{key}_community_guild" if enabled else "")
    )
    bot_role = str(profile_row.get("community_bot_role") or branding.get("community_bot_role") or DEFAULT_COMMUNITY_BOT_ROLE).strip() or DEFAULT_COMMUNITY_BOT_ROLE
    status = _discord_community_status(str(profile_row.get("community_guild_status") or "").strip(), fallback=default_status)
    public_name = str(profile_row.get("public_name") or profile_row.get("display_name") or pretty_label(key)).strip() or pretty_label(key)
    olympus_mirror_channel = str(profile_row.get("olympus_mirror_channel") or branding.get("olympus_mirror_channel") or "").strip()
    channels = {
        "welcome": str(branding.get("community_welcome_channel") or "welcome").strip() or "welcome",
        "announcements": str(branding.get("community_announcements_channel") or "announcements").strip() or "announcements",
        "patch_notes": str(branding.get("community_patch_notes_channel") or branding.get("community_announcements_channel") or "patch-notes").strip() or "patch-notes",
        "feedback": str(branding.get("community_feedback_channel") or "feedback").strip() or "feedback",
        "bugs": str(branding.get("community_bugs_channel") or "bug-reports").strip() or "bug-reports",
        "events": str(branding.get("community_events_channel") or "events").strip() or "events",
    }
    owner_route = _community_owner_route(profile_row, fallback_project_key=key)
    return {
        "project_key": key,
        "community_guild_enabled": bool(enabled),
        "community_guild_status": status,
        "community_guild_blueprint_key": blueprint_key,
        "community_bot_role": bot_role,
        "public_name": public_name,
        "olympus_mirror_channel": olympus_mirror_channel,
        "discord_branding": branding,
        "profile": profile_row,
        "default_channels": channels,
        "owner_route": owner_route,
        "receipt_kinds": _community_receipt_contract(profile_row),
    }

