def normalize_integration_scope(scope: str | None) -> str:
    value = (scope or "project").strip().lower()
    return "luminax" if value == "luminax" else "project"

def normalize_project_key(project_key: str | None) -> str | None:
    raw = (project_key or "").strip().lower()
    if not raw:
        return None
    clean = "".join(ch for ch in raw if ch.isalnum() or ch in "-_").strip("-_")
    return clean[:128] if clean else None


if LUMINAX_RUNTIME_ENABLED and DEFER_HIVE_EMPLOYEE_PROFILE_BOOTSTRAP:
    ensure_hive_employee_profiles()

def pretty_label(value: str | None) -> str:
    text = (value or "").strip().replace("_", " ").replace("-", " ")
    if not text:
        return "Item"
    return " ".join(part.capitalize() for part in text.split())

CREATIVE_EMPIRE_HINTS = [
    "start a band",
    "start an angsty rock band",
    "make a band",
    "create a band",
    "album",
    "single",
    "music video",
    "artist project",
    "song rollout",
]

def detect_creative_empire_intent(prompt: str) -> dict[str, Any]:
    text = (prompt or "").strip()
    lower = text.lower()
    if not text:
        return {"matched": False}
    matched = any(h in lower for h in CREATIVE_EMPIRE_HINTS)
    if not matched:
        return {"matched": False}
    genre = "angsty rock" if "angsty" in lower or "rock" in lower else "alt pop"
    candidate_names = [
        "Neon Graves",
        "Velvet Collapse",
        "Static Halo",
        "Midnight Wreckage",
        "Glass Riot",
    ]
    idx = (sum(ord(ch) for ch in lower) + len(lower)) % len(candidate_names)
    band_name = candidate_names[idx]
    if "neon" in lower:
        band_name = "Neon Graves"
    project_key = normalize_project_key(f"creative-{band_name}") or f"creative-{int(time.time())}"
    return {
        "matched": True,
        "project_key": project_key,
        "band_name": band_name,
        "genre": genre,
        "prompt": text,
    }

TASK_STATUS_ALLOWED = {"queued", "in_progress", "blocked", "completed", "canceled", "failed"}

def normalize_task_status(status: str | None, default: str = "queued") -> str:
    value = (status or "").strip().lower()
    if not value:
        return default
    return value if value in TASK_STATUS_ALLOWED else default

def normalize_tool_key(raw: str | None) -> str:
    value = (raw or "").strip().lower()
    clean = "".join(ch for ch in value if ch.isalnum() or ch in "-_").strip("-_")
    return clean[:96]

def create_tool_scaffold(tool_key: str, description: str = "", owner: str = "mount-olympus", notes: str = "") -> dict[str, Any]:
    key = normalize_tool_key(tool_key)
    if not key:
        raise HTTPException(status_code=400, detail="Tool key is required")
    TOOLS_GENERATED_ROOT.mkdir(parents=True, exist_ok=True)
    TOOL_PLAN_ROOT.mkdir(parents=True, exist_ok=True)
    py_path = TOOLS_GENERATED_ROOT / f"{key}.py"
    plan_path = TOOL_PLAN_ROOT / f"{key}.json"
    if not py_path.exists():
        template = (
            '"""Mount Olympus generated tool scaffold."""\n\n'
            "from __future__ import annotations\n\n"
            "def run(args: dict) -> dict:\n"
            "    \"\"\"Implement tool logic safely, then return JSON-serializable output.\"\"\"\n"
            f"    return {{\"status\": \"todo\", \"tool\": \"{key}\", \"args\": args}}\n"
        )
        py_path.write_text(template, encoding="utf-8")
    plan_record = {
        "tool_key": key,
        "description": (description or "").strip(),
        "owner": (owner or "mount-olympus").strip(),
        "notes": (notes or "").strip(),
        "generated_file": str(py_path),
        "created_at": int(time.time()),
        "status": "scaffolded",
    }
    plan_path.write_text(json.dumps(plan_record, indent=2), encoding="utf-8")
    return {"status": "ok", "tool": key, "generated_file": str(py_path), "plan_file": str(plan_path), "record": plan_record}

def normalize_workflow_key(raw: str | None) -> str:
    value = (raw or "").strip().lower()
    clean = "".join(ch for ch in value if ch.isalnum() or ch in "-_").strip("-_")
    return clean[:96]

def workflow_path(workflow_key: str) -> Path:
    key = normalize_workflow_key(workflow_key)
    if not key:
        raise HTTPException(status_code=400, detail="Workflow key is required")
    return WORKFLOW_ROOT / f"{key}.json"

def save_workflow_def(workflow_key: str, payload: dict[str, Any]) -> dict[str, Any]:
    path = workflow_path(workflow_key)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return {"workflow_key": normalize_workflow_key(workflow_key), "path": str(path)}

def read_workflow_def(workflow_key: str) -> dict[str, Any]:
    path = workflow_path(workflow_key)
    if not path.exists():
        raise HTTPException(status_code=404, detail="Workflow not found")
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            raise ValueError("Workflow payload is not object")
        return data
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Invalid workflow file: {e}")

def list_workflow_defs(limit: int = 200) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for p in sorted(WORKFLOW_ROOT.glob("*.json"), reverse=True)[:limit]:
        try:
            data = json.loads(p.read_text(encoding="utf-8"))
            rows.append({
                "workflow_key": str(data.get("workflow_key", p.stem)),
                "title": str(data.get("title", p.stem)),
                "description": str(data.get("description", "")),
                "updated_at": int(data.get("updated_at", 0) or 0),
                "node_count": len(data.get("nodes", []) if isinstance(data.get("nodes"), list) else []),
                "edge_count": len(data.get("edges", []) if isinstance(data.get("edges"), list) else []),
                "path": str(p),
            })
        except Exception:
            rows.append({"workflow_key": p.stem, "title": p.stem, "description": "invalid_workflow_file", "updated_at": 0, "node_count": 0, "edge_count": 0, "path": str(p)})
    return rows

