def _normalize_model_key(raw: str | None) -> str:
    value = (raw or "").strip().lower()
    return "".join(ch for ch in value if ch.isalnum() or ch in "-_").strip("-_")[:128]

def _model_status_summary(models: list[dict[str, Any]]) -> dict[str, Any]:
    by_status: dict[str, int] = {}
    by_category: dict[str, int] = {}
    by_provider: dict[str, int] = {}
    for item in models:
        status = str(item.get("status", "unknown")).strip().lower() or "unknown"
        category = str(item.get("category", "uncategorized")).strip().lower() or "uncategorized"
        provider = str(item.get("provider", "unknown")).strip().lower() or "unknown"
        by_status[status] = by_status.get(status, 0) + 1
        by_category[category] = by_category.get(category, 0) + 1
        by_provider[provider] = by_provider.get(provider, 0) + 1
    return {"by_status": by_status, "by_category": by_category, "by_provider": by_provider}

