def _media_tools_doc() -> dict[str, Any]:
    data = _read_json(MEDIA_TOOLS_PATH)
    if not isinstance(data, dict):
        data = {}
    tools = data.get("tools")
    if not isinstance(tools, list):
        data = _default_media_tools_doc()
        MEDIA_TOOLS_PATH.parent.mkdir(parents=True, exist_ok=True)
        MEDIA_TOOLS_PATH.write_text(json.dumps(data, indent=2), encoding="utf-8")
        tools = data.get("tools", [])
    data["tools"] = [x for x in tools if isinstance(x, dict)]
    return data


def _image_style_doc() -> dict[str, Any]:
    data = _read_json(IMAGE_STYLE_LIBRARY_PATH)
    return data if isinstance(data, dict) else {"version": "", "styles": []}


def _image_style_entry(style_key: str) -> dict[str, Any] | None:
    target = str(style_key or "").strip().lower()
    if not target:
        return None
    rows = _image_style_doc().get("styles", [])
    if not isinstance(rows, list):
        return None
    for row in rows:
        if not isinstance(row, dict):
            continue
        key = str(row.get("style_key", "")).strip().lower()
        if key == target:
            return row
    return None


def _apply_image_style(prompt: str, settings: dict[str, Any]) -> tuple[str, dict[str, Any], dict[str, Any] | None]:
    merged = dict(settings or {})
    style_key = str(merged.get("style_key", "")).strip().lower()
    if not style_key:
        return prompt, merged, None
    style = _image_style_entry(style_key)
    if not style:
        return prompt, merged, None
    recommended = style.get("recommended_settings", {})
    if isinstance(recommended, dict):
        base = dict(recommended)
        base.update(merged)
        merged = base
    prefix = str(style.get("prompt_prefix", "")).strip()
    suffix = str(style.get("prompt_suffix", "")).strip()
    parts = [part for part in [prefix, prompt, suffix] if str(part or "").strip()]
    styled_prompt = ". ".join(parts)
    style_negative = str(style.get("negative_prompt", "")).strip()
    request_negative = str(merged.get("negative_prompt", "")).strip()
    merged_negative = ", ".join([part for part in [request_negative, style_negative] if part])
    if merged_negative:
        merged["negative_prompt"] = merged_negative
    merged["style_display_name"] = str(style.get("display_name", style_key)).strip() or style_key
    return styled_prompt, merged, style


def _edge_image_dimensions(settings: dict[str, Any]) -> tuple[int, int]:
    size = str((settings or {}).get("size") or _normalize_image_size(settings)).strip().lower()
    match = re.fullmatch(r"(\d{2,4})x(\d{2,4})", size)
    if not match:
        return 1024, 1024
    try:
        return int(match.group(1)), int(match.group(2))
    except Exception:
        return 1024, 1024

def _media_job_path(job_id: str) -> Path:
    safe = "".join(ch for ch in (job_id or "").strip().lower() if ch.isalnum() or ch in "-_")
    if not safe:
        raise HTTPException(status_code=400, detail="Invalid media job id")
    return MEDIA_JOB_ROOT / f"{safe}.json"

def _list_media_jobs(limit: int = 200) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for p in sorted(MEDIA_JOB_ROOT.glob("*.json"), reverse=True)[:max(1, min(limit, 800))]:
        try:
            data = json.loads(p.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                rows.append(data)
        except Exception:
            continue
    return rows

def _read_media_job(job_id: str) -> dict[str, Any]:
    path = _media_job_path(job_id)
    if not path.exists():
        raise HTTPException(status_code=404, detail="Media job not found")
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            raise ValueError("invalid media job payload")
        return data
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Invalid media job file: {e}")

def _write_media_job(record: dict[str, Any]):
    job_id = str(record.get("job_id", "")).strip()
    if not job_id:
        raise HTTPException(status_code=400, detail="Media job id is required")
    record["updated_at"] = int(time.time())
    _write_json(_media_job_path(job_id), record)

def _media_asset_url(job_id: str) -> str:
    return f"/api/media/jobs/{job_id}/asset"

def _site_asset_api_url(site_name: str, rel_path: str) -> str:
    rel = _site_rel_path(rel_path)
    return f"/api/sites/public/{normalize_site_slug(site_name)}/{rel}" if rel else f"/api/sites/public/{normalize_site_slug(site_name)}"

def _default_site_asset_api_url(rel_path: str) -> str:
    rel = _site_rel_path(rel_path)
    return f"/api/sites/default/public/{rel}" if rel else "/api/sites/default/public"

def _project_asset_root(project_key: str) -> Path:
    safe = normalize_project_key(project_key)
    if not safe:
        raise HTTPException(status_code=400, detail="Invalid project key")
    root = (PROJECTS_ROOT / safe).resolve()
    if not str(root).startswith(str(PROJECTS_ROOT.resolve())):
        raise HTTPException(status_code=400, detail="Invalid project asset root")
    root.mkdir(parents=True, exist_ok=True)
    return root

def _safe_join(root: Path, rel_path: str) -> tuple[Path, str]:
    rel = (rel_path or "").strip().replace("\\", "/").lstrip("/")
    candidate = (root / rel).resolve() if rel else root.resolve()
    if not str(candidate).startswith(str(root.resolve())):
        raise HTTPException(status_code=400, detail="Path escapes allowed root")
    return candidate, rel

def _ensure_target_file(rel_path: str, default_name: str) -> str:
    rel = (rel_path or "").strip().replace("\\", "/").lstrip("/")
    if not rel:
        return default_name
    if rel.endswith("/"):
        return f"{rel}{default_name}"
    if "." not in Path(rel).name:
        return rel + Path(default_name).suffix
    return rel

def _music_output_extension(settings: dict[str, Any]) -> str:
    requested = str((settings or {}).get("output_format", "mp3")).strip().lower()
    return ".wav" if requested == "wav" else ".mp3"

def _media_output_extension(media_type: str, settings: dict[str, Any]) -> str:
    if str(media_type or "").strip().lower() == "music":
        return _music_output_extension(settings)
    requested = str((settings or {}).get("output_format", "png")).strip().lower()
    if requested in {"jpg", "jpeg"}:
        return ".jpg"
    if requested == "webp":
        return ".webp"
    if requested == "svg":
        return ".svg"
    return ".png"

def _media_job_default_name(job_id: str, media_type: str, settings: dict[str, Any]) -> str:
    return f"{job_id}{_media_output_extension(media_type, settings)}"

def _resolve_media_output_target(job_id: str, output_target: str, media_type: str, settings: dict[str, Any], default_name: str = "") -> dict[str, Any]:
    default_name = default_name or _media_job_default_name(job_id, media_type, settings)
    raw = (output_target or "").strip()
    if not raw:
        base_dir = "images" if str(media_type or "").strip().lower() == "image" else str(media_type or "generated").strip().lower() or "generated"
        rel = _ensure_target_file(f"{base_dir}/{default_name}", default_name)
        path, safe_rel = _safe_join(MEDIA_OUTPUT_ROOT, rel)
        return {"kind": "generated", "path": path, "relative_path": safe_rel}
    lower = raw.lower()
    if lower.startswith("site:"):
        body = raw[5:]
        site_name, _, rel = body.partition("/")
        safe_site = normalize_site_slug(site_name)
        safe_rel = _ensure_target_file(rel, f"assets/{default_name}")
        path, safe_rel = _safe_join(_site_source_root(safe_site), safe_rel)
        return {"kind": "site", "site_name": safe_site, "path": path, "relative_path": safe_rel}
    if lower.startswith("project:"):
        body = raw[8:]
        project_key, _, rel = body.partition("/")
        safe_project = normalize_project_key(project_key)
        if not safe_project:
            raise HTTPException(status_code=400, detail="Invalid project output target")
        safe_rel = _ensure_target_file(rel, f"assets/{default_name}")
        path, safe_rel = _safe_join(_project_asset_root(safe_project), safe_rel)
        return {"kind": "project", "project_key": safe_project, "path": path, "relative_path": safe_rel}
    safe_rel = _ensure_target_file(raw, default_name)
    path, safe_rel = _safe_join(MEDIA_OUTPUT_ROOT, safe_rel)
    return {"kind": "generated", "path": path, "relative_path": safe_rel}

async def _read_media_source_asset(source_ref: str) -> dict[str, Any]:
    raw = (source_ref or "").strip()
    if not raw:
        raise HTTPException(status_code=400, detail="Missing source asset")
    lower = raw.lower()
    if lower.startswith("http://") or lower.startswith("https://"):
        async with httpx.AsyncClient(timeout=httpx.Timeout(MEDIA_JOB_TIMEOUT_SEC, connect=10.0), follow_redirects=True) as client:
            response = await client.get(raw)
            response.raise_for_status()
            payload = response.content
            if len(payload) > MEDIA_MAX_SOURCE_BYTES:
                raise HTTPException(status_code=400, detail="Source asset exceeds size limit")
            mime = response.headers.get("content-type", "").split(";")[0].strip() or "application/octet-stream"
            name = Path(raw.split("?", 1)[0]).name or f"source_{uuid.uuid4().hex[:8]}"
            return {"bytes": payload, "filename": name, "mime": mime, "source": raw}
    if lower.startswith("job:"):
        other_job = _read_media_job(raw[4:])
        asset_path = Path(str(other_job.get("asset_path", "")).strip())
        if not asset_path.exists():
            raise HTTPException(status_code=404, detail="Referenced media job asset not found")
        payload = asset_path.read_bytes()
        if len(payload) > MEDIA_MAX_SOURCE_BYTES:
            raise HTTPException(status_code=400, detail="Source asset exceeds size limit")
        mime = mimetypes.guess_type(asset_path.name)[0] or "application/octet-stream"
        return {"bytes": payload, "filename": asset_path.name, "mime": mime, "source": raw}
    if lower.startswith("site:"):
        body = raw[5:]
        site_name, _, rel = body.partition("/")
        path, _ = _safe_join(_site_source_root(normalize_site_slug(site_name)), rel)
    elif lower.startswith("project:"):
        body = raw[8:]
        project_key, _, rel = body.partition("/")
        safe_project = normalize_project_key(project_key)
        if not safe_project:
            raise HTTPException(status_code=400, detail="Invalid project source asset")
        path, _ = _safe_join(_project_asset_root(safe_project), rel)
    else:
        raw_path = Path(raw)
        path = raw_path.resolve() if raw_path.is_absolute() else (WORKSPACE_ROOT / raw).resolve()
        allowed_roots = [WORKSPACE_ROOT.resolve(), MEDIA_OUTPUT_ROOT.resolve(), PROJECTS_ROOT.resolve(), SITES_ROOT.resolve()]
        if not any(str(path).startswith(str(root)) for root in allowed_roots):
            raise HTTPException(status_code=400, detail="Source asset path is outside allowed roots")
    if not path.exists() or not path.is_file():
        raise HTTPException(status_code=404, detail="Source asset not found")
    payload = path.read_bytes()
    if len(payload) > MEDIA_MAX_SOURCE_BYTES:
        raise HTTPException(status_code=400, detail="Source asset exceeds size limit")
    mime = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
    return {"bytes": payload, "filename": path.name, "mime": mime, "source": str(path)}

async def _read_media_source_assets(source_asset: str) -> list[dict[str, Any]]:
    refs = [part.strip() for part in str(source_asset or "").split(",") if part.strip()]
    assets: list[dict[str, Any]] = []
    for ref in refs[:4]:
        assets.append(await _read_media_source_asset(ref))
    return assets

def _normalize_image_size(settings: dict[str, Any]) -> str:
    raw = str((settings or {}).get("size", "")).strip().lower()
    allowed = {"1024x1024", "1536x1024", "1024x1536", "auto"}
    if raw in allowed:
        return raw
    width = int(settings.get("width", 0) or 0)
    height = int(settings.get("height", 0) or 0)
    if width and height:
        if width >= height * 1.2:
            return "1536x1024"
        if height >= width * 1.2:
            return "1024x1536"
    return "1024x1024"

def _normalize_image_quality(settings: dict[str, Any]) -> str:
    value = str((settings or {}).get("quality", "high")).strip().lower()
    return value if value in {"low", "medium", "high", "auto"} else "high"

def _normalize_image_background(settings: dict[str, Any]) -> str:
    value = str((settings or {}).get("background", "auto")).strip().lower()
    return value if value in {"transparent", "opaque", "auto"} else "auto"

def _normalize_image_format(settings: dict[str, Any]) -> str:
    value = str((settings or {}).get("output_format", "png")).strip().lower()
    if value in {"jpg", "jpeg"}:
        return "jpeg"
    return value if value in {"png", "webp"} else "png"

def _normalize_image_compression(settings: dict[str, Any]) -> int | None:
    value = settings.get("output_compression")
    if value is None or str(value).strip() == "":
        return None
    try:
        return max(0, min(int(value), 100))
    except Exception:
        return None

def _normalize_image_moderation(settings: dict[str, Any]) -> str | None:
    value = str((settings or {}).get("moderation", "")).strip().lower()
    return value if value in {"auto", "low"} else None

def _normalize_music_action(settings: dict[str, Any]) -> str:
    value = str((settings or {}).get("action", "generate")).strip().lower()
    return value if value in {"generate", "lyrics", "extend", "stems", "wav"} else "generate"

def _music_job_workspace(job_id: str) -> Path:
    root = MEDIA_OUTPUT_ROOT / "jobs" / job_id
    root.mkdir(parents=True, exist_ok=True)
    return root

def _music_job_file_url(job_id: str, rel_path: str) -> str:
    rel = _site_rel_path(rel_path)
    return f"/api/media/jobs/{job_id}/files/{quote(rel, safe='/')}" if rel else f"/api/media/jobs/{job_id}/files"

def _music_safe_label(value: str, fallback: str) -> str:
    cleaned = re.sub(r"[^a-zA-Z0-9._-]+", "_", (value or "").strip()).strip("._")
    return cleaned[:96] or fallback

def _music_callback_url() -> str:
    return SUNO_CALLBACK_URL

