def safe_under(root: Path, path_str: str) -> Path:
    target = (root / path_str).resolve()
    if not str(target).startswith(str(root.resolve())):
        raise HTTPException(status_code=400, detail="Path outside allowed root denied")
    return target

def safe_workspace_path(path_str: str) -> Path:
    return safe_under(WORKSPACE_ROOT, path_str)

def safe_project_path(path_str: str) -> Path:
    return safe_under(PROJECTS_ROOT, path_str)

def normalize_file_root(root_name: str = "") -> str:
    return "workspace" if str(root_name or "").strip().lower() == "workspace" else "project"

def _resolve_runtime_root_and_path(root_name: str, path_str: str) -> tuple[str, Path, str]:
    normalized_root = normalize_file_root(root_name)
    base_root = WORKSPACE_ROOT if normalized_root == "workspace" else PROJECTS_ROOT
    raw = str(path_str or "").strip().replace("\\", "/")
    if normalized_root != "workspace" or not raw:
        return normalized_root, base_root, raw

    lower = raw.lower()
    prefix = WINDOWS_WORKSPACE_PREFIX
    if not prefix or not lower.startswith(prefix):
        return normalized_root, base_root, raw

    suffix = raw[len(prefix):].lstrip("/")
    atlas_root = WORKSPACE_ATLAS_ROOT.resolve()
    if not suffix:
        return normalized_root, atlas_root, ""

    try:
        atlas_target = safe_under(atlas_root, suffix)
        if atlas_target.exists():
            rel = str(atlas_target.relative_to(atlas_root)).replace("\\", "/")
            return normalized_root, atlas_root, rel
    except HTTPException:
        pass

    parts = [part for part in suffix.split("/") if part]
    if parts:
        project_key = normalize_project_key(parts[0]) or parts[0].strip().lower()
        remainder = "/".join(parts[1:])
        candidate_rel = f"projects/{project_key}"
        if remainder:
            candidate_rel += f"/{remainder}"
        try:
            candidate_target = safe_under(atlas_root, candidate_rel)
            if candidate_target.exists():
                rel = str(candidate_target.relative_to(atlas_root)).replace("\\", "/")
                return normalized_root, atlas_root, rel
        except HTTPException:
            pass

    return normalized_root, atlas_root, suffix

def _checkout_scope_kind(value: Any) -> str:
    return "tree" if str(value or "").strip().lower() == "tree" else "exact"

def _checkout_lease_seconds(value: Any) -> int:
    try:
        parsed = int(value or FILE_CHECKOUT_DEFAULT_LEASE_SEC)
    except Exception:
        parsed = FILE_CHECKOUT_DEFAULT_LEASE_SEC
    return max(60, min(parsed, 86400))

def _normalize_locked_path(root_name: str, rel_path: str, allow_directory: bool = False) -> tuple[str, str]:
    normalized_root, root, resolved_path = _resolve_runtime_root_and_path(root_name, rel_path)
    raw = str(resolved_path or ".").strip().replace("\\", "/")
    target = safe_under(root, raw or ".")
    rel = str(target.relative_to(root)).replace("\\", "/")
    if allow_directory:
        if raw in {"", ".", "./"}:
            return normalized_root, "."
        if target.exists() and target.is_dir():
            return normalized_root, rel or "."
        if not target.exists() and raw.endswith("/"):
            return normalized_root, rel or "."
    if not rel or rel == ".":
        raise HTTPException(status_code=400, detail="A concrete file path is required")
    if target.exists() and target.is_dir():
        raise HTTPException(status_code=400, detail="A file path is required for this checkout")
    return normalized_root, rel

def _empty_checkout_state() -> dict[str, Any]:
    return {"updated_at": int(time.time()), "locks": {}}

def ensure_file_checkout_tables():
    try:
        conn = db_conn()
        cur = conn.cursor()
        cur.execute(
            f"""
            CREATE TABLE IF NOT EXISTS {FILE_CHECKOUT_DB_TABLE} (
              lock_key VARCHAR(512) PRIMARY KEY,
              checkout_id VARCHAR(64) NOT NULL,
              root_name VARCHAR(32) NOT NULL,
              path TEXT NOT NULL,
              scope_kind VARCHAR(16) NOT NULL,
              holder VARCHAR(191) NOT NULL,
              session_id VARCHAR(191) NULL,
              status VARCHAR(32) NOT NULL DEFAULT 'checked_out',
              note TEXT NULL,
              created_at BIGINT NOT NULL,
              updated_at BIGINT NOT NULL,
              lease_seconds INT NOT NULL,
              expires_at BIGINT NOT NULL,
              queue_json LONGTEXT NULL,
              nudges_json LONGTEXT NULL
            )
            """
        )
        conn.commit()
        cur.close()
        conn.close()
    except Exception:
        pass

def _decode_checkout_json_list(raw_value: Any) -> list[dict[str, Any]]:
    if isinstance(raw_value, list):
        return [row for row in raw_value if isinstance(row, dict)]
    text = str(raw_value or "").strip()
    if not text:
        return []
    try:
        parsed = json.loads(text)
        if isinstance(parsed, list):
            return [row for row in parsed if isinstance(row, dict)]
    except Exception:
        pass
    return []

def _load_file_checkout_state_from_db() -> dict[str, Any]:
    ensure_file_checkout_tables()
    state = _empty_checkout_state()
    try:
        conn = db_conn()
        cur = conn.cursor(dictionary=True)
        cur.execute(
            f"SELECT lock_key, checkout_id, root_name, path, scope_kind, holder, session_id, status, note, "
            f"created_at, updated_at, lease_seconds, expires_at, queue_json, nudges_json "
            f"FROM {FILE_CHECKOUT_DB_TABLE}"
        )
        rows = cur.fetchall()
        cur.close()
        conn.close()
        for row in rows:
            key = str(row.get("lock_key") or "").strip()
            if not key:
                continue
            lock = {
                "checkout_id": str(row.get("checkout_id") or "").strip(),
                "root": normalize_file_root(row.get("root_name")),
                "path": str(row.get("path") or ".").strip() or ".",
                "scope_kind": _checkout_scope_kind(row.get("scope_kind")),
                "holder": str(row.get("holder") or "").strip(),
                "session_id": str(row.get("session_id") or "").strip()[:120],
                "status": str(row.get("status") or "checked_out").strip() or "checked_out",
                "note": str(row.get("note") or "").strip()[:600],
                "created_at": int(row.get("created_at") or 0),
                "updated_at": int(row.get("updated_at") or 0),
                "lease_seconds": _checkout_lease_seconds(row.get("lease_seconds")),
                "expires_at": int(row.get("expires_at") or 0),
                "queue": _decode_checkout_json_list(row.get("queue_json")),
                "nudges": _decode_checkout_json_list(row.get("nudges_json")),
            }
            state["locks"][key] = lock
            state["updated_at"] = max(int(state.get("updated_at") or 0), int(lock.get("updated_at") or 0))
    except Exception:
        return {}
    return state

def _load_file_checkout_state() -> dict[str, Any]:
    with FILE_CHECKOUT_STATE_GUARD:
        db_state = _load_file_checkout_state_from_db()
        if isinstance(db_state, dict) and db_state.get("locks"):
            return db_state
        if not FILE_CHECKOUT_STATE_PATH.exists():
            return _empty_checkout_state()
        try:
            raw = json.loads(FILE_CHECKOUT_STATE_PATH.read_text(encoding="utf-8"))
            if isinstance(raw, dict):
                raw.setdefault("locks", {})
                raw.setdefault("updated_at", int(time.time()))
                return raw
        except Exception:
            pass
        return _empty_checkout_state()

def _save_file_checkout_state(state: dict[str, Any]) -> dict[str, Any]:
    with FILE_CHECKOUT_STATE_GUARD:
        payload = state if isinstance(state, dict) else _empty_checkout_state()
        payload["updated_at"] = int(time.time())
        payload.setdefault("locks", {})
        FILE_CHECKOUT_STATE_PATH.parent.mkdir(parents=True, exist_ok=True)
        FILE_CHECKOUT_STATE_PATH.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
        try:
            ensure_file_checkout_tables()
            conn = db_conn()
            cur = conn.cursor()
            cur.execute(f"DELETE FROM {FILE_CHECKOUT_DB_TABLE}")
            for key, lock in (payload.get("locks") or {}).items():
                if not isinstance(lock, dict):
                    continue
                cur.execute(
                    f"REPLACE INTO {FILE_CHECKOUT_DB_TABLE} "
                    "(lock_key, checkout_id, root_name, path, scope_kind, holder, session_id, status, note, created_at, updated_at, lease_seconds, expires_at, queue_json, nudges_json) "
                    "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)",
                    (
                        str(key or "").strip(),
                        str(lock.get("checkout_id") or "").strip(),
                        normalize_file_root(lock.get("root")),
                        str(lock.get("path") or ".").strip() or ".",
                        _checkout_scope_kind(lock.get("scope_kind")),
                        str(lock.get("holder") or "").strip()[:191],
                        str(lock.get("session_id") or "").strip()[:191],
                        str(lock.get("status") or "checked_out").strip() or "checked_out",
                        str(lock.get("note") or "").strip()[:600],
                        int(lock.get("created_at") or 0),
                        int(lock.get("updated_at") or 0),
                        _checkout_lease_seconds(lock.get("lease_seconds")),
                        int(lock.get("expires_at") or 0),
                        json.dumps(lock.get("queue") if isinstance(lock.get("queue"), list) else [], ensure_ascii=False),
                        json.dumps(lock.get("nudges") if isinstance(lock.get("nudges"), list) else [], ensure_ascii=False),
                    ),
                )
            conn.commit()
            cur.close()
            conn.close()
        except Exception:
            pass
        return payload

def _file_checkout_key(root_name: str, rel_path: str, scope_kind: str = "exact") -> str:
    normalized_root, normalized_path = _normalize_locked_path(root_name, rel_path, allow_directory=_checkout_scope_kind(scope_kind) == "tree")
    return f"{normalized_root}:{_checkout_scope_kind(scope_kind)}:{normalized_path}"

def _checkout_actor(agent_key: str = "", session_id: str = "") -> str:
    actor = str(agent_key or "").strip()
    if actor:
        return actor[:120]
    actor = str(current_web_auth_user() or "").strip()
    if actor:
        return actor[:120]
    actor = str(session_id or "").strip()
    if actor:
        return actor[:120]
    return "luminax-agent"

def _path_within_scope(candidate_path: str, scope_path: str) -> bool:
    candidate = str(candidate_path or "").strip().strip("/")
    scope = str(scope_path or "").strip().strip("/")
    if scope in {"", "."}:
        return True
    if candidate in {"", "."}:
        return scope in {"", "."}
    return candidate == scope or candidate.startswith(scope + "/")

def _refresh_checkout_lock(lock: dict[str, Any], lease_seconds: int | None = None):
    now_ts = int(time.time())
    lease = _checkout_lease_seconds(lease_seconds if lease_seconds is not None else lock.get("lease_seconds"))
    lock["lease_seconds"] = lease
    lock["expires_at"] = now_ts + lease
    lock["updated_at"] = now_ts

def _lock_conflicts_with_scope(lock: dict[str, Any], root_name: str, rel_path: str, scope_kind: str) -> bool:
    if str(lock.get("root") or "").strip() != root_name:
        return False
    requested_scope = _checkout_scope_kind(scope_kind)
    locked_scope = _checkout_scope_kind(lock.get("scope_kind"))
    locked_path = str(lock.get("path") or "").strip() or "."
    if requested_scope == "tree":
        if locked_scope == "tree":
            return _path_within_scope(rel_path, locked_path) or _path_within_scope(locked_path, rel_path)
        return _path_within_scope(locked_path, rel_path)
    if locked_scope == "tree":
        return _path_within_scope(rel_path, locked_path)
    return locked_path == rel_path

def _lock_sort_key(lock: dict[str, Any], rel_path: str, scope_kind: str) -> tuple[int, int, int]:
    same_path = 0 if str(lock.get("path") or "").strip() == rel_path else 1
    same_scope = 0 if _checkout_scope_kind(lock.get("scope_kind")) == _checkout_scope_kind(scope_kind) else 1
    created_at = int(lock.get("created_at") or 0)
    return (same_path, same_scope, created_at)

def _promote_next_checkout_lock(lock: dict[str, Any]) -> tuple[str | None, dict[str, Any] | None]:
    queue = [row for row in (lock.get("queue") or []) if isinstance(row, dict)]
    if not queue:
        return None, None
    next_row = queue.pop(0)
    now_ts = int(time.time())
    lease_seconds = _checkout_lease_seconds(next_row.get("lease_seconds") or lock.get("lease_seconds"))
    promoted = {
        "checkout_id": f"checkout_{uuid.uuid4().hex[:12]}",
        "root": str(next_row.get("root") or lock.get("root") or "project").strip() or "project",
        "path": str(next_row.get("path") or lock.get("path") or ".").strip() or ".",
        "scope_kind": _checkout_scope_kind(next_row.get("scope_kind") or lock.get("scope_kind") or "exact"),
        "holder": str(next_row.get("agent_key") or "").strip() or "queued-agent",
        "session_id": str(next_row.get("session_id") or "").strip()[:120],
        "status": "checked_out",
        "note": str(next_row.get("note") or lock.get("note") or "").strip()[:600],
        "created_at": now_ts,
        "updated_at": now_ts,
        "lease_seconds": lease_seconds,
        "expires_at": now_ts + lease_seconds,
        "queue": queue,
        "nudges": lock.get("nudges") if isinstance(lock.get("nudges"), list) else [],
    }
    promoted_key = _file_checkout_key(promoted["root"], promoted["path"], promoted["scope_kind"])
    return promoted_key, promoted

def _prune_checkout_state(state: dict[str, Any]) -> tuple[dict[str, Any], bool]:
    payload = state if isinstance(state, dict) else _empty_checkout_state()
    locks = payload.setdefault("locks", {})
    now_ts = int(time.time())
    changed = False
    for key, lock in list(locks.items()):
        if not isinstance(lock, dict):
            locks.pop(key, None)
            changed = True
            continue
        lock.setdefault("root", "project")
        lock.setdefault("path", ".")
        lock["scope_kind"] = _checkout_scope_kind(lock.get("scope_kind"))
        if not int(lock.get("lease_seconds") or 0):
            lock["lease_seconds"] = FILE_CHECKOUT_DEFAULT_LEASE_SEC
            changed = True
        if not int(lock.get("expires_at") or 0):
            lock["expires_at"] = int(lock.get("updated_at") or lock.get("created_at") or now_ts) + _checkout_lease_seconds(lock.get("lease_seconds"))
            changed = True
        if int(lock.get("expires_at") or 0) <= now_ts:
            promoted_key, promoted = _promote_next_checkout_lock(lock)
            locks.pop(key, None)
            if promoted_key and promoted:
                locks[promoted_key] = promoted
            changed = True
    if changed:
        payload["updated_at"] = now_ts
    return payload, changed

def _find_checkout_lock(
    state: dict[str, Any],
    root_name: str,
    rel_path: str,
    *,
    scope_kind: str = "exact",
    exclude_key: str = "",
) -> tuple[str | None, dict[str, Any] | None]:
    matches: list[tuple[str, dict[str, Any]]] = []
    for key, lock in (state.get("locks", {}) or {}).items():
        if key == exclude_key or not isinstance(lock, dict):
            continue
        if _lock_conflicts_with_scope(lock, root_name, rel_path, scope_kind):
            matches.append((key, lock))
    matches.sort(key=lambda row: _lock_sort_key(row[1], rel_path, scope_kind))
    return matches[0] if matches else (None, None)

def _file_checkout_public(lock: dict[str, Any]) -> dict[str, Any]:
    queue = lock.get("queue") if isinstance(lock.get("queue"), list) else []
    nudges = lock.get("nudges") if isinstance(lock.get("nudges"), list) else []
    return {
        "checkout_id": str(lock.get("checkout_id") or "").strip(),
        "root": str(lock.get("root") or "project").strip(),
        "path": str(lock.get("path") or "").strip(),
        "scope_kind": _checkout_scope_kind(lock.get("scope_kind")),
        "holder": str(lock.get("holder") or "").strip(),
        "session_id": str(lock.get("session_id") or "").strip(),
        "status": str(lock.get("status") or "checked_out").strip(),
        "note": str(lock.get("note") or "").strip(),
        "created_at": int(lock.get("created_at") or 0),
        "updated_at": int(lock.get("updated_at") or 0),
        "lease_seconds": _checkout_lease_seconds(lock.get("lease_seconds")),
        "expires_at": int(lock.get("expires_at") or 0),
        "queue_count": len(queue),
        "queue": [
            {
                "queue_id": str(row.get("queue_id") or "").strip(),
                "agent_key": str(row.get("agent_key") or "").strip(),
                "session_id": str(row.get("session_id") or "").strip(),
                "note": str(row.get("note") or "").strip(),
                "path": str(row.get("path") or "").strip(),
                "scope_kind": _checkout_scope_kind(row.get("scope_kind")),
                "created_at": int(row.get("created_at") or 0),
                "nudge_count": int(row.get("nudge_count") or 0),
                "lease_seconds": _checkout_lease_seconds(row.get("lease_seconds")),
                "has_patch_packet": bool(str(row.get("patch_packet") or "").strip()),
            }
            for row in queue[:20]
            if isinstance(row, dict)
        ],
        "latest_nudge": nudges[-1] if nudges else None,
    }

def _file_checkout_summary(rows: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        "active_lock_count": len(rows),
        "tree_lock_count": len([row for row in rows if row.get("scope_kind") == "tree"]),
        "exact_lock_count": len([row for row in rows if row.get("scope_kind") == "exact"]),
        "waiting_agent_count": sum(int(row.get("queue_count") or 0) for row in rows),
    }

def list_file_checkouts(root_name: str = "", rel_path: str = "") -> dict[str, Any]:
    state, changed = _prune_checkout_state(_load_file_checkout_state())
    if changed:
        _save_file_checkout_state(state)
    wanted_root = normalize_file_root(root_name) if str(root_name or "").strip() else ""
    wanted_path = ""
    if str(rel_path or "").strip():
        wanted_root, wanted_path = _normalize_locked_path(root_name or "project", rel_path, allow_directory=True)
    rows: list[dict[str, Any]] = []
    for lock in state.get("locks", {}).values():
        if not isinstance(lock, dict):
            continue
        if wanted_root and str(lock.get("root") or "").strip() != wanted_root:
            continue
        lock_path = str(lock.get("path") or "").strip() or "."
        if wanted_path and not (_path_within_scope(wanted_path, lock_path) or _path_within_scope(lock_path, wanted_path)):
            continue
        rows.append(_file_checkout_public(lock))
    rows.sort(key=lambda row: (int(row.get("updated_at") or 0), row.get("root") or "", row.get("path") or ""), reverse=True)
    return {"status": "ok", "rows": rows, "count": len(rows), "summary": _file_checkout_summary(rows), "updated_at": int(state.get("updated_at") or 0)}

def request_file_checkout(
    root_name: str,
    rel_path: str,
    *,
    agent_key: str = "",
    session_id: str = "",
    note: str = "",
    patch_packet: str = "",
    scope_kind: str = "exact",
    lease_seconds: int = FILE_CHECKOUT_DEFAULT_LEASE_SEC,
) -> dict[str, Any]:
    with FILE_CHECKOUT_STATE_GUARD:
        requested_scope = _checkout_scope_kind(scope_kind)
        normalized_root, normalized_path = _normalize_locked_path(root_name, rel_path, allow_directory=requested_scope == "tree")
        actor = _checkout_actor(agent_key, session_id)
        now_ts = int(time.time())
        state, changed = _prune_checkout_state(_load_file_checkout_state())
        if changed:
            _save_file_checkout_state(state)
        key = _file_checkout_key(normalized_root, normalized_path, requested_scope)
        locks = state.setdefault("locks", {})
        existing = locks.get(key) if isinstance(locks.get(key), dict) else None
        if existing:
            if actor == str(existing.get("holder") or "").strip():
                if note.strip():
                    existing["note"] = note.strip()[:600]
                if session_id.strip():
                    existing["session_id"] = session_id.strip()[:120]
                if patch_packet.strip():
                    nudges = existing.setdefault("nudges", [])
                    nudges.append(
                        {
                            "kind": "holder_patch",
                            "agent_key": actor,
                            "note": note.strip()[:600],
                            "patch_packet": patch_packet.strip()[:6000],
                            "created_at": now_ts,
                        }
                    )
                    existing["nudges"] = nudges[-25:]
                _refresh_checkout_lock(existing, lease_seconds)
                locks[key] = existing
                _save_file_checkout_state(state)
                return {"status": "checked_out", "lock": _file_checkout_public(existing), "reused": True}
            queue = existing.setdefault("queue", [])
            queued = None
            for row in queue:
                if not isinstance(row, dict):
                    continue
                if actor == str(row.get("agent_key") or "").strip():
                    queued = row
                    break
            if queued is None:
                queued = {
                    "queue_id": f"queue_{uuid.uuid4().hex[:10]}",
                    "root": normalized_root,
                    "path": normalized_path,
                    "scope_kind": requested_scope,
                    "agent_key": actor,
                    "session_id": session_id.strip()[:120],
                    "note": note.strip()[:600],
                    "patch_packet": patch_packet.strip()[:6000],
                    "created_at": now_ts,
                    "nudge_count": 0,
                    "lease_seconds": _checkout_lease_seconds(lease_seconds),
                }
                queue.append(queued)
            else:
                queued["updated_at"] = now_ts
                queued["lease_seconds"] = _checkout_lease_seconds(lease_seconds)
                if note.strip():
                    queued["note"] = note.strip()[:600]
                if patch_packet.strip():
                    queued["patch_packet"] = patch_packet.strip()[:6000]
            existing["queue"] = queue
            _refresh_checkout_lock(existing, lease_seconds)
            locks[key] = existing
            _save_file_checkout_state(state)
            position = next((idx + 1 for idx, row in enumerate(queue) if str(row.get("queue_id") or "").strip() == str(queued.get("queue_id") or "").strip()), len(queue))
            return {
                "status": "queued",
                "position": position,
                "lock": _file_checkout_public(existing),
                "queue_entry": {
                    "queue_id": str(queued.get("queue_id") or "").strip(),
                    "agent_key": actor,
                    "has_patch_packet": bool(str(queued.get("patch_packet") or "").strip()),
                },
            }
        conflict_key, conflict = _find_checkout_lock(state, normalized_root, normalized_path, scope_kind=requested_scope, exclude_key=key)
        if conflict:
            if actor == str(conflict.get("holder") or "").strip():
                return {
                    "status": "checked_out",
                    "lock": _file_checkout_public(conflict),
                    "reused": True,
                    "detail": "Actor already holds an overlapping checkout scope.",
                }
            return {
                "status": "blocked",
                "detail": f"{normalized_root}:{normalized_path} conflicts with active {conflict.get('scope_kind', 'exact')} checkout held by {str(conflict.get('holder') or 'another agent').strip() or 'another agent'}.",
                "lock": _file_checkout_public(conflict),
                "conflict_key": conflict_key,
            }
        lock = {
            "checkout_id": f"checkout_{uuid.uuid4().hex[:12]}",
            "root": normalized_root,
            "path": normalized_path,
            "scope_kind": requested_scope,
            "holder": actor,
            "session_id": session_id.strip()[:120],
            "status": "checked_out",
            "note": note.strip()[:600],
            "created_at": now_ts,
            "updated_at": now_ts,
            "lease_seconds": _checkout_lease_seconds(lease_seconds),
            "expires_at": now_ts + _checkout_lease_seconds(lease_seconds),
            "queue": [],
            "nudges": [],
        }
        if patch_packet.strip():
            lock["nudges"].append(
                {
                    "kind": "holder_patch",
                    "agent_key": actor,
                    "note": note.strip()[:600],
                    "patch_packet": patch_packet.strip()[:6000],
                    "created_at": now_ts,
                }
            )
        locks[key] = lock
        _save_file_checkout_state(state)
        return {"status": "checked_out", "lock": _file_checkout_public(lock), "reused": False}

def release_file_checkout(
    root_name: str,
    rel_path: str,
    *,
    checkout_id: str = "",
    agent_key: str = "",
    completion_note: str = "",
    scope_kind: str = "exact",
) -> dict[str, Any]:
    with FILE_CHECKOUT_STATE_GUARD:
        requested_scope = _checkout_scope_kind(scope_kind)
        normalized_root, normalized_path = _normalize_locked_path(root_name, rel_path, allow_directory=requested_scope == "tree")
        actor = _checkout_actor(agent_key, "")
        key = _file_checkout_key(normalized_root, normalized_path, requested_scope)
        state, changed = _prune_checkout_state(_load_file_checkout_state())
        if changed:
            _save_file_checkout_state(state)
        locks = state.setdefault("locks", {})
        existing = locks.get(key) if isinstance(locks.get(key), dict) else None
        if not existing:
            return {"status": "released", "detail": "No checkout was active for that file.", "lock": None}
        existing_id = str(existing.get("checkout_id") or "").strip()
        existing_holder = str(existing.get("holder") or "").strip()
        if checkout_id.strip() and checkout_id.strip() != existing_id:
            raise HTTPException(status_code=409, detail=f"Checkout mismatch. Active checkout: {existing_id}")
        if actor and actor != existing_holder and not request_has_trusted_web_control():
            raise HTTPException(status_code=403, detail=f"{normalized_root}:{normalized_path} is currently held by {existing_holder}")
        promoted_key, promoted = _promote_next_checkout_lock(existing)
        locks.pop(key, None)
        if promoted_key and promoted:
            locks[promoted_key] = promoted
        _save_file_checkout_state(state)
        return {
            "status": "released",
            "released_checkout_id": existing_id,
            "released_holder": existing_holder,
            "completion_note": completion_note.strip()[:600],
            "promoted": _file_checkout_public(promoted) if promoted else None,
        }

def nudge_file_checkout(
    root_name: str,
    rel_path: str,
    *,
    queue_id: str = "",
    agent_key: str = "",
    note: str = "",
    patch_packet: str = "",
) -> dict[str, Any]:
    with FILE_CHECKOUT_STATE_GUARD:
        normalized_root, normalized_path = _normalize_locked_path(root_name, rel_path, allow_directory=True)
        actor = _checkout_actor(agent_key, "")
        state, changed = _prune_checkout_state(_load_file_checkout_state())
        if changed:
            _save_file_checkout_state(state)
        key, existing = _find_checkout_lock(state, normalized_root, normalized_path, scope_kind="exact")
        if not existing:
            direct_key = _file_checkout_key(normalized_root, normalized_path, "exact")
            existing = state.get("locks", {}).get(direct_key)
            key = direct_key if isinstance(existing, dict) else None
        if not isinstance(existing, dict):
            raise HTTPException(status_code=404, detail="No active checkout found for that file.")
        queue = existing.get("queue") if isinstance(existing.get("queue"), list) else []
        matched_queue = None
        if queue_id.strip():
            for row in queue:
                if str(row.get("queue_id") or "").strip() == queue_id.strip():
                    matched_queue = row
                    break
        nudges = existing.setdefault("nudges", [])
        nudges.append(
            {
                "kind": "queue_nudge",
                "agent_key": actor,
                "queue_id": queue_id.strip(),
                "target_holder": str(existing.get("holder") or "").strip(),
                "note": note.strip()[:600],
                "patch_packet": patch_packet.strip()[:6000],
                "created_at": int(time.time()),
            }
        )
        existing["nudges"] = nudges[-25:]
        if matched_queue is not None:
            matched_queue["nudge_count"] = int(matched_queue.get("nudge_count") or 0) + 1
            if note.strip():
                matched_queue["note"] = note.strip()[:600]
            if patch_packet.strip():
                matched_queue["patch_packet"] = patch_packet.strip()[:6000]
        existing["updated_at"] = int(time.time())
        if key:
            state.setdefault("locks", {})[key] = existing
            _save_file_checkout_state(state)
        return {"status": "nudge_recorded", "lock": _file_checkout_public(existing)}

def enforce_file_checkout(root_name: str, rel_path: str, checkout_id: str = "", agent_key: str = ""):
    with FILE_CHECKOUT_STATE_GUARD:
        normalized_root, normalized_path = _normalize_locked_path(root_name, rel_path)
        state, changed = _prune_checkout_state(_load_file_checkout_state())
        if changed:
            _save_file_checkout_state(state)
        actor = _checkout_actor(agent_key, "")
        conflicts: list[dict[str, Any]] = []
        for lock in state.get("locks", {}).values():
            if not isinstance(lock, dict):
                continue
            if _lock_conflicts_with_scope(lock, normalized_root, normalized_path, "exact"):
                conflicts.append(lock)
        if not conflicts:
            raise HTTPException(
                status_code=409,
                detail=f"No active checkout covers {normalized_root}:{normalized_path}. Acquire checkout before writing.",
            )
        for lock in sorted(conflicts, key=lambda row: _lock_sort_key(row, normalized_path, "exact")):
            active_id = str(lock.get("checkout_id") or "").strip()
            active_holder = str(lock.get("holder") or "").strip()
            if checkout_id.strip() and checkout_id.strip() == active_id:
                return
            if actor and actor == active_holder:
                return
        primary = sorted(conflicts, key=lambda row: _lock_sort_key(row, normalized_path, "exact"))[0]
        scope_kind = _checkout_scope_kind(primary.get("scope_kind"))
        active_holder = str(primary.get("holder") or "").strip()
        raise HTTPException(
            status_code=409,
            detail=(
                f"{normalized_root}:{normalized_path} is covered by an active {scope_kind} checkout held by "
                f"{active_holder or 'another agent'}. Wait for release or send a nudge."
            ),
        )

def list_paths(root: Path, rel_path: str = "", limit: int = 500) -> list[str]:
    target = safe_under(root, rel_path or ".")
    items: list[str] = []
    if target.is_file():
        return [str(target.relative_to(root)).replace("\\", "/")]
    for p in target.rglob("*"):
        if len(items) >= limit:
            break
        if p.is_file():
            items.append(str(p.relative_to(root)).replace("\\", "/"))
    return items

def read_text(root: Path, rel_path: str, max_bytes: int = 1_000_000) -> str:
    target = safe_under(root, rel_path)
    if not target.exists() or not target.is_file():
        raise HTTPException(status_code=404, detail="File not found")
    data = target.read_bytes()
    if len(data) > max_bytes:
        raise HTTPException(status_code=400, detail=f"File too large ({len(data)} bytes)")
    return data.decode("utf-8", errors="ignore")

def write_text(root: Path, rel_path: str, content: str) -> Path:
    target = safe_under(root, rel_path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")
    return target


def _safe_project_dir_name(title: str, project_key: str) -> str:
    preferred = str(title or pretty_label(project_key)).strip() or pretty_label(project_key)
    cleaned = "".join(ch for ch in preferred if ch.isalnum() or ch in {" ", "-", "_"}).strip().rstrip(".")
    return cleaned or pretty_label(project_key)


def _resolve_workspace_project_root(path_text: str, registry_row: dict[str, Any] | None = None) -> Path:
    raw = str(path_text or "").strip()
    if raw:
        normalized = raw.replace("\\", "/")
        prefix = WINDOWS_WORKSPACE_PREFIX
        if prefix and normalized.lower().startswith(prefix):
            suffix = normalized[len(prefix):].lstrip("/")
            translated = WORKSPACE_ATLAS_ROOT / Path(suffix)
            return translated
        candidate = Path(raw)
        if candidate.exists():
            return candidate
        deploy_target = registry_row.get("deploy_target") if isinstance(registry_row, dict) and isinstance(registry_row.get("deploy_target"), dict) else {}
        deploy_root = str(deploy_target.get("workdir") or deploy_target.get("apply_path") or "").strip()
        if deploy_root:
            deploy_candidate = Path(deploy_root)
            if deploy_candidate.exists():
                return deploy_candidate
        return candidate
    return WORKSPACE_ATLAS_ROOT


def _upsert_workspace_registry_project(row: dict[str, Any]) -> dict[str, Any]:
    registry = load_workspace_registry_profile()
    rows = [item for item in registry.get("projects", []) if isinstance(item, dict)]
    key = normalize_project_key(row.get("project_key"))
    if not key:
        raise HTTPException(status_code=400, detail="Invalid workspace project key")
    existing_index = -1
    existing = {}
    for idx, item in enumerate(rows):
        if normalize_project_key(item.get("project_key")) == key:
            existing_index = idx
            existing = item
            break
    merged = {**existing, **row, "project_key": key}
    if existing_index >= 0:
        rows[existing_index] = merged
    else:
        rows.append(merged)
    registry["projects"] = sorted(rows, key=lambda item: int(item.get("priority") or 0), reverse=True)
    _write_json(WORKSPACE_REGISTRY_PATH, registry)
    return merged


def _upsert_workspace_connection_ref(row: dict[str, Any]) -> dict[str, Any]:
    registry = load_workspace_connections_profile()
    rows = [item for item in registry.get("connections", []) if isinstance(item, dict)]
    key = str(row.get("key") or "").strip()
    if not key:
        raise HTTPException(status_code=400, detail="Connection ref key is required")
    existing_index = -1
    existing = {}
    for idx, item in enumerate(rows):
        if str(item.get("key") or "").strip() == key:
            existing_index = idx
            existing = item
            break
    merged = {**existing, **row, "key": key}
    if existing_index >= 0:
        rows[existing_index] = merged
    else:
        rows.append(merged)
    registry["connections"] = rows
    _write_json(WORKSPACE_CONNECTIONS_PATH, registry)
    return merged


def _write_if_missing(path: Path, content: str) -> None:
    if path.exists():
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")

def _string_list(value: Any) -> list[str]:
    if not isinstance(value, list):
        return []
    rows: list[str] = []
    for item in value:
        text = str(item or "").strip()
        if text:
            rows.append(text)
    return rows

def _render_project_template_text(template: str, values: dict[str, Any]) -> str:
    rendered = str(template or "")
    for key, value in values.items():
        rendered = rendered.replace(f"{{{{{key}}}}}", str(value or ""))
    return rendered

def _seed_template_tree(root: Path, template: dict[str, Any], dir_key: str, file_key: str, values: dict[str, Any]) -> dict[str, Any]:
    created_dirs: list[str] = []
    written_files: list[str] = []
    for rel in _string_list(template.get(dir_key)):
        target = safe_under(root, rel)
        if target.exists():
            continue
        target.mkdir(parents=True, exist_ok=True)
        created_dirs.append(str(target))
    for row in template.get(file_key, []) if isinstance(template.get(file_key), list) else []:
        if not isinstance(row, dict):
            continue
        rel = str(row.get("path") or "").strip().replace("\\", "/")
        if not rel:
            continue
        target = safe_under(root, rel)
        if target.exists():
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        content = _render_project_template_text(str(row.get("content") or ""), values)
        target.write_text(content.rstrip() + "\n", encoding="utf-8")
        written_files.append(str(target))
    return {"directories": created_dirs, "files": written_files}


def _workspace_project_root(project_key: str, *, ensure_exists: bool = False) -> Path:
    key = normalize_project_key(project_key)
    if not key:
        raise HTTPException(status_code=400, detail="Invalid project key")
    registry_row = workspace_registry_project(key)
    candidates: list[Path] = []
    root_text = str(registry_row.get("root_path") or "").strip()
    if root_text:
        candidates.append(_resolve_workspace_project_root(root_text, registry_row=registry_row))
    candidates.extend(
        [
            PROJECTS_ROOT / key,
            WORKSPACE_ROOT / key,
            WORKSPACE_ATLAS_ROOT / _safe_project_dir_name(str(registry_row.get("display_name") or pretty_label(key)).strip(), key),
        ]
    )
    for candidate in candidates:
        if ensure_exists:
            candidate.mkdir(parents=True, exist_ok=True)
            return candidate
        if candidate.exists():
            return candidate
    target = candidates[0]
    if ensure_exists:
        target.mkdir(parents=True, exist_ok=True)
    return target


def _project_codex_paths(project_key: str, *, ensure_root: bool = False) -> dict[str, Path]:
    project_root = _workspace_project_root(project_key, ensure_exists=ensure_root)
    codex_root = project_root / PROJECT_CODEX_DIRNAME
    paths = {
        "project_root": project_root,
        "codex_root": codex_root,
        "thread_path": codex_root / "thread.json",
        "instructions_path": codex_root / "instructions.md",
        "suggestions_root": codex_root / "suggestions",
        "receipts_root": codex_root / "receipts",
        "artifacts_root": codex_root / "artifacts",
    }
    if ensure_root:
        codex_root.mkdir(parents=True, exist_ok=True)
        paths["suggestions_root"].mkdir(parents=True, exist_ok=True)
        paths["receipts_root"].mkdir(parents=True, exist_ok=True)
        paths["artifacts_root"].mkdir(parents=True, exist_ok=True)
    return paths


def _project_codex_placeholder(path: Path, note: str) -> None:
    placeholder = path / ".gitkeep"
    if not placeholder.exists():
        placeholder.write_text(note.strip() + "\n", encoding="utf-8")


def _project_codex_assigned_workers(project_key: str, registry_row: dict[str, Any], profile_row: dict[str, Any], existing: dict[str, Any]) -> list[str]:
    rows: list[str] = []
    for item in existing.get("assigned_workers", []) if isinstance(existing.get("assigned_workers"), list) else []:
        text = str(item or "").strip()
        if text:
            rows.append(text)
    owner = str(registry_row.get("role_owner") or profile_row.get("owner") or "zeus").strip().lower() or "zeus"
    defaults = [owner, "hive-director", "hermes-messenger", "qa-lead"]
    if normalize_project_key(project_key) in LIFE_OPS_PROJECT_KEYS:
        defaults.extend(["zeus-presence", "life-business-wealth", "life-food-health-family", "life-motivation-fitness"])
    if normalize_project_key(project_key) == "underfoot":
        defaults.extend(["darius-unity-bot", "lumi-3d-engineer"])
    deduped: list[str] = []
    for item in rows + defaults:
        text = str(item or "").strip()
        if text and text not in deduped:
            deduped.append(text)
    return deduped


def _preferred_project_escalation_model(project_key: str, registry_row: dict[str, Any], profile_row: dict[str, Any], existing: dict[str, Any]) -> str:
    current = str(
        existing.get("preferred_escalation_model")
        or profile_row.get("preferred_escalation_model")
        or registry_row.get("preferred_escalation_model")
        or ""
    ).strip()
    if _is_allowed_cloud_model(current):
        return current
    key = normalize_project_key(project_key)
    if key in LIFE_OPS_PROJECT_KEYS or key in {"zeus-presence", "luminax", "epoch-portal"}:
        return "gpt-5.4-mini"
    return "gpt-5.4"


def _project_codex_suggestion_rows(project_key: str) -> list[dict[str, Any]]:
    paths = _project_codex_paths(project_key, ensure_root=False)
    suggestions_root = paths["suggestions_root"]
    if not suggestions_root.exists():
        return []
    rows: list[dict[str, Any]] = []
    for path in sorted(suggestions_root.glob("*.json")):
        payload = _read_json(path)
        title = str(payload.get("title") or path.stem).strip() if isinstance(payload, dict) else path.stem
        status = str(payload.get("status") or "queued").strip() if isinstance(payload, dict) else "queued"
        review_state = str(payload.get("review_state") or "pending_review").strip() if isinstance(payload, dict) else "pending_review"
        rows.append(
            {
                "suggestion_id": str(payload.get("suggestion_id") or path.stem).strip() if isinstance(payload, dict) else path.stem,
                "title": title[:180],
                "status": status or "queued",
                "review_state": review_state or "pending_review",
                "requested_by": str(payload.get("requested_by") or "").strip() if isinstance(payload, dict) else "",
                "source": str(payload.get("source") or "").strip() if isinstance(payload, dict) else "",
                "created_at": int(payload.get("created_at") or 0) if isinstance(payload, dict) else 0,
                "path": str(path),
            }
        )
    rows.sort(key=lambda item: (int(item.get("created_at") or 0), str(item.get("suggestion_id") or "")), reverse=True)
    return rows[:80]


def _project_codex_review_queue(session_rows: list[dict[str, Any]], suggestion_rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    queue: list[dict[str, Any]] = []
    for row in session_rows[:40]:
        questions = row.get("questions_pending", []) if isinstance(row.get("questions_pending"), list) else []
        if questions or str(row.get("last_status") or "").strip().lower() in {"blocked", "failed", "review"}:
            queue.append(
                {
                    "kind": "session",
                    "id": str(row.get("session_id") or "").strip(),
                    "summary": str(row.get("last_summary") or row.get("goal") or row.get("title") or "").strip()[:240],
                    "status": str(row.get("last_status") or "").strip() or "idle",
                }
            )
    for row in suggestion_rows[:40]:
        if str(row.get("status") or "").strip().lower() not in {"done", "approved", "resolved"}:
            queue.append(
                {
                    "kind": "suggestion",
                    "id": str(row.get("suggestion_id") or "").strip(),
                    "summary": str(row.get("title") or "").strip()[:240],
                    "status": str(row.get("review_state") or row.get("status") or "").strip() or "pending_review",
                }
            )
    return queue[:40]


def _render_project_codex_instructions(
    project_key: str,
    *,
    registry_row: dict[str, Any],
    profile_row: dict[str, Any],
    atlas_row: dict[str, Any],
    paths: dict[str, Path],
    thread_doc: dict[str, Any],
) -> str:
    key = normalize_project_key(project_key) or ""
    display_name = str(registry_row.get("display_name") or profile_row.get("display_name") or pretty_label(key)).strip() or pretty_label(key)
    required_context_files = profile_row.get("required_context_files") if isinstance(profile_row.get("required_context_files"), list) else []
    review_commands = registry_row.get("review_commands") if isinstance(registry_row.get("review_commands"), list) else []
    test_commands = registry_row.get("test_commands") if isinstance(registry_row.get("test_commands"), list) else []
    local_test_commands = registry_row.get("local_test_commands") if isinstance(registry_row.get("local_test_commands"), list) else []
    live_change = profile_row.get("live_change_policy") if isinstance(profile_row.get("live_change_policy"), dict) else {}
    verification_profile = profile_row.get("verification_profile") if isinstance(profile_row.get("verification_profile"), dict) else {}
    lines = [
        f"# Codex Thread Instructions: {display_name}",
        "",
        f"- Project key: `{key}`",
        f"- Project root: `{paths['project_root']}`",
        f"- Thread manifest: `{paths['thread_path']}`",
        f"- Suggestions inbox: `{paths['suggestions_root']}`",
        f"- Template version: `{PROJECT_CODEX_TEMPLATE_VERSION}`",
        "",
        "## Source Of Truth",
        f"- `/{PROJECT_CODEX_DIRNAME}/thread.json` is the implementation source of truth for this project.",
        "- Keep the manifest, instructions, and suggestions inbox current after every meaningful change.",
        "- Project work should happen in the project Codex thread or through a suggestion submitted into that thread.",
        "",
        "## Professional Worker Standard",
        "- No slop, no filler. Updates must be precise, professional, and scoped to the actual work.",
        "- Self-correction is mandatory. Double-check changes, assumptions, and diagnostics before handing them back.",
        "- Review-first. Ask for review or queue review state before treating the result as good.",
        "- Documentation hygiene is mandatory. Update manifests, instructions, and receipts immediately after changes.",
        "",
        "## Execution Rules",
        "- Respect project scope boundaries and do not spill edits into unrelated projects.",
        "- Use existing env files and declared connection refs instead of inventing secrets or hidden config.",
        "- Prefer full-access execution only when the project policy and active maintenance guard allow it.",
        "- Keep runtime and queue changes breadcrumbed. Silent failure or silent drift is not acceptable.",
        "- If a route, assignment, handoff, or fallback changes, write a diagnostic breadcrumb and capture the why.",
        "",
        "## Review And Verification",
        f"- Latest review state: `{str(thread_doc.get('latest_review_state') or 'pending_review').strip() or 'pending_review'}`",
        f"- Review summary: `{str(thread_doc.get('review_state_summary') or 'review_required').strip() or 'review_required'}`",
        "- Before submission, confirm what changed, what was verified, and what still needs review.",
    ]
    if review_commands:
        lines.append("- Review commands:")
        lines.extend([f"  - `{cmd}`" for cmd in review_commands])
    if test_commands or local_test_commands:
        lines.append("- Test commands:")
        for cmd in (local_test_commands or test_commands):
            lines.append(f"  - `{cmd}`")
    rollback_notes = verification_profile.get("rollback_notes") if isinstance(verification_profile.get("rollback_notes"), list) else []
    if rollback_notes:
        lines.append("- Rollback notes:")
        lines.extend([f"  - {str(item).strip()}" for item in rollback_notes if str(item).strip()])
    lines.extend(
        [
            "",
            "## Diagnostics",
            "- All runtime, voice, queue, allocator, matchmaking, and scene-flow changes must emit structured breadcrumbs.",
            "- Critical flows must not fail as silent spinners.",
            "- Degraded or stuck states must write a diagnostic receipt with recent breadcrumbs.",
            "",
            "## Live Change Policy",
            f"- Mode: `{str(live_change.get('mode') or 'guarded_live').strip() or 'guarded_live'}`",
            f"- Requires project scope: `{bool(live_change.get('requires_project_scope', True))}`",
            f"- Requires local tests: `{bool(live_change.get('requires_local_tests', True))}`",
            f"- Requires remote verification: `{bool(live_change.get('requires_remote_verification', True))}`",
            f"- Ask when unknown: `{bool(live_change.get('asks_when_unknown', True))}`",
            "",
            "## Required Context Files",
        ]
    )
    context_rows = required_context_files or ["README.md", "portal.json", "nameplate.txt", "details.txt"]
    for item in context_rows:
        lines.append(f"- `{item}`")
    lines.extend(
        [
            "",
            "## Project Notes",
            f"- Purpose: {str(registry_row.get('purpose') or profile_row.get('summary') or '').strip() or 'Bootstrap project managed by Mount Olympus.'}",
            f"- Owner lane: `{str(registry_row.get('role_owner') or profile_row.get('owner') or 'zeus').strip() or 'zeus'}`",
            f"- Atlas path: `{str(atlas_row.get('atlas_path') or registry_row.get('atlas_paths', {}).get('project_atlas') or paths['project_root'] / 'PROJECT_ATLAS.md')}`",
        ]
    )
    return "\n".join(lines).strip() + "\n"


def _sync_project_codex_metadata(
    project_key: str,
    *,
    thread_doc: dict[str, Any],
    paths: dict[str, Path],
    registry_row: dict[str, Any],
    profile_row: dict[str, Any],
) -> dict[str, Any]:
    key = normalize_project_key(project_key)
    if not key:
        return {}
    codex_summary = {
        "template_version": PROJECT_CODEX_TEMPLATE_VERSION,
        "status": str(thread_doc.get("thread_status") or "ready").strip() or "ready",
        "review_state_summary": str(thread_doc.get("review_state_summary") or thread_doc.get("latest_review_state") or "pending_review").strip() or "pending_review",
        "preferred_escalation_model": str(thread_doc.get("preferred_escalation_model") or "gpt-5.4-mini").strip() or "gpt-5.4-mini",
        "thread_path": str(paths["thread_path"]),
        "instructions_path": str(paths["instructions_path"]),
        "suggestions_path": str(paths["suggestions_root"]),
        "updated_at": int(thread_doc.get("updated_at") or time.time()),
    }
    notification_policy = {
        "mode": "waking_hours_only" if key in LIFE_OPS_PROJECT_KEYS else "manual",
        "timezone": "America/New_York",
        "start_hour": DEFAULT_LIFE_OPS_WAKE_START_HOUR,
        "end_hour": DEFAULT_LIFE_OPS_WAKE_END_HOUR,
    }
    existing_life_ops_policy = registry_row.get("life_ops_notification_policy") if isinstance(registry_row.get("life_ops_notification_policy"), dict) else {}
    existing_waking_policy = registry_row.get("waking_hours_notification_policy") if isinstance(registry_row.get("waking_hours_notification_policy"), dict) else {}
    _upsert_workspace_registry_project(
        {
            "project_key": key,
            "codex_thread_required": True,
            "active_thread_status": codex_summary["status"],
            "review_state_summary": codex_summary["review_state_summary"],
            "codex_thread_template_version": PROJECT_CODEX_TEMPLATE_VERSION,
            "codex_thread_status": codex_summary["status"],
            "codex_review_state_summary": codex_summary["review_state_summary"],
            "preferred_escalation_model": codex_summary["preferred_escalation_model"],
            "codex_thread": codex_summary,
            "life_ops_notification_policy": notification_policy if key in LIFE_OPS_PROJECT_KEYS else existing_life_ops_policy,
            "waking_hours_notification_policy": notification_policy if key in LIFE_OPS_PROJECT_KEYS else existing_waking_policy,
        }
    )
    profile_path = OLYMPUS_PROFILE_ROOT / "projects" / f"{key}.json"
    profile_payload = {
        **profile_row,
        "key": key,
        "root_path": str(paths["project_root"]),
        "codex_thread_required": True,
        "active_thread_status": codex_summary["status"],
        "review_state_summary": codex_summary["review_state_summary"],
        "preferred_escalation_model": codex_summary["preferred_escalation_model"],
        "codex_thread": {
            **(profile_row.get("codex_thread") if isinstance(profile_row.get("codex_thread"), dict) else {}),
            **codex_summary,
        },
    }
    if key in LIFE_OPS_PROJECT_KEYS:
        profile_payload["life_ops_notification_policy"] = notification_policy
        profile_payload["waking_hours_notification_policy"] = notification_policy
        profile_payload["discord_branding"] = {
            **(profile_row.get("discord_branding") if isinstance(profile_row.get("discord_branding"), dict) else {}),
            "guild_blueprint_key": LIFE_OPS_GUILD_BLUEPRINT_KEY,
        }
    _write_json(profile_path, profile_payload)
    return codex_summary


def bootstrap_or_repair_project_codex_thread(project_key: str, *, reason: str = "", force: bool = False) -> dict[str, Any]:
    key = normalize_project_key(project_key)
    if not key:
        raise HTTPException(status_code=400, detail="Invalid project key")
    registry_row = workspace_registry_project(key)
    profile_row = olympus_project_profile_for_workspace_project(key)
    atlas_row = workspace_atlas_project(key)
    paths = _project_codex_paths(key, ensure_root=True)
    _project_codex_placeholder(paths["suggestions_root"], "Queued suggestion files for the project Codex thread.")
    _project_codex_placeholder(paths["receipts_root"], "Execution and review receipts for the project Codex thread.")
    _project_codex_placeholder(paths["artifacts_root"], "Thread artifacts and review outputs.")
    existing = _read_json(paths["thread_path"]) if paths["thread_path"].exists() else {}
    sessions_payload = list_codex_sessions(limit=80, project_key=key) if key else {"rows": []}
    session_rows = sessions_payload.get("rows") if isinstance(sessions_payload.get("rows"), list) else []
    suggestion_rows = _project_codex_suggestion_rows(key)
    review_queue = _project_codex_review_queue(session_rows, suggestion_rows)
    outstanding_blockers = existing.get("outstanding_blockers", []) if isinstance(existing.get("outstanding_blockers"), list) else []
    assigned_workers = _project_codex_assigned_workers(key, registry_row, profile_row, existing)
    preferred_escalation_model = _preferred_project_escalation_model(key, registry_row, profile_row, existing)
    latest_review_state = str(existing.get("latest_review_state") or "").strip()
    if not latest_review_state:
        latest_review_state = "blocked" if outstanding_blockers else ("pending_review" if review_queue else "approved")
    review_state_summary = "blocked" if outstanding_blockers else ("review_required" if review_queue else "good")
    thread_status = "blocked" if outstanding_blockers else ("attention_needed" if review_queue else "ready")
    ts = int(time.time())
    thread_doc = {
        **existing,
        "version": PROJECT_CODEX_TEMPLATE_VERSION,
        "tool": "codex_thread",
        "project_key": key,
        "display_name": str(registry_row.get("display_name") or profile_row.get("display_name") or pretty_label(key)).strip() or pretty_label(key),
        "project_root": str(paths["project_root"]),
        "thread_status": thread_status,
        "execution_mode": "project_thread",
        "preferred_workdir": str(existing.get("preferred_workdir") or registry_row.get("default_workdir") or ".").strip() or ".",
        "preferred_escalation_model": preferred_escalation_model,
        "assigned_workers": assigned_workers,
        "active_codex_session_ids": [str(row.get("session_id") or "").strip() for row in session_rows if str(row.get("session_id") or "").strip()][:24],
        "latest_review_state": latest_review_state,
        "review_state_summary": review_state_summary,
        "review_queue": review_queue,
        "outstanding_blockers": [item for item in outstanding_blockers if str(item or "").strip()][:24],
        "pending_suggestions": suggestion_rows[:24],
        "required_context_files": profile_row.get("required_context_files") if isinstance(profile_row.get("required_context_files"), list) else ["README.md", "portal.json", "nameplate.txt", "details.txt"],
        "live_change_policy": profile_row.get("live_change_policy") if isinstance(profile_row.get("live_change_policy"), dict) else {},
        "verification_profile": profile_row.get("verification_profile") if isinstance(profile_row.get("verification_profile"), dict) else {},
        "worker_mandate": {
            "no_slop_no_filler": True,
            "self_correction_required": True,
            "review_first": True,
            "documentation_hygiene_required": True,
        },
        "schedule": {
            "zeus_heavy_sweep_sec": DEFAULT_ZEUS_HEAVY_SWEEP_SEC,
            "life_ops_internal_review_sec": DEFAULT_LIFE_OPS_INTERNAL_REVIEW_SEC if key in LIFE_OPS_PROJECT_KEYS else 0,
            "life_ops_user_outreach_mode": "waking_hours_only" if key in LIFE_OPS_PROJECT_KEYS else "manual",
            "life_ops_waking_hours": {
                "timezone": "America/New_York",
                "start_hour": DEFAULT_LIFE_OPS_WAKE_START_HOUR,
                "end_hour": DEFAULT_LIFE_OPS_WAKE_END_HOUR,
            },
        },
        "sync": {
            "reason": str(reason or existing.get("sync", {}).get("reason") or "bootstrap").strip()[:240],
            "last_synced_at": ts,
            "last_bootstrap_at": int(existing.get("sync", {}).get("last_bootstrap_at") or ts),
        },
        "updated_at": ts,
        "created_at": int(existing.get("created_at") or ts),
    }
    instructions_text = _render_project_codex_instructions(
        key,
        registry_row=registry_row,
        profile_row=profile_row,
        atlas_row=atlas_row,
        paths=paths,
        thread_doc=thread_doc,
    )
    if force or not paths["instructions_path"].exists() or paths["instructions_path"].read_text(encoding="utf-8", errors="ignore") != instructions_text:
        paths["instructions_path"].write_text(instructions_text, encoding="utf-8")
    _write_json(paths["thread_path"], thread_doc)
    metadata = _sync_project_codex_metadata(key, thread_doc=thread_doc, paths=paths, registry_row=registry_row, profile_row=profile_row)
    _append_runtime_diagnostic_receipt(
        {
            "event": "project_codex_thread_sync",
            "stage": "thread_sync",
            "severity": "warn" if thread_status != "ready" else "info",
            "scene": "assistant-core",
            "route": "codex/threads/bootstrap",
            "connection": {"project": key, "thread_status": thread_status, "review_state": latest_review_state},
            "summary": f"Project Codex thread synced for {key}",
            "details": json.dumps(
                _json_ready(
                    {
                        "reason": reason or "bootstrap",
                        "pending_suggestions": len(suggestion_rows),
                        "active_sessions": len(thread_doc.get("active_codex_session_ids") or []),
                        "review_queue": len(review_queue),
                        "metadata": metadata,
                    }
                ),
                ensure_ascii=False,
            ),
        }
    )
    return {
        "status": "ok",
        "project_key": key,
        "paths": {name: str(path) for name, path in paths.items()},
        "thread": thread_doc,
        "metadata": metadata,
    }


def load_project_codex_thread(project_key: str, *, bootstrap_missing: bool = False) -> dict[str, Any]:
    key = normalize_project_key(project_key)
    if not key:
        return {}
    paths = _project_codex_paths(key, ensure_root=bootstrap_missing)
    if not paths["thread_path"].exists():
        if bootstrap_missing:
            return bootstrap_or_repair_project_codex_thread(key, reason="load_missing").get("thread", {})
        return {}
    payload = _read_json(paths["thread_path"])
    return payload if isinstance(payload, dict) else {}


def list_project_codex_threads(limit: int = 80, project_key: str = "", bootstrap_missing: bool = False) -> dict[str, Any]:
    target = normalize_project_key(project_key)
    registry = load_workspace_registry_profile()
    rows: list[dict[str, Any]] = []
    for raw in registry.get("projects", []) if isinstance(registry.get("projects"), list) else []:
        if not isinstance(raw, dict):
            continue
        key = normalize_project_key(raw.get("project_key"))
        if not key or (target and key != target):
            continue
        thread_doc = load_project_codex_thread(key, bootstrap_missing=bootstrap_missing)
        if not thread_doc and bootstrap_missing:
            thread_doc = bootstrap_or_repair_project_codex_thread(key, reason="list_bootstrap").get("thread", {})
        paths = _project_codex_paths(key, ensure_root=False)
        rows.append(
            {
                "project_key": key,
                "display_name": str(raw.get("display_name") or pretty_label(key)).strip() or pretty_label(key),
                "project_root": str(paths["project_root"]),
                "thread_status": str(thread_doc.get("thread_status") or ("missing" if not paths["thread_path"].exists() else "unknown")).strip(),
                "review_state_summary": str(thread_doc.get("review_state_summary") or thread_doc.get("latest_review_state") or "").strip() or "unknown",
                "preferred_escalation_model": str(thread_doc.get("preferred_escalation_model") or raw.get("preferred_escalation_model") or "gpt-5.4-mini").strip(),
                "active_codex_session_ids": thread_doc.get("active_codex_session_ids", [])[:12] if isinstance(thread_doc.get("active_codex_session_ids"), list) else [],
                "pending_suggestions": len(thread_doc.get("pending_suggestions", []) if isinstance(thread_doc.get("pending_suggestions"), list) else []),
                "thread_path": str(paths["thread_path"]),
                "instructions_path": str(paths["instructions_path"]),
                "updated_at": int(thread_doc.get("updated_at") or 0),
            }
        )
    rows.sort(key=lambda item: (str(item.get("thread_status") or "") != "ready", -(int(item.get("updated_at") or 0)), str(item.get("project_key") or "")))
    limited = rows[: max(1, min(int(limit or 80), 200))]
    summary = {
        "count": len(limited),
        "missing": len([row for row in limited if row.get("thread_status") == "missing"]),
        "attention_needed": len([row for row in limited if row.get("thread_status") in {"attention_needed", "blocked"}]),
        "ready": len([row for row in limited if row.get("thread_status") == "ready"]),
    }
    return {"status": "ok", "summary": summary, "rows": limited, "project_key": target or None}


def submit_project_codex_suggestion(
    project_key: str,
    *,
    title: str,
    body: str,
    requested_by: str = "operator",
    source: str = "assistant-core",
    suggestion_kind: str = "suggestion",
    meta: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    key = normalize_project_key(project_key)
    if not key:
        raise HTTPException(status_code=400, detail="Invalid project key")
    safe_title = str(title or body or "Project suggestion").strip()
    safe_body = str(body or "").strip()
    if not safe_body:
        raise HTTPException(status_code=400, detail="Suggestion body is required")
    paths = _project_codex_paths(key, ensure_root=True)
    suggestion_id = f"suggestion_{int(time.time())}_{uuid.uuid4().hex[:8]}"
    payload = {
        "suggestion_id": suggestion_id,
        "project_key": key,
        "title": safe_title[:180] or "Project suggestion",
        "body": safe_body[:20000],
        "requested_by": str(requested_by or "operator").strip()[:120] or "operator",
        "source": str(source or "assistant-core").strip()[:180] or "assistant-core",
        "kind": str(suggestion_kind or "suggestion").strip()[:60] or "suggestion",
        "status": "queued",
        "review_state": "pending_review",
        "created_at": int(time.time()),
        "meta": meta if isinstance(meta, dict) else {},
    }
    _write_json(paths["suggestions_root"] / f"{suggestion_id}.json", payload)
    thread_state = bootstrap_or_repair_project_codex_thread(key, reason="suggestion_submitted")
    _append_runtime_diagnostic_receipt(
        {
            "event": "project_codex_suggestion_submitted",
            "stage": "suggestion_queued",
            "severity": "info",
            "scene": "assistant-core",
            "route": "codex/threads/suggestion",
            "connection": {"project": key, "suggestion_id": suggestion_id},
            "summary": f"Suggestion queued for {key}",
            "details": json.dumps(_json_ready({"title": payload["title"], "requested_by": payload["requested_by"], "source": payload["source"]}), ensure_ascii=False),
        }
    )
    return {"status": "ok", "suggestion": payload, "thread": thread_state.get("thread")}


def mark_project_codex_review_state(
    project_key: str,
    *,
    review_state: str,
    note: str = "",
    session_id: str = "",
    blocker: str = "",
) -> dict[str, Any]:
    key = normalize_project_key(project_key)
    if not key:
        raise HTTPException(status_code=400, detail="Invalid project key")
    payload = load_project_codex_thread(key, bootstrap_missing=True)
    safe_review = str(review_state or "").strip().lower() or "pending_review"
    if safe_review not in {"pending_review", "review_requested", "approved", "good", "blocked", "rejected"}:
        safe_review = "pending_review"
    blockers = payload.get("outstanding_blockers", []) if isinstance(payload.get("outstanding_blockers"), list) else []
    safe_blocker = str(blocker or "").strip()
    if safe_blocker and safe_blocker not in blockers:
        blockers.append(safe_blocker)
    if safe_review in {"approved", "good"}:
        blockers = []
    payload["latest_review_state"] = safe_review
    payload["review_state_summary"] = "good" if safe_review in {"approved", "good"} else ("blocked" if safe_review == "blocked" else "review_required")
    payload["thread_status"] = "blocked" if blockers else ("ready" if safe_review in {"approved", "good"} else "attention_needed")
    payload["outstanding_blockers"] = blockers[:24]
    payload["updated_at"] = int(time.time())
    payload.setdefault("review_history", [])
    payload["review_history"] = (
        [
            {
                "review_state": safe_review,
                "note": str(note or "").strip()[:1200],
                "session_id": str(session_id or "").strip()[:120],
                "created_at": int(time.time()),
            }
        ]
        + [row for row in payload.get("review_history", []) if isinstance(row, dict)]
    )[:40]
    paths = _project_codex_paths(key, ensure_root=True)
    _write_json(paths["thread_path"], payload)
    _sync_project_codex_metadata(key, thread_doc=payload, paths=paths, registry_row=workspace_registry_project(key), profile_row=olympus_project_profile_for_workspace_project(key))
    _append_runtime_diagnostic_receipt(
        {
            "event": "project_codex_review_state_changed",
            "stage": "review_state",
            "severity": "warn" if safe_review == "blocked" else "info",
            "scene": "assistant-core",
            "route": "codex/threads/review",
            "connection": {"project": key, "review_state": safe_review},
            "summary": f"Review state updated for {key}",
            "details": json.dumps(_json_ready({"note": str(note or "").strip(), "session_id": str(session_id or "").strip(), "blocker": safe_blocker}), ensure_ascii=False),
        }
    )
    return {"status": "ok", "thread": payload}


def repair_codex_session_links(project_key: str = "", *, limit: int = 120) -> dict[str, Any]:
    target = normalize_project_key(project_key)
    changed_rows: list[dict[str, Any]] = []
    scanned = 0
    for path in CODEX_SESSION_ROOT.glob("*.json"):
        if scanned >= max(1, min(int(limit or 120), 400)):
            break
        scanned += 1
        try:
            session = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(session, dict):
                continue
            repaired, changed = _repair_codex_session_record(session)
            if target and normalize_project_key(repaired.get("project_key")) != target:
                continue
            if changed:
                path.write_text(json.dumps(repaired, indent=2, ensure_ascii=False), encoding="utf-8")
                _sync_project_thread_from_session(repaired, reason="session_repair")
                changed_rows.append(
                    {
                        "session_id": str(repaired.get("session_id") or "").strip(),
                        "project_key": normalize_project_key(repaired.get("project_key")),
                        "project_key_status": str(repaired.get("project_key_status") or "").strip(),
                    }
                )
        except Exception:
            continue
    return {"status": "ok", "project_key": target or None, "scanned": scanned, "changed": len(changed_rows), "rows": changed_rows[:80]}


def run_project_codex_thread_sweep(
    *,
    project_key: str = "",
    limit: int = 80,
    bootstrap_missing: bool = True,
    repair_sessions: bool = True,
    reason: str = "zeus_sweep",
) -> dict[str, Any]:
    target = normalize_project_key(project_key)
    registry = load_workspace_registry_profile()
    rows: list[dict[str, Any]] = []
    if repair_sessions:
        session_repair = repair_codex_session_links(target or "", limit=max(80, limit * 2))
    else:
        session_repair = {"status": "skipped", "changed": 0, "rows": []}
    for raw in registry.get("projects", []) if isinstance(registry.get("projects"), list) else []:
        if not isinstance(raw, dict):
            continue
        key = normalize_project_key(raw.get("project_key"))
        if not key or (target and key != target):
            continue
        thread_state = bootstrap_or_repair_project_codex_thread(key, reason=reason, force=False) if bootstrap_missing else {"thread": load_project_codex_thread(key)}
        thread_doc = thread_state.get("thread") if isinstance(thread_state.get("thread"), dict) else {}
        rows.append(
            {
                "project_key": key,
                "display_name": str(raw.get("display_name") or pretty_label(key)).strip() or pretty_label(key),
                "thread_status": str(thread_doc.get("thread_status") or "missing").strip(),
                "review_state_summary": str(thread_doc.get("review_state_summary") or thread_doc.get("latest_review_state") or "unknown").strip(),
                "pending_suggestions": len(thread_doc.get("pending_suggestions", []) if isinstance(thread_doc.get("pending_suggestions"), list) else []),
                "active_sessions": len(thread_doc.get("active_codex_session_ids", []) if isinstance(thread_doc.get("active_codex_session_ids"), list) else []),
                "review_queue": len(thread_doc.get("review_queue", []) if isinstance(thread_doc.get("review_queue"), list) else []),
                "preferred_escalation_model": str(thread_doc.get("preferred_escalation_model") or raw.get("preferred_escalation_model") or "gpt-5.4-mini").strip(),
            }
        )
    rows.sort(key=lambda item: (str(item.get("thread_status") or "") == "ready", -(int(item.get("pending_suggestions") or 0)), -(int(item.get("review_queue") or 0))))
    limited = rows[: max(1, min(int(limit or 80), 200))]
    summary = {
        "count": len(limited),
        "ready": len([row for row in limited if row.get("thread_status") == "ready"]),
        "attention_needed": len([row for row in limited if row.get("thread_status") in {"attention_needed", "blocked"}]),
        "missing": len([row for row in limited if row.get("thread_status") == "missing"]),
        "pending_suggestions": sum(int(row.get("pending_suggestions") or 0) for row in limited),
        "review_queue": sum(int(row.get("review_queue") or 0) for row in limited),
        "repaired_sessions": int(session_repair.get("changed") or 0),
    }
    _append_runtime_diagnostic_receipt(
        {
            "event": "project_codex_thread_sweep",
            "stage": "sweep",
            "severity": "warn" if summary["attention_needed"] or summary["missing"] else "info",
            "scene": "assistant-core",
            "route": "codex/threads/sweep",
            "connection": {"project": target or "__all__", "reason": reason},
            "summary": "Project Codex thread sweep completed",
            "details": json.dumps(_json_ready({"summary": summary, "session_repair": session_repair}), ensure_ascii=False),
        }
    )
    return {"status": "ok", "project_key": target or None, "reason": reason, "summary": summary, "rows": limited, "session_repair": session_repair}

def _seed_project_workspace_from_template(project_root: Path, project_key: str, title: str, goal: str, template: dict[str, Any]) -> dict[str, Any]:
    template_key = str(template.get("key") or "").strip()
    if not template_key:
        return {"status": "skipped", "reason": "no starter template"}
    seeded = _seed_template_tree(
        project_root,
        template,
        "workspace_directories",
        "workspace_files",
        {
            "project_key": project_key,
            "title": title or pretty_label(project_key),
            "goal": goal or f"Bootstrap {title or pretty_label(project_key)} through Mount Olympus.",
            "starter_display_name": str(template.get("display_name") or pretty_label(template_key)).strip() or pretty_label(template_key),
        },
    )
    return {"status": "ok", "starter_template": template_key, **seeded}

def seed_project_runtime_workspace(project_key: str, title: str, goal: str, starter_template: Optional[dict[str, Any]] = None) -> dict[str, Any]:
    template = starter_template if isinstance(starter_template, dict) else {}
    template_key = str(template.get("key") or "").strip()
    if template_key:
        key = normalize_project_key(project_key)
        if not key:
            raise HTTPException(status_code=400, detail="Invalid project key")
        root = safe_under(PROJECTS_ROOT, key)
        root.mkdir(parents=True, exist_ok=True)
        seeded = _seed_template_tree(
            root,
            template,
            "runtime_directories",
            "runtime_files",
            {
                "project_key": key,
                "title": title or pretty_label(key),
                "goal": goal or f"Bootstrap {title or pretty_label(key)} through Mount Olympus.",
                "starter_display_name": str(template.get("display_name") or pretty_label(template_key)).strip() or pretty_label(template_key),
            },
        )
        return {"status": "ok", "starter_template": template_key, "root": str(root), **seeded}
    return seed_game_project_workspace(project_key, title, goal)

def _bootstrap_workspace_project_artifacts(
    project_key: str,
    title: str,
    goal: str,
    starter_template_key: str = "",
) -> dict[str, Any]:
    key = normalize_project_key(project_key)
    if not key:
        raise HTTPException(status_code=400, detail="Invalid project key")
    registry_row = workspace_registry_project(key)
    starter_template = project_starter_template_profile(starter_template_key)
    starter_template_key = str(starter_template.get("key") or "").strip()
    starter_display_name = str(starter_template.get("display_name") or pretty_label(starter_template_key)).strip() if starter_template_key else ""
    root_text = str(registry_row.get("root_path") or "").strip()
    project_root = _resolve_workspace_project_root(root_text, registry_row) if root_text else (WORKSPACE_ATLAS_ROOT / _safe_project_dir_name(title, key))
    project_root.mkdir(parents=True, exist_ok=True)
    (project_root / "Feedback").mkdir(parents=True, exist_ok=True)

    display_name = (title or pretty_label(key)).strip() or pretty_label(key)
    status_summary = (goal or f"{display_name} bootstrap project created through Olympus.").strip()
    connection_ref_key = f"{key}_project_bootstrap"
    deploy_target = registry_row.get("deploy_target", {}) if isinstance(registry_row.get("deploy_target"), dict) else {}
    template_deploy_target = starter_template.get("deploy_target", {}) if isinstance(starter_template.get("deploy_target"), dict) else {}
    if not deploy_target:
        deploy_target = template_deploy_target or {
            "host_ref": "server_brain",
            "kind": "manual_pending",
            "workdir": str(project_root),
            "verify_after_apply": True,
        }
    purpose_template = str(starter_template.get("purpose_template") or "").strip()
    purpose_text = _render_project_template_text(
        purpose_template,
        {"project_key": key, "title": display_name, "goal": status_summary},
    ) if purpose_template else ""
    mutable_paths = registry_row.get("mutable_paths") if isinstance(registry_row.get("mutable_paths"), list) else []
    if not mutable_paths:
        mutable_paths = _string_list(starter_template.get("mutable_paths")) or [".", "Feedback", "nameplate.txt", "details.txt"]
    excluded_paths = registry_row.get("excluded_paths") if isinstance(registry_row.get("excluded_paths"), list) else []
    if not excluded_paths:
        excluded_paths = _string_list(starter_template.get("excluded_paths"))
    review_commands = registry_row.get("review_commands") if isinstance(registry_row.get("review_commands"), list) else []
    if not review_commands:
        review_commands = _string_list(starter_template.get("review_commands"))
    test_commands = registry_row.get("test_commands") if isinstance(registry_row.get("test_commands"), list) else []
    if not test_commands:
        test_commands = _string_list(starter_template.get("test_commands"))
    local_test_commands = registry_row.get("local_test_commands") if isinstance(registry_row.get("local_test_commands"), list) else []
    if not local_test_commands:
        local_test_commands = _string_list(starter_template.get("local_test_commands")) or list(test_commands)
    remote_test_commands = registry_row.get("remote_test_commands") if isinstance(registry_row.get("remote_test_commands"), list) else []
    if not remote_test_commands:
        remote_test_commands = _string_list(starter_template.get("remote_test_commands"))
    health_urls = registry_row.get("health_urls") if isinstance(registry_row.get("health_urls"), list) else []
    if not health_urls:
        health_urls = _string_list(starter_template.get("health_urls"))
    domains = registry_row.get("domains") if isinstance(registry_row.get("domains"), list) else []
    if not domains:
        domains = _string_list(starter_template.get("domains"))
    connections_ref = registry_row.get("connections_ref") if isinstance(registry_row.get("connections_ref"), list) else []
    if not connections_ref:
        connections_ref = _string_list(starter_template.get("connections_ref")) or [connection_ref_key]
    sync_targets = registry_row.get("sync_targets") if isinstance(registry_row.get("sync_targets"), list) else []
    if not sync_targets:
        sync_targets = _string_list(starter_template.get("sync_targets"))
    registry_payload = {
        "project_key": key,
        "display_name": display_name,
        "purpose": (purpose_text or goal or f"{display_name} project in the Mount Olympus workspace.").strip(),
        "audience": str(registry_row.get("audience") or starter_template.get("audience") or "operators and assigned project members").strip(),
        "status_summary": str(registry_row.get("status_summary") or status_summary).strip(),
        "role_owner": str(registry_row.get("role_owner") or starter_template.get("owner_lane") or "zeus").strip() or "zeus",
        "priority": int(registry_row.get("priority") or starter_template.get("priority") or 25),
        "stack": str(registry_row.get("stack") or starter_template.get("stack") or "workspace_project").strip() or "workspace_project",
        "runtime_shape": str(registry_row.get("runtime_shape") or starter_template.get("runtime_shape") or "bootstrap_workspace").strip() or "bootstrap_workspace",
        "root_path": str(project_root),
        "default_workdir": str(registry_row.get("default_workdir") or starter_template.get("default_workdir") or ".").strip() or ".",
        "domains": domains,
        "mutable_paths": mutable_paths,
        "excluded_paths": excluded_paths,
        "review_commands": review_commands,
        "test_commands": test_commands,
        "local_test_commands": local_test_commands,
        "remote_test_commands": remote_test_commands,
        "health_urls": health_urls,
        "connections_ref": connections_ref,
        "deploy_target": deploy_target,
        "atlas_paths": {
            "project_atlas": str(project_root / "PROJECT_ATLAS.md"),
            "file_index": str(project_root / "FILE_INDEX.md"),
        },
        "sync_targets": sync_targets,
    }
    saved_registry = _upsert_workspace_registry_project(registry_payload)

    profile_path = OLYMPUS_PROFILE_ROOT / "projects" / f"{key}.json"
    current_profile = _read_json(profile_path)
    profile_payload = {
        **current_profile,
        "kind": "project",
        "key": key,
        "aliases": current_profile.get("aliases", [key]),
        "display_name": str(current_profile.get("display_name") or display_name).strip() or display_name,
        "public_name": str(current_profile.get("public_name") or display_name).strip() or display_name,
        "root_path": str(project_root),
        "owner": str(current_profile.get("owner") or saved_registry.get("role_owner") or "zeus").strip() or "zeus",
        "category": str(current_profile.get("category") or starter_template.get("category") or "workspace-project").strip() or "workspace-project",
        "summary": str(current_profile.get("summary") or status_summary).strip() or status_summary,
        "visibility": str(current_profile.get("visibility") or starter_template.get("visibility") or "public_product").strip() or "public_product",
        "capability_bundles": current_profile.get("capability_bundles", starter_template.get("capability_bundles", ["project_task"])),
        "deploy_policy": current_profile.get(
            "deploy_policy",
            starter_template.get("deploy_policy", {"allowed": True, "mode": "manual_guarded", "restart_services": []}),
        ),
        "arrangement": current_profile.get(
            "arrangement",
            starter_template.get(
                "arrangement",
                {
                    "primary_root": ".",
                    "notes": "Bootstrap project. Fill in source folders, services, and runtime surfaces as implementation becomes concrete.",
                },
            ),
        ),
        "verification_profile": current_profile.get(
            "verification_profile",
            starter_template.get(
                "verification_profile",
                {
                    "local_test_commands": saved_registry.get("local_test_commands", []),
                    "remote_test_commands": saved_registry.get("remote_test_commands", []),
                    "health_urls": saved_registry.get("health_urls", []),
                    "smoke_prompts": [],
                    "rollback_notes": ["Restore the previous tested workspace snapshot before reapplying changes."],
                },
            ),
        ),
        "connections_refs": current_profile.get("connections_refs", saved_registry.get("connections_ref", [connection_ref_key])),
        "live_change_policy": current_profile.get(
            "live_change_policy",
            starter_template.get(
                "live_change_policy",
                {
                    "mode": "guarded_live",
                    "requires_project_scope": True,
                    "requires_local_tests": True,
                    "requires_remote_verification": True,
                    "asks_when_unknown": True,
                    "logs_rollback_breadcrumbs": True,
                },
            ),
        ),
        "required_context_files": current_profile.get(
            "required_context_files",
            starter_template.get("required_context_files", ["README.md", "portal.json", "nameplate.txt", "details.txt"]),
        ),
        "related_assets": current_profile.get("related_assets", starter_template.get("related_assets", [])),
        "discord_branding": current_profile.get("discord_branding", starter_template.get("discord_branding", {})),
    }
    _write_json(profile_path, profile_payload)

    _upsert_workspace_connection_ref(
        {
            "key": connection_ref_key,
            "kind": "project_scope",
            "owner": key,
            "host_ref": str(deploy_target.get("host_ref") or "server_brain").strip() or "server_brain",
            "summary": f"Bootstrap connection ref for {display_name}. Expand with public URLs, service names, and env keys as the project matures.",
            "workspace_root": str(project_root),
            "atlas_hint": str(project_root / "PROJECT_ATLAS.md"),
        }
    )

    _write_if_missing(
        project_root / "nameplate.txt",
        "\n".join(
            [
                f"Project: {display_name}",
                f"Key: {key}",
                "Status: bootstrap",
                f"Starter Template: {starter_display_name}" if starter_display_name else "",
                f"Purpose: {saved_registry.get('purpose')}",
                f"Deploy Target: {deploy_target.get('kind') or 'manual_pending'}",
                "",
            ]
        ),
    )
    details_line = f"{datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')} UTC | bootstrap | {status_summary}"
    details_path = project_root / "details.txt"
    if details_path.exists():
        existing_text = details_path.read_text(encoding="utf-8", errors="ignore").strip()
        if details_line not in existing_text:
            details_path.write_text((existing_text + "\n" + details_line + "\n").lstrip(), encoding="utf-8")
    else:
        details_path.write_text(details_line + "\n", encoding="utf-8")
    _write_if_missing(
        project_root / "portal.json",
        json.dumps(
            {
                "project_key": key,
                "display_name": display_name,
                "summary": saved_registry.get("purpose"),
                "status": "bootstrap",
                "owner_lane": saved_registry.get("role_owner"),
                "starter_template": starter_template_key or None,
            },
            indent=2,
        )
        + "\n",
    )
    workspace_template_seed = _seed_project_workspace_from_template(project_root, key, display_name, status_summary, starter_template)
    codex_thread_state = bootstrap_or_repair_project_codex_thread(key, reason="workspace_bootstrap", force=False)

    atlas_snapshot = {}
    try:
        atlas_snapshot = rebuild_workspace_atlas(key)
    except Exception:
        atlas_snapshot = load_workspace_atlas_snapshot()
    return {
        "registry": saved_registry,
        "profile_path": str(profile_path),
        "project_root": str(project_root),
        "atlas": atlas_snapshot,
        "starter_template": {
            "key": starter_template_key,
            "display_name": starter_display_name,
        } if starter_template_key else {},
        "workspace_seed": workspace_template_seed,
        "codex_thread": codex_thread_state,
    }

def _project_record_by_key(project_key: str | None) -> dict[str, Any]:
    wanted = normalize_project_key(project_key)
    if not wanted:
        return {}
    for row in _list_project_records(limit=320):
        if normalize_project_key(row.get("project_key")) == wanted:
            return row
    return {}

def _tail_lines(text: str, limit: int = 6) -> list[str]:
    return [line.strip() for line in str(text or "").splitlines() if line.strip()][-max(1, limit):]

def _optional_project_preview(project_key: str, filename: str, max_chars: int = 1200) -> str:
    try:
        target = safe_under(PROJECTS_ROOT, f"{project_key}/{filename}")
    except HTTPException:
        return ""
    if not target.exists() or not target.is_file():
        return ""
    return _read_text_preview(target, max_chars)

def _recent_project_context(project_key: str | None) -> dict[str, Any]:
    key = normalize_project_key(project_key)
    record = _project_record_by_key(key) if key else {}
    registry_row = workspace_registry_project(key) if key else {}
    atlas_row = workspace_atlas_project(key) if key else {}
    profile_row = olympus_project_profile_for_workspace_project(key) if key else {}
    thread_row = load_project_codex_thread(key, bootstrap_missing=False) if key else {}
    tasks = list_project_tasks(project_key=key, status="", limit=12) if key else []
    sessions = list_codex_sessions(limit=12, project_key=key or "").get("rows", []) if key else []
    brief_preview = _optional_project_preview(key, "PROJECT_BRIEF.md", 1600) if key else ""
    nameplate_preview = _optional_project_preview(key, "nameplate.txt", 800) if key else ""
    details_preview = _optional_project_preview(key, "details.txt", 1400) if key else ""
    connection_refs = []
    for ref_key in atlas_row.get("connections_ref_keys", []) if isinstance(atlas_row.get("connections_ref_keys"), list) else []:
        ref = workspace_connection_ref(ref_key)
        if ref:
            connection_refs.append(ref)
    return {
        "project_key": key,
        "record": record,
        "registry": registry_row,
        "atlas": atlas_row,
        "profile": profile_row,
        "project_thread": thread_row,
        "connection_refs": connection_refs,
        "tasks": tasks,
        "sessions": sessions,
        "brief_preview": brief_preview,
        "nameplate_preview": nameplate_preview,
        "details_preview": details_preview,
    }

def _guess_codex_scope(prompt: str) -> str:
    text = str(prompt or "").strip().lower()
    if any(term in text for term in ["review", "inspect", "analyze", "look at", "audit"]):
        return "inspect"
    if any(term in text for term in ["repair", "fix", "bug", "error", "regression", "broken"]):
        return "repair"
    return "implement"

def _actionable_project_key(prompt: str, meta: Optional[dict[str, Any]] = None) -> str | None:
    payload = meta if isinstance(meta, dict) else {}
    for key_name in ("project_key", "project", "site_name", "site_key"):
        resolved = normalize_project_key(payload.get(key_name))
        if resolved:
            return resolved
    return normalize_project_key(prompt)

async def dispatch_research_job(
    topic: str,
    *,
    max_sources: int = 6,
    max_iterations: int = 2,
    provider: str = "auto",
    reasoning_provider: str = "auto",
) -> dict[str, Any]:
    enforce_worker_pause("Research worker")
    enforce_runtime_rate_limit("research")
    runtime_policy = load_runtime_policy()
    openai_models = runtime_policy.get("openai_models") if isinstance(runtime_policy.get("openai_models"), dict) else {}
    async with httpx.AsyncClient(timeout=30) as client:
        response = await client.post(
            f"{RESEARCH_WORKER_URL}/run",
            json={
                "topic": topic,
                "max_sources": max(2, min(int(max_sources or 6), 12)),
                "max_iterations": max(1, min(int(max_iterations or 2), 4)),
                "provider": provider,
                "reasoning_provider": reasoning_provider,
                "model_fast": str(openai_models.get("research_fast") or openai_models.get("fast") or OPENAI_CHAT_MODEL_FAST).strip(),
                "model_reasoning": str(openai_models.get("research_reasoning") or openai_models.get("reasoning") or OPENAI_CHAT_MODEL_REASONING).strip(),
            },
        )
    response.raise_for_status()
    payload = response.json()
    return payload if isinstance(payload, dict) else {"status": "ok", "raw": payload}

async def compose_actionable_reply(
    prompt: str,
    trace_ctx: dict[str, Any],
    *,
    allow_write: bool = True,
) -> tuple[str, list[dict[str, Any]], dict[str, Any]]:
    meta = trace_ctx.get("meta") if isinstance(trace_ctx, dict) else {}
    project_key = _actionable_project_key(prompt, meta)
    context = _recent_project_context(project_key)
    record = context.get("record") if isinstance(context.get("record"), dict) else {}
    registry_row = context.get("registry") if isinstance(context.get("registry"), dict) else {}
    atlas_row = context.get("atlas") if isinstance(context.get("atlas"), dict) else {}
    profile_row = context.get("profile") if isinstance(context.get("profile"), dict) else {}
    thread_row = context.get("project_thread") if isinstance(context.get("project_thread"), dict) else {}
    connection_refs = context.get("connection_refs") if isinstance(context.get("connection_refs"), list) else []
    project_title = str(record.get("title") or pretty_label(project_key or "general ops")).strip() or pretty_label(project_key or "general ops")
    tasks = context.get("tasks") if isinstance(context.get("tasks"), list) else []
    sessions = context.get("sessions") if isinstance(context.get("sessions"), list) else []
    active_session_id = str((sessions[0] or {}).get("session_id") if sessions else "").strip()
    prompt_signature = " ".join(str(prompt or "").strip().lower().split())
    reusable_statuses = {"queued", "in_progress", "running", "review_required", "revise", "verified_local", "verified_alpha_runtime", "promoted"}
    task_record = next(
        (
            row
            for row in tasks
            if isinstance(row, dict)
            and " ".join(str(row.get("goal") or "").strip().lower().split()) == prompt_signature
            and str(row.get("status") or "").strip().lower() in reusable_statuses
        ),
        None,
    )
    queued_suggestion: dict[str, Any] | None = None
    if project_key:
        try:
            thread_state = bootstrap_or_repair_project_codex_thread(project_key, reason="actionable_request")
            thread_row = thread_state.get("thread") if isinstance(thread_state.get("thread"), dict) else thread_row
            existing_suggestions = thread_row.get("pending_suggestions") if isinstance(thread_row.get("pending_suggestions"), list) else []
            prompt_title = str(prompt or "").strip()[:180]
            queued_suggestion = next(
                (
                    row
                    for row in existing_suggestions
                    if isinstance(row, dict)
                    and str(row.get("title") or "").strip() == prompt_title
                    and str(row.get("status") or "").strip().lower() in {"queued", "review", "pending_review"}
                ),
                None,
            )
            if not queued_suggestion:
                suggestion_state = submit_project_codex_suggestion(
                    project_key,
                    title=prompt_title,
                    body=prompt,
                    requested_by=str(trace_ctx.get("speaker") or "operator").strip() or "operator",
                    source="compose_actionable_reply",
                    suggestion_kind="action_request",
                    meta={
                        "surface": trace_ctx.get("meta", {}).get("surface") or "chat",
                        "room_key": trace_ctx.get("room_key"),
                        "session_id": trace_ctx.get("session_id"),
                    },
                )
                queued_suggestion = suggestion_state.get("suggestion") if isinstance(suggestion_state.get("suggestion"), dict) else None
                thread_row = suggestion_state.get("thread") if isinstance(suggestion_state.get("thread"), dict) else thread_row
        except Exception:
            queued_suggestion = None
    if project_key and not active_session_id:
        session = create_codex_session_record(
            project_key=project_key,
            title=f"{project_title} implementation lane",
            goal=prompt,
            workdir="",
            allow_write=allow_write,
        )
        active_session_id = str(session.get("session_id") or "").strip()
        sessions = [codex_session_preview(session)] + sessions
    if project_key and not task_record:
        task_record = create_project_task(
            goal=prompt,
            project_key=project_key,
            entails="Chat-directed actionable request routed through Mount Olympus conversation.",
            source="chat_orchestrator",
            requested_by=trace_ctx.get("speaker") or "operator",
            status="queued",
            meta={"surface": trace_ctx.get("meta", {}).get("surface") or "chat", "room_key": trace_ctx.get("room_key"), "session_id": trace_ctx.get("session_id")},
        )
        tasks = [task_record] + tasks
    codex_result: dict[str, Any] | None = None
    codex_error = ""
    if project_key and control_granted():
        try:
            codex_result = await run_codex_bridge_session(
                goal=prompt,
                project_key=project_key,
                task_uid=str((task_record or {}).get("task_uid") or ""),
                mode="project",
                scope=_guess_codex_scope(prompt),
                workdir="",
                allow_write=allow_write,
                update_task_status_flag=True,
                source="chat_orchestrator",
                session_id=active_session_id or None,
            )
            if active_session_id:
                try:
                    session_payload = load_codex_session(active_session_id)
                    _apply_codex_result_to_session(session_payload, prompt, codex_result)
                except Exception:
                    pass
        except Exception as e:
            codex_error = str(e)
    context_lines = [
        f"Project key: {project_key or 'not resolved'}",
        f"Project title: {project_title}",
        record.get("goal") and f"Project goal: {record.get('goal')}",
        registry_row.get("purpose") and f"Workspace purpose: {registry_row.get('purpose')}",
        registry_row.get("audience") and f"Audience: {registry_row.get('audience')}",
        atlas_row.get("status_summary") and f"Status summary: {atlas_row.get('status_summary')}",
        atlas_row.get("stack") and f"Stack: {atlas_row.get('stack')} ({atlas_row.get('runtime_shape') or 'runtime shape unknown'})",
        atlas_row.get("deploy_target") and f"Deploy target: {json.dumps(atlas_row.get('deploy_target'), ensure_ascii=False)}",
        atlas_row.get("verification_profile", {}).get("local_test_commands") and "Local verification:\n- " + "\n- ".join([str(item)[:220] for item in atlas_row.get("verification_profile", {}).get("local_test_commands", [])[:4]]),
        atlas_row.get("verification_profile", {}).get("remote_test_commands") and "Remote verification:\n- " + "\n- ".join([str(item)[:220] for item in atlas_row.get("verification_profile", {}).get("remote_test_commands", [])[:4]]),
        atlas_row.get("verification_profile", {}).get("health_urls") and "Health URLs:\n- " + "\n- ".join([str(item)[:220] for item in atlas_row.get("verification_profile", {}).get("health_urls", [])[:4]]),
        connection_refs and "Connection refs:\n- " + "\n- ".join([f"{row.get('key')}: {row.get('public_url') or row.get('summary') or row.get('service_name') or row.get('runtime_path') or ''}"[:220] for row in connection_refs[:4] if isinstance(row, dict)]),
        profile_row.get("live_change_policy") and f"Live change policy: {json.dumps(profile_row.get('live_change_policy'), ensure_ascii=False)}",
        context.get("brief_preview") and f"Project brief preview:\n{context.get('brief_preview')[:1200]}",
        context.get("nameplate_preview") and f"Nameplate:\n{context.get('nameplate_preview')[:400]}",
        context.get("details_preview") and "Recent details:\n- " + "\n- ".join(_tail_lines(context.get("details_preview"), 5)),
        tasks and "Recent tasks:\n- " + "\n- ".join([str(row.get("goal") or row.get("entails") or row.get("task_uid") or "task")[:180] for row in tasks[:4]]),
        sessions and "Recent Codex sessions:\n- " + "\n- ".join([f"{row.get('session_id')}: {str(row.get('last_summary') or row.get('goal') or '').strip()[:140]}" for row in sessions[:3]]),
        thread_row and f"Project Codex thread status: {thread_row.get('thread_status') or 'unknown'} / review={thread_row.get('review_state_summary') or thread_row.get('latest_review_state') or 'unknown'}",
        queued_suggestion and f"Queued into project Codex suggestions: {queued_suggestion.get('suggestion_id') or queued_suggestion.get('title')}",
        active_session_id and f"Active session routed: {active_session_id}",
        task_record and f"Active task routed: {task_record.get('task_uid')}",
        codex_result and f"Codex outcome: {codex_result.get('outcome') or codex_result.get('status') or 'unknown'}",
        codex_result and codex_result.get("summary") and f"Codex summary: {str(codex_result.get('summary') or '')[:500]}",
        codex_error and f"Codex blocker: {codex_error[:500]}",
    ]
    reply_lines: list[str] = [ACTIONABLE_ACK_TEXT]
    if project_key:
        reply_lines.append(f"I checked `{project_title}` before routing the work.")
    else:
        reply_lines.append("I could not resolve the target project from this request alone.")
    if task_record and str(task_record.get("task_uid") or "").strip():
        reply_lines.append(f"Task queued: `{str(task_record.get('task_uid') or '').strip()}`.")
    if active_session_id:
        reply_lines.append(f"Codex thread: `{active_session_id}`.")
    if queued_suggestion and str(queued_suggestion.get("suggestion_id") or "").strip():
        reply_lines.append(f"Project thread suggestion: `{str(queued_suggestion.get('suggestion_id') or '').strip()}`.")
    if codex_result:
        outcome = str(codex_result.get("outcome") or codex_result.get("status") or "queued").strip().lower()
        summary = str(codex_result.get("summary") or "").strip()
        if outcome in {"completed", "success", "succeeded", "ok", "verified"}:
            reply_lines.append("Status: Codex completed the pass.")
        elif outcome in {"queued", "running", "in_progress"}:
            reply_lines.append("Status: Codex accepted the pass and is running it.")
        elif outcome == "blocked":
            reply_lines.append("Blocked: the execution lane accepted the request but hit a guard or queue blocker.")
        else:
            reply_lines.append(f"Status: {pretty_label(outcome or 'queued')}.")
        if summary:
            reply_lines.append(_truncate_text(summary, 320))
    elif codex_error:
        reply_lines.append(f"Blocked: {_truncate_text(codex_error, 320)}")
    elif project_key and not control_granted():
        reply_lines.append("Blocked: live execution control is not granted right now, so I only queued the project lane.")
    elif not project_key:
        reply_lines.append("Reply with the project name, or run this from that project lane, so I can route it cleanly.")
    else:
        reply_lines.append("Status: the request is routed and waiting on execution details.")
    draft = " ".join([line.strip() for line in reply_lines if str(line).strip()]).strip()
    trace: list[dict[str, Any]] = []
    if project_key:
        trace.append({"tool": "project.context", "status": "ok", "project_key": project_key, "task_uid": (task_record or {}).get("task_uid"), "session_id": active_session_id})
    if queued_suggestion:
        trace.append({"tool": "codex.thread.suggestion", "status": "ok", "project_key": project_key, "suggestion_id": queued_suggestion.get("suggestion_id"), "review_state": queued_suggestion.get("review_state")})
    if codex_result:
        trace.append({"tool": "codex.bridge.run", "status": codex_result.get("status") or "ok", "project_key": project_key, "session_id": active_session_id, "run_id": codex_result.get("run_id"), "outcome": codex_result.get("outcome")})
    elif codex_error:
        trace.append({"tool": "codex.bridge.run", "status": "error", "project_key": project_key, "session_id": active_session_id, "detail": codex_error[:320]})
    payload = {
        "project_key": project_key,
        "project_title": project_title,
        "task": task_record,
        "session_id": active_session_id,
        "project_thread": thread_row,
        "queued_suggestion": queued_suggestion,
        "codex_result": codex_result,
        "codex_error": codex_error,
        "context": context,
    }
    return draft, trace, payload

async def compose_live_lookup_reply(prompt: str, *, speaker: str = "", deep: bool = False) -> tuple[str, list[dict[str, Any]], dict[str, Any] | None]:
    lookup_prompt = (
        "Research this request using live tools when freshness, current events, releases, or verification matter.\n"
        "- Prefer browser.navigate/browser.chain for current factual checks.\n"
        "- Use research.run when a deeper sourced report would help.\n"
        "- Give a concise answer and include direct source URLs when tools were used.\n\n"
        f"Speaker: {speaker or 'operator'}\nRequest: {prompt}"
    )
    final_text, trace = await maybe_execute_tools(lookup_prompt, max_rounds=4 if deep else 3)
    final_text = await apply_accuracy_gate(prompt, final_text, trace)
    research_job = None
    if deep and not any(str(row.get("tool") or "").strip() == "research.run" for row in trace):
        try:
            research_job = await dispatch_research_job(prompt, max_sources=6, max_iterations=2)
            trace.append({"tool": "research.run", "status": research_job.get("status") or "started", "job_id": research_job.get("job_id"), "topic": prompt[:180]})
            if research_job.get("job_id"):
                final_text = final_text.strip() + f"\n\nBackground research job: {research_job.get('job_id')}."
        except Exception as e:
            trace.append({"tool": "research.run", "status": "error", "detail": str(e)[:320]})
    return final_text, trace, research_job

def is_quick_chat_prompt(prompt: str) -> bool:
    p = (prompt or "").strip().lower()
    if not p:
        return False
    if looks_like_capability_query(p):
        return False
    if is_actionable_prompt(p):
        return False
    toolish = [
        "build", "code", "debug", "fix", "patch", "write file", "create scaffold",
        "service", "docker", "mysql", "qdrant", "redis", "browser", "site",
        "account", "task", "agent", "memory", "git", "install", "script",
        "workflow", "project", "discord", "plan", "scan", "diagnostic",
    ]
    return not any(t in p for t in toolish) and len(p) < 280

def looks_like_site_change_prompt(prompt: str) -> bool:
    text = (prompt or "").strip().lower()
    if not text:
        return False
    site_terms = ["default webpage", "default page", "placeholder", "website", "webpage", "site"]
    action_terms = ["change", "replace", "set", "make", "publish", "switch"]
    return any(term in text for term in site_terms) and any(term in text for term in action_terms)

def _site_placeholder_label(prompt: str) -> str:
    raw = (prompt or "").strip()
    if not raw:
        return ""
    match = re.search(r"placeholder(?:\s+(?:for|called|named))?\s+([a-z0-9][a-z0-9 _-]{0,40})", raw, re.I)
    if not match:
        return ""
    label = re.sub(r"\s+", " ", match.group(1)).strip(" .?!,")
    if not label:
        return ""
    if label.isalpha() and len(label) <= 8:
        return label.upper()
    return label

def site_change_prompt_response(prompt: str) -> str:
    label = _site_placeholder_label(prompt) or "placeholder"
    return (
        f"I can handle that here. Do you want me to publish a simple {label} placeholder page "
        "and make it the default now, or should I use custom wording, colors, or branding instead?"
    )

async def ollama_chat(messages: list[dict[str, Any]], model: str, stream: bool = False, format_schema: Optional[dict[str, Any]] = None, role_hint: str = ""):
    requested_model = str(model or "").strip() or MODEL_FAST
    resolved_model, resolution = await resolve_ollama_model(requested_model, role_hint=role_hint)
    if bool(resolution.get("fallback_applied")):
        activity_log(
            "assistant-core",
            "ollama_model_fallback",
            "warn",
            "Ollama model fallback applied",
            f"{requested_model} -> {resolved_model}",
            resolution,
        )
        cognition_log(
            "assistant-core",
            "core",
            "model_fallback",
            "Ollama model fallback applied",
            f"{requested_model} -> {resolved_model}",
            resolution,
        )
    payload: dict[str, Any] = {"model": resolved_model, "messages": messages, "stream": stream}
    if format_schema is not None:
        payload["format"] = format_schema
    async with httpx.AsyncClient(timeout=900) as client:
        r = await client.post(f"{OLLAMA_HOST}/api/chat", json=payload)
        if r.status_code == 404 and requested_model == resolved_model:
            retry_model, retry_resolution = await resolve_ollama_model(requested_model, role_hint=role_hint, force_refresh=True)
            if retry_model != resolved_model:
                activity_log(
                    "assistant-core",
                    "ollama_model_fallback",
                    "warn",
                    "Ollama model fallback applied after missing model",
                    f"{requested_model} -> {retry_model}",
                    retry_resolution,
                )
                cognition_log(
                    "assistant-core",
                    "core",
                    "model_fallback",
                    "Ollama model fallback applied after missing model",
                    f"{requested_model} -> {retry_model}",
                    retry_resolution,
                )
                payload["model"] = retry_model
                r = await client.post(f"{OLLAMA_HOST}/api/chat", json=payload)
        r.raise_for_status()
        return r

async def openai_chat_text(messages: list[dict[str, Any]], model: str) -> str:
    if not OPENAI_ENABLE or not OPENAI_API_KEY:
        raise RuntimeError("OpenAI disabled")
    headers = {"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"}
    async with httpx.AsyncClient(timeout=900) as client:
        # Prefer Responses API (latest path), fallback to Chat Completions for compatibility.
        try:
            rr = await client.post(
                f"{OPENAI_BASE_URL}/responses",
                headers=headers,
                json={
                    "model": model,
                    "input": messages,
                    "reasoning": {"effort": "medium"},
                    "temperature": 0.4,
                },
            )
            rr.raise_for_status()
            payload = rr.json()
            output_text = (payload.get("output_text") or "").strip()
            if output_text:
                return output_text
            # Structured fallback parse if output_text is omitted.
            collected: list[str] = []
            for item in payload.get("output", []) or []:
                if not isinstance(item, dict):
                    continue
                for part in item.get("content", []) or []:
                    if isinstance(part, dict) and part.get("type") in {"output_text", "text"}:
                        text = str(part.get("text", "")).strip()
                        if text:
                            collected.append(text)
            if collected:
                return "\n".join(collected).strip()
        except Exception:
            pass
        r = await client.post(
            f"{OPENAI_BASE_URL}/chat/completions",
            headers=headers,
            json={"model": model, "messages": messages, "temperature": 0.4},
        )
        r.raise_for_status()
        data = r.json()
        return str(data["choices"][0]["message"]["content"]).strip()

async def openai_list_models() -> list[dict[str, Any]]:
    if not OPENAI_ENABLE or not OPENAI_API_KEY:
        return []
    async with httpx.AsyncClient(timeout=120) as client:
        r = await client.get(
            f"{OPENAI_BASE_URL}/models",
            headers={"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"},
        )
        r.raise_for_status()
        payload = r.json()
        rows = payload.get("data", []) if isinstance(payload, dict) else []
        out = []
        for item in rows:
            if not isinstance(item, dict):
                continue
            model_id = str(item.get("id", "")).strip()
            if model_id:
                out.append({"id": model_id, "owned_by": item.get("owned_by"), "created": item.get("created")})
        out.sort(key=lambda x: x.get("id", ""))
        return out

async def ollama_embed(text: str) -> list[float]:
    async with httpx.AsyncClient(timeout=120) as client:
        r = await client.post(f"{OLLAMA_HOST}/api/embed", json={"model": EMBED_MODEL, "input": text})
        r.raise_for_status()
        data = r.json()
        if "embeddings" in data and data["embeddings"]:
            return data["embeddings"][0]
        if "embedding" in data:
            return data["embedding"]
        raise RuntimeError("Invalid embed response")

async def save_memory(text: str):
    clean = (text or "").strip()
    if not clean:
        return
    persisted_text = _truncate_text(clean, MEMORY_ENTRY_MAX_CHARS)
    try:
        vector = await ollama_embed(_truncate_text(persisted_text, MEMORY_QDRANT_MAX_CHARS))
        qdrant.upsert(
            collection_name="luminax_memory",
            points=[models.PointStruct(id=str(uuid.uuid4()), vector=vector, payload={"text": persisted_text, "ts": int(time.time())})],
        )
    except Exception:
        pass
    out = MEMORY_ROOT / "chat" / f"{int(time.time())}_{uuid.uuid4().hex[:8]}.txt"
    out.write_text(persisted_text, encoding="utf-8")
    mysql_write("chat", "memory", persisted_text, {"file": str(out), "truncated": len(clean) > len(persisted_text)})
    _prune_files(MEMORY_ROOT / "chat", "*.txt", MEMORY_CHAT_KEEP_FILES)

async def lookup_memory(query: str, limit: int = 5) -> list[str]:
    try:
        vector = await ollama_embed(query)
        result = qdrant.search(collection_name="luminax_memory", query_vector=vector, limit=limit)
        return [hit.payload.get("text", "") for hit in result]
    except Exception:
        return []

def write_patch_proposal(target: str) -> Path:
    out = PATCH_ROOT / f"patch_{int(time.time())}_{uuid.uuid4().hex[:8]}.md"
    out.write_text(
        f"# Patch Proposal\n\n## Target\n{target}\n\n## Proposed Work\n- inspect current files and configs\n- generate safe patch\n- test candidate in sandbox\n- adopt only if candidate passes and improves or maintains result\n",
        encoding="utf-8",
    )
    mysql_summary("patch_proposal", f"Patch proposal created for {target}", {"path": str(out)})
    return out

async def browser_call(endpoint: str, payload: dict[str, Any]) -> dict[str, Any]:
    async with httpx.AsyncClient(timeout=900) as client:
        r = await client.post(f"{BROWSER_AGENT_URL.rstrip('/')}/{endpoint}", json=payload)
        r.raise_for_status()
        return r.json()

async def _broadcast_call(
    method: str,
    route: str,
    payload: dict[str, Any] | None = None,
    timeout: float = 45.0,
    expect_bytes: bool = False,
):
    url = f"{BROADCAST_CONDUCTOR_URL.rstrip('/')}/{route.lstrip('/')}"
    async with httpx.AsyncClient(timeout=timeout) as client:
        response = await client.request(method.upper(), url, json=payload)
    if response.status_code >= 400:
        detail = ""
        try:
            problem = response.json()
            detail = str(problem.get("detail") or problem.get("error") or problem)
        except Exception:
            detail = response.text.strip()
        raise HTTPException(status_code=response.status_code, detail=detail or "Broadcast conductor request failed")
    if expect_bytes:
        return {
            "content": response.content,
            "content_type": response.headers.get("content-type", "application/octet-stream"),
            "filename": response.headers.get("content-disposition", ""),
        }
    if not response.content:
        return {"status": "ok"}
    try:
        return response.json()
    except Exception:
        return {"status": "ok", "raw": response.text}


async def _account_worker_call(
    method: str,
    route: str,
    payload: dict[str, Any] | None = None,
    timeout: float = 45.0,
):
    url = f"{ACCOUNT_WORKER_URL.rstrip('/')}/{route.lstrip('/')}"
    headers: dict[str, str] = {}
    trusted_user = current_web_auth_user()
    if trusted_user:
        headers["X-Web-Auth-User"] = trusted_user
    async with httpx.AsyncClient(timeout=timeout) as client:
        response = await client.request(method.upper(), url, json=payload, headers=headers)
    if response.status_code >= 400:
        detail = ""
        try:
            problem = response.json()
            detail = str(problem.get("detail") or problem.get("error") or problem)
        except Exception:
            detail = response.text.strip()
        raise HTTPException(status_code=response.status_code, detail=detail or "Account worker request failed")
    if not response.content:
        return {"status": "ok"}
    try:
        return response.json()
    except Exception:
        return {"status": "ok", "raw": response.text}

