def copy_workspace_to_sandbox(sandbox_root: Path):
    if sandbox_root.exists():
        shutil.rmtree(sandbox_root)
    shutil.copytree(
        WORKSPACE_ROOT,
        sandbox_root,
        ignore=shutil.ignore_patterns("memory", "sandboxes", "__pycache__", "*.pyc", ".git"),
    )

ALLOWED_CLI_PREFIXES = [
    "docker compose ps",
    "docker compose logs",
    "docker compose restart",
    "docker ps",
    "docker logs",
    "git status",
    "git diff",
    "git log",
    "python3 -m py_compile",
    "codex --version",
    "codex --help",
    "ls",
    "cat",
]

def cli_command_allowed(command: str) -> bool:
    cleaned = " ".join((command or "").strip().split())
    if not cleaned:
        return False
    lowered = cleaned.lower()
    dangerous_tokens = [";", "&&", "||", "`", "$(", ">", "<", "|", "\n", "\r"]
    if any(tok in cleaned for tok in dangerous_tokens):
        return False
    return any(lowered.startswith(prefix) for prefix in ALLOWED_CLI_PREFIXES)

def collect_repair_diagnostics(service_name: str = "", max_log_lines: int = 120) -> dict[str, Any]:
    checks: dict[str, Any] = {}
    try:
        redis_client.ping()
        checks["redis"] = "ok"
    except Exception as e:
        checks["redis"] = f"error: {e}"
    try:
        qdrant.get_collections()
        checks["qdrant"] = "ok"
    except Exception as e:
        checks["qdrant"] = f"error: {e}"
    try:
        conn = db_conn()
        conn.close()
        checks["mysql"] = "ok"
    except Exception as e:
        checks["mysql"] = f"error: {e}"
    compose_ps = subprocess.run(
        ["/bin/sh", "-lc", "cd /workspace/luminax && (docker compose ps || docker-compose ps || true)"],
        capture_output=True,
        text=True,
    )
    log_tail = ""
    if service_name.strip():
        safe = "".join(ch for ch in service_name.strip() if ch.isalnum() or ch in "-_")
        if safe:
            tail_cmd = f"cd /workspace/luminax && (docker compose logs --tail {max(20, min(max_log_lines, 400))} {safe} || docker logs --tail {max(20, min(max_log_lines, 400))} {safe} || true)"
            tails = subprocess.run(["/bin/sh", "-lc", tail_cmd], capture_output=True, text=True)
            log_tail = (tails.stdout + "\n" + tails.stderr)[-20000:]
    return {
        "checks": checks,
        "compose_ps": (compose_ps.stdout + "\n" + compose_ps.stderr)[-20000:],
        "service_log_tail": log_tail,
    }

async def make_self_repair_plan(target: str, service: str, error_context: str, diagnostics: dict[str, Any]) -> str:
    caps = load_dynamic_capabilities()
    prompt = (
        "You are Zeus self-maintenance planner.\n"
        "Write a concrete repair plan with sections:\n"
        "1) Root-cause hypotheses\n2) Safe file changes\n3) Test commands\n4) Rollback plan\n5) Restart/check commands.\n"
        "Never claim changes are already applied.\n\n"
        f"Target: {target}\n"
        f"Service: {service or 'unspecified'}\n"
        f"Error context:\n{error_context or '(none provided)'}\n\n"
        f"Capabilities:\n{json.dumps(caps, ensure_ascii=False)[:12000]}\n\n"
        f"Diagnostics:\n{json.dumps(diagnostics, ensure_ascii=False)[:14000]}"
    )
    messages = [
        {"role": "system", "content": build_system_prompt() + "\nYou are generating a self-repair plan only."},
        {"role": "user", "content": prompt},
    ]
    if SELF_REPAIR_PROVIDER == "openai" and OPENAI_ENABLE and OPENAI_API_KEY:
        try:
            return await openai_chat_text(messages, OPENAI_SELF_REPAIR_MODEL)
        except Exception:
            pass
    reasoning_model = resolve_active_models().get("reasoning", {}).get("model", MODEL_REASONING)
    r = await ollama_chat(messages, model=reasoning_model, stream=False)
    return r.json().get("message", {}).get("content", "No self-repair plan generated.")

