def looks_like_capability_query(prompt: str) -> bool:
    text = (prompt or "").strip().lower()
    if not text:
        return False
    if any(hint in text for hint in CAPABILITY_QUERY_HINTS):
        return True
    compact = re.sub(r"[^a-z0-9 ]+", " ", text)
    tokens = set([t for t in compact.split() if t])
    signal = {"capabilities", "skills", "features", "tools", "limits", "roadmap"}
    return len(tokens & signal) >= 2 and ("you" in tokens or "zeus" in tokens)

