def is_actionable_prompt(prompt: str) -> bool:
    text = (prompt or "").strip().lower()
    if not text:
        return False
    strong_hints = [
        "build",
        "change",
        "create",
        "setup",
        "set up",
        "install",
        "deploy",
        "fix",
        "replace",
        "repair",
        "run",
        "execute",
        "configure",
        "publish",
        "update",
        "improve",
        "continue",
        "keep going",
        "work on",
        "move forward",
        "follow through",
        "finish",
        "complete",
        "take care of",
        "handle this",
    ]
    if text.endswith("?") and len(text.split()) < 9 and not any(h in text for h in strong_hints):
        return False
    return any(h in text for h in ACTIONABLE_HINTS)

def is_suggestion_prompt(prompt: str) -> bool:
    text = (prompt or "").strip().lower()
    if not text:
        return False
    return any(h in text for h in SUGGESTION_HINTS)

def discord_request_prefers_actionable(
    prompt: str,
    *,
    mode: str = "conversation",
    project_key: str = "",
    actor_role: str = "",
    request_source: str = "",
    authorized_capabilities: Optional[list[str]] = None,
) -> bool:
    normalized_mode = str(mode or "conversation").strip().lower() or "conversation"
    if normalized_mode in {"lookup", "lookup_deep", "voice"}:
        return False
    if normalized_mode == "action":
        return True
    normalized_source = str(request_source or "").strip().lower()
    if normalized_source == "zeus_planner":
        return False
    if is_actionable_prompt(prompt):
        return True
    project_resolved = bool(normalize_project_key(project_key))
    capabilities = {
        str(item).strip().lower()
        for item in (authorized_capabilities or [])
        if str(item).strip()
    }
    role = str(actor_role or "").strip().lower()
    has_execution_capability = bool(capabilities & DISCORD_ACTIONABLE_CAPABILITIES)
    trusted_role = role in {"owner", "operator", "platform_admin", "admin", "founder"}
    return project_resolved and normalized_source.startswith("discord") and (has_execution_capability or trusted_role)

def discord_request_allow_write(
    *,
    actor_role: str = "",
    authorized_capabilities: Optional[list[str]] = None,
) -> bool:
    capabilities = {
        str(item).strip().lower()
        for item in (authorized_capabilities or [])
        if str(item).strip()
    }
    role = str(actor_role or "").strip().lower()
    if role in {"owner", "operator", "platform_admin", "admin", "founder"}:
        return True
    return bool(capabilities & {"project_task", "codex_task", "deploy_execute", "discord_admin", "branding_sync"})

def action_kernel_scan(prompt: str) -> dict[str, Any]:
    text = (prompt or "").strip()
    words = [w for w in text.split() if w.strip()]
    actionable = is_actionable_prompt(text)
    confidence = 0.15
    if actionable:
        confidence = min(0.95, 0.35 + (len(words) / 26.0))
    summary = {
        "actionable": actionable,
        "confidence": round(confidence, 3),
        "word_count": len(words),
        "normalized_project_key": normalize_project_key(text),
        "hints_matched": [h for h in ACTIONABLE_HINTS if h in text.lower()][:8],
    }
    return {
        "status": "ok",
        "scan": summary,
        "next": {
            "recommended_mode": "auto_execute" if actionable else "chat_only",
            "kernel_run_route": "/api/action/kernel/run",
            "kernel_runs_route": "/api/action/kernel/runs",
        },
    }


LOCAL_COMPANION_SURFACES = {"luminax_local", "luminax_voice"}
LOCAL_COMPANION_ROOM_KINDS = {"desktop_voice", "desktop_companion", "desktop_local"}


def is_local_companion_surface(meta: Any = None, room_kind: str = "") -> bool:
    payload = meta if isinstance(meta, dict) else {}
    surface = str(payload.get("surface") or "").strip().lower()
    room_kind_key = str(room_kind or "").strip().lower()
    return surface in LOCAL_COMPANION_SURFACES or room_kind_key in LOCAL_COMPANION_ROOM_KINDS


def _local_companion_voice_turn(trace_ctx: dict[str, Any]) -> bool:
    meta = trace_ctx.get("meta") if isinstance(trace_ctx.get("meta"), dict) else {}
    surface = str(meta.get("surface") or "").strip().lower()
    view = str(meta.get("view") or "").strip().lower()
    room_kind = str(trace_ctx.get("room_kind") or "").strip().lower()
    return surface == "luminax_voice" or view == "voice" or room_kind == "desktop_voice"


def _local_companion_autonomy_reply(final_text: str, autonomy: dict[str, Any]) -> str:
    status = str(autonomy.get("status") or "unknown").strip().lower()
    mode = str(autonomy.get("execution_mode") or "").strip().lower()
    hive = autonomy.get("hive") if isinstance(autonomy.get("hive"), dict) else {}
    workflow = autonomy.get("workflow_run") if isinstance(autonomy.get("workflow_run"), dict) else {}
    friendly = str(
        autonomy.get("friendly_confirmation")
        or hive.get("friendly_confirmation")
        or ""
    ).strip()
    reason = str(
        autonomy.get("reason")
        or workflow.get("error")
        or autonomy.get("detail")
        or ""
    ).strip()
    if friendly:
        return friendly
    if status == "executed":
        return (final_text or "").strip() or "Done."
    if status == "planned" and mode == "plan_only":
        if reason:
            return f"I stayed in planning mode: {reason}"
        return "I stayed in planning mode."
    if status == "held_for_revision":
        if reason:
            return f"I need to revise the approach before acting: {reason}"
        return "I need to revise the approach before acting."
    if status == "failed":
        if reason:
            return f"I tried to do that, but it failed: {reason}"
        return "I tried to do that, but it failed."
    return (final_text or "").strip() or "I processed that request."


async def run_local_companion_chat(
    prompt: str,
    trace_ctx: dict[str, Any],
) -> tuple[str, list[dict[str, Any]], dict[str, Any] | None]:
    trace: list[dict[str, Any]] = []
    autonomy: dict[str, Any] | None = None
    voice_turn = _local_companion_voice_turn(trace_ctx)
    if voice_turn and not is_actionable_prompt(prompt):
        final_text = await quick_chat_response(
            prompt,
            memory_limit=0,
            extra_system=(
                "This is a live local voice conversation on the user's PC. "
                "Reply immediately in one short spoken sentence by default, or two very short sentences max when needed. "
                "Do not mention permissions, routing, project lanes, review, or internal tooling."
            ),
        )
        return sanitize_user_facing_reply(final_text), trace, autonomy

    memories = [] if voice_turn else await lookup_memory(prompt)
    if memories:
        owner_trace_log(
            "memory",
            "system",
            "memory_lookup",
            f"Loaded {len(memories)} memory matches",
            "\n".join([_truncate_text(m, 220) for m in memories[:4]]),
            room_key=trace_ctx["room_key"],
            room_label=trace_ctx["room_label"],
            room_kind=trace_ctx["room_kind"],
            speaker=trace_ctx["speaker"],
            session_id=trace_ctx["session_id"],
            meta={"phase": "memory", "surface": trace_ctx["meta"].get("surface") or "luminax_local"},
        )
    enriched_prompt = prompt
    if memories:
        enriched_prompt = f"{prompt}\n\nRelevant memory:\n" + "\n".join(memories)
    final_text, trace = await maybe_execute_tools(enriched_prompt, max_rounds=3 if voice_turn else 6)
    if not voice_turn:
        final_text = await apply_accuracy_gate(prompt, final_text, trace)
    if voice_turn:
        final_text = sanitize_user_facing_reply(final_text)
    if is_actionable_prompt(prompt) and not trace:
        try:
            autonomy = await run_proactive_autonomy(
                prompt,
                source="luminax_local",
                seed_response=final_text,
                force_execute=True,
            )
        except Exception as e:
            autonomy = {"status": "error", "detail": str(e)}
        if autonomy and str(autonomy.get("execution_mode") or "").strip().lower() not in {"project_thread"}:
            final_text = _local_companion_autonomy_reply(final_text, autonomy)
    return final_text, trace, autonomy

def current_web_auth_user() -> str:
    return (web_auth_user_ctx.get("") or "").strip().lower()

def request_has_trusted_web_control() -> bool:
    return TRUST_PROXY_AUTH_HEADERS and bool(TRUSTED_WEB_CONTROL_USER) and current_web_auth_user() == TRUSTED_WEB_CONTROL_USER

def require_owner_trace_access(detail: str = "Owner trace is restricted") -> str:
    user = current_web_auth_user()
    if not request_has_trusted_web_control():
        raise HTTPException(status_code=403, detail=detail)
    return user

def control_granted() -> bool:
    return request_has_trusted_web_control() or redis_client.get("luminax_control_granted") == "true"

def request_has_operator_control(token: str = "") -> bool:
    if request_has_trusted_web_control():
        return True
    return request_has_connector_token(token) and redis_client.get("luminax_control_granted") == "true"

def request_has_connector_token(token: str = "") -> bool:
    return len(CONTROL_TOKEN) >= 32 and hmac.compare_digest((token or "").strip().encode("utf-8"), CONTROL_TOKEN.encode("utf-8"))

def control_session_payload() -> dict[str, Any]:
    user = current_web_auth_user()
    return {
        "control_granted": control_granted(),
        "web_auth_user": user or None,
        "trusted_web_control_user": TRUSTED_WEB_CONTROL_USER or None,
        "web_control_auto_granted": request_has_trusted_web_control(),
    }

def require_control_token(token: str, detail: str = "Control not granted"):
    if not request_has_operator_control(token):
        raise HTTPException(status_code=403, detail=detail)

def require_connector_token(token: str, detail: str = "Connector token invalid"):
    if not request_has_connector_token(token):
        raise HTTPException(status_code=403, detail=detail)

def require_media_job_token(token: str, detail: str = "Media job auth failed"):
    if request_has_operator_control(token) or request_has_connector_token(token):
        return
    raise HTTPException(status_code=403, detail=detail)

def _autonomy_run_path(run_id: str) -> Path:
    safe = "".join(ch for ch in (run_id or "").strip().lower() if ch.isalnum() or ch in "-_")
    if not safe:
        raise HTTPException(status_code=400, detail="Invalid autonomy run id")
    return AUTONOMY_RUN_ROOT / f"{safe}.json"

def _list_autonomy_runs(limit: int = 120) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for p in sorted(AUTONOMY_RUN_ROOT.glob("*.json"), reverse=True)[:max(1, min(limit, 600))]:
        try:
            data = json.loads(p.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                rows.append(data)
        except Exception:
            continue
    return rows

