@app.get("/api/health")
async def health():
    runtime_policy = load_runtime_policy()
    checks = {"status": "ok", "services": {}}
    try:
        redis_client.ping()
        checks["services"]["redis"] = {"status": "ok"}
    except Exception as e:
        checks["status"] = "degraded"
        checks["services"]["redis"] = {"status": "error", "detail": str(e)}
    try:
        qdrant.get_collections()
        checks["services"]["qdrant"] = {"status": "ok"}
    except Exception as e:
        checks["status"] = "degraded"
        checks["services"]["qdrant"] = {"status": "error", "detail": str(e)}
    try:
        conn = db_conn()
        conn.close()
        checks["services"]["mysql"] = {"status": "ok"}
    except Exception as e:
        checks["status"] = "degraded"
        checks["services"]["mysql"] = {"status": "error", "detail": str(e)}
    optional_services = {
        "hive_dreamer": f"{HIVE_DREAMER_URL}/health",
        "hive_engineer": f"{HIVE_ENGINEER_URL}/health",
        "hive_critic": f"{HIVE_CRITIC_URL}/health",
        "threed_engineer": f"{THREED_ENGINEER_URL}/health",
        "finance_swarm": f"{FINANCE_SWARM_URL}/health",
        "luminax_brain": f"{LUMINAX_BRAIN_URL}/health",
        "affect_controller": f"{AFFECT_CONTROLLER_URL}/health",
        "mcp_router": f"{MCP_ROUTER_URL}/health",
        "langgraph_orchestrator": f"{LANGGRAPH_URL}/health",
    }
    for name, url in optional_services.items():
        try:
            payload = await _fetch_json(url, timeout=1.5)
            checks["services"][name] = {"status": "ok", "data": payload}
        except Exception as e:
            checks["services"][name] = {"status": "idle", "detail": str(e)}
    checks["runtime_policy"] = runtime_policy
    checks["worker_pause"] = runtime_worker_pause_state()
    checks["active_models"] = resolve_active_models()
    return checks

