@app.post("/api/discord/action/review")
async def discord_action_review(req: DiscordActionReviewRequest):
    require_connector_token(req.token)
    action_kind = _discord_action_kind(req.action_kind)
    access = resolve_discord_actor_access(
        discord_user_id=req.discord_user_id,
        project_key=req.project_key,
        guild_id=req.guild_id,
        channel_id=req.channel_id,
    )
    authorized_capabilities = access.get("authorized_capabilities") if isinstance(access.get("authorized_capabilities"), list) else []
    required_capabilities = discord_action_required_capabilities(action_kind)
    has_required_capabilities = all(cap in authorized_capabilities for cap in required_capabilities)
    can_oracle_override = "oracle_override" in authorized_capabilities
    can_execute = bool(access.get("can_command")) or bool(access.get("server_operator"))
    can_view = bool(access.get("can_view")) or bool(access.get("server_operator"))
    detail = ""
    if action_kind == "conversation":
        approved = bool(access.get("linked") or can_view or can_execute)
        detail = "Linked conversation lane ready." if approved else "This Discord identity is not linked to Olympus yet."
        return {
            "status": "ok",
            "approved": approved,
            "action_kind": action_kind,
            "detail": detail,
            "allow_write": False,
            "policy": access,
            "required_capabilities": required_capabilities,
        }
    if action_kind == "lookup":
        approved = can_view and (has_required_capabilities or not required_capabilities)
        detail = "Lookup is allowed in this project lane." if approved else "Project lookup is not granted in this lane."
        return {
            "status": "ok",
            "approved": approved,
            "action_kind": action_kind,
            "detail": detail,
            "allow_write": False,
            "policy": access,
            "required_capabilities": required_capabilities,
        }
    if not can_execute:
        detail = "This Discord actor does not have project execution rights in the current lane."
    elif not has_required_capabilities:
        detail = f"Missing required capability for {action_kind}: {', '.join(required_capabilities)}"
    deploy_rights = access.get("deploy_rights") if isinstance(access.get("deploy_rights"), dict) else {}
    if not detail and action_kind == "deploy" and not bool(deploy_rights.get("allowed")):
        detail = "Deploy execution is not allowed for this job template."
    debate: dict[str, Any] = {}
    critic_reject = False
    approved = False
    oracle_override_used = False
    if not detail:
        debate = await run_hive_debate(
            goal=req.goal,
            project_key=access.get("project_key") or req.project_key,
            auto_create_project=False,
            create_tasks=False,
            source=f"discord_{action_kind}_review",
        )
        turns = debate.get("turns") if isinstance(debate.get("turns"), list) else []
        critic_reject = any(
            str(turn.get("brain") or "").strip().lower() == "critic"
            and str(turn.get("vote_bucket") or "").strip().lower() == "reject"
            for turn in turns
            if isinstance(turn, dict)
        )
        approved = bool(debate.get("consensus_passed")) and not critic_reject
        revise_count = int(debate.get("revise_count") or 0)
        reject_count = int(debate.get("reject_count") or 0)
        if (
            not approved
            and not critic_reject
            and reject_count == 0
            and revise_count >= 2
            and can_oracle_override
            and can_execute
            and has_required_capabilities
            and action_kind in {"implement", "deploy", "branding_sync", "discord_admin"}
        ):
            approved = True
            oracle_override_used = True
        summary = str(debate.get("summary") or "").strip()
        if oracle_override_used:
            detail = (summary + " " if summary else "") + f"Zeus used oracle_override to convert revise-only consensus into a guarded {action_kind} approval."
        else:
            detail = summary or ("Oracle Chamber approved." if approved else "Oracle Chamber held the action for revision.")
    allow_write = bool(req.allow_write and approved and can_execute and action_kind in {"implement", "deploy", "branding_sync", "discord_admin"})
    record_meta = {
        "discord_user_id": req.discord_user_id,
        "guild_id": req.guild_id,
        "channel_id": req.channel_id,
        "project_key": access.get("project_key") or req.project_key,
        "job_template": access.get("job_template") or access.get("actor_role"),
        "required_capabilities": required_capabilities,
        "approved": approved,
        "action_kind": action_kind,
        "allow_write": allow_write,
        "oracle_override_used": oracle_override_used,
    }
    activity_log(
        "assistant-core",
        "discord_action_review",
        "ok" if approved else "blocked",
        f"Discord review {action_kind}",
        discord_action_review_summary(access, action_kind, req.goal),
        {**record_meta, "detail": detail},
    )
    return {
        "status": "ok",
        "approved": approved,
        "action_kind": action_kind,
        "detail": detail,
        "allow_write": allow_write,
        "policy": access,
        "required_capabilities": required_capabilities,
        "debate": debate,
        "critic_reject": critic_reject,
        "oracle_override_used": oracle_override_used,
    }

