@app.post("/api/skills/planned/add")
async def skills_planned_add(req: PlannedSkillRequest):
    require_control_token(req.token)
    key = "".join(ch for ch in (req.key or "").strip().lower() if ch.isalnum() or ch in "-_")
    if not key:
        raise HTTPException(status_code=400, detail="Skill key is required")
    status = (req.status or "planned").strip().lower()
    if status not in {"planned", "researching", "in_progress"}:
        status = "planned"
    entry = {
        "key": key,
        "description": (req.description or "").strip(),
        "status": status,
        "owner": (req.owner or "operator").strip(),
        "notes": (req.notes or "").strip(),
        "updated_at": int(time.time()),
    }
    rows = load_planned_skill_memory()
    replaced = False
    for i, row in enumerate(rows):
        if str(row.get("key", "")).strip() == key:
            rows[i] = entry
            replaced = True
            break
    if not replaced:
        rows.append(entry)
    save_planned_skill_memory(rows)
    await save_memory(
        f"PLANNED SKILL UPDATE\nkey={key}\nstatus={status}\nowner={entry['owner']}\ndescription={entry['description']}\nnotes={entry['notes']}"
    )
    return {"status": "ok", "entry": entry, "planned_total": len(rows), "planned_skill_memory_path": str(PLANNED_SKILL_MEMORY_PATH)}

