@app.post("/api/models/hub/install")
async def models_hub_install(req: ModelHubInstallRequest):
    require_control_token(req.token)
    model_key = _normalize_model_key(req.model_key)
    if not model_key:
        raise HTTPException(status_code=400, detail="model_key is required")
    data = _model_catalog_doc()
    model_entry = next((m for m in data.get("models", []) if isinstance(m, dict) and _normalize_model_key(m.get("model_key")) == model_key), None)
    if not model_entry:
        raise HTTPException(status_code=404, detail="Model key not found in catalog")
    plan = _build_install_plan(model_entry, req)
    job_id = uuid.uuid4().hex[:12]
    job = {
        "job_id": job_id,
        "created_at": int(time.time()),
        "model_key": model_key,
        "model_category": model_entry.get("category"),
        "provider": plan.get("provider"),
        "install_mode": plan.get("install_mode"),
        "plan": plan,
        "status": "planned",
        "execution": {},
    }
    _model_job_path(job_id).write_text(json.dumps(job, indent=2), encoding="utf-8")
    try:
        execution = await _execute_model_install_plan(plan)
        job["execution"] = execution
        job["completed_at"] = int(time.time())
        exec_status = str(execution.get("status", "")).strip().lower()
        if exec_status == "executed":
            job["status"] = "installed"
            _update_model_catalog_entry(model_key, "installed", req.notes, {"last_install_job": job_id, "last_install_ts": int(time.time())})
        elif exec_status == "manual_required":
            job["status"] = "manual_required"
            _update_model_catalog_entry(model_key, "manual_required", req.notes, {"last_install_job": job_id})
        else:
            job["status"] = "planned"
            _update_model_catalog_entry(model_key, "planned", req.notes, {"last_install_job": job_id})
    except Exception as e:
        job["status"] = "failed"
        job["completed_at"] = int(time.time())
        job["execution"] = {"status": "failed", "error": str(e)}
        _update_model_catalog_entry(model_key, "failed", str(e), {"last_install_job": job_id})
    _model_job_path(job_id).write_text(json.dumps(job, indent=2), encoding="utf-8")
    activity_log("assistant-core", "model_hub_install", "ok" if job["status"] != "failed" else "error", f"Model install job {job_id}", model_key, {"status": job["status"], "provider": plan.get("provider")})
    return {"status": "ok", "job": job}

