@app.post("/api/groupup/rooms/create")
async def groupup_room_create(req: GroupUpRoomCreateRequest):
    title = (req.title or "GroupUp Room").strip() or "GroupUp Room"
    room_key = normalize_groupup_key(req.room_key, default=normalize_groupup_key(title, default=f"groupup-{uuid.uuid4().hex[:6]}"))
    room_path = _groupup_room_path(room_key)
    if room_path.exists():
        raise HTTPException(status_code=409, detail="GroupUp room already exists")
    now = int(time.time())
    palette = _groupup_theme_palette(req.theme)
    host_name = (req.host_name or "Host").strip() or "Host"
    host_token = uuid.uuid4().hex + uuid.uuid4().hex[:8]
    host_participant_token = uuid.uuid4().hex + uuid.uuid4().hex[:8]
    host_participant_id = uuid.uuid4().hex[:12]
    room = {
        "room_key": room_key,
        "title": title,
        "project_key": normalize_project_key(req.project_key or "groupup") or "groupup",
        "theme": normalize_groupup_key(req.theme, default="confetti_arcade"),
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "host": {
            "display_name": host_name,
            "host_token": host_token,
            "participant_token": host_participant_token,
            "participant_id": host_participant_id,
        },
        "overlay": {
            "preset": "auto",
            "headline": (req.headline or title).strip() or title,
            "subheadline": (req.subheadline or "Live tonight test room").strip() or "Live tonight test room",
            "ticker": "GroupUp overlay live. Join the room and your tile appears automatically.",
            "show_names": True,
            "focus_participant_id": "",
            "accent_primary": palette["primary"],
            "accent_secondary": palette["secondary"],
            "background_asset": "",
            "logo_asset": "",
            "frame_asset": "",
        },
        "participants": [
            {
                "participant_id": host_participant_id,
                "participant_token": host_participant_token,
                "display_name": host_name,
                "color": palette["primary"],
                "note": "Host",
                "status": "online",
                "joined_at": now,
                "last_seen_at": now,
                "role": "host",
                "is_host": True,
                "avatar_asset": "",
            }
        ],
    }
    _groupup_write_room(room)
    return {
        "status": "created",
        "room": _groupup_sanitized_room(room, viewer="host"),
        "host_token": host_token,
        "host_participant_token": host_participant_token,
        "join_url": _groupup_join_url(room_key),
        "room_url": _groupup_room_url(room_key, host_participant_token),
        "host_url": _groupup_host_url(room_key, host_token),
        "overlay_url": _groupup_overlay_url(room_key),
        "project_url": _groupup_project_url(),
    }


@app.post("/api/groupup/rooms/join")
async def groupup_room_join(req: GroupUpRoomJoinRequest):
    room = _groupup_refresh_presence(_groupup_read_room(req.room_key))
    if str(room.get("status", "active")).lower() != "active":
        raise HTTPException(status_code=400, detail="Room is not active")
    now = int(time.time())
    display_name = (req.display_name or "").strip()
    if not display_name:
        raise HTTPException(status_code=400, detail="display_name is required")
    palette = _groupup_theme_palette(str(room.get("theme", "confetti_arcade")))
    participant = {
        "participant_id": uuid.uuid4().hex[:12],
        "participant_token": uuid.uuid4().hex + uuid.uuid4().hex[:8],
        "display_name": display_name[:48],
        "color": _groupup_color(req.color, palette["secondary"]),
        "note": (req.note or "").strip()[:120],
        "status": "online",
        "joined_at": now,
        "last_seen_at": now,
        "role": "guest",
        "is_host": False,
        "avatar_asset": "",
    }
    room.setdefault("participants", []).append(participant)
    _groupup_write_room(room)
    return {
        "status": "joined",
        "participant": {k: v for k, v in participant.items() if k != "participant_token"},
        "participant_token": participant["participant_token"],
        "room": _groupup_sanitized_room(room, viewer="self"),
        "room_url": _groupup_room_url(str(room.get("room_key", "")), participant["participant_token"]),
        "overlay_url": _groupup_overlay_url(str(room.get("room_key", ""))),
    }


@app.get("/api/groupup/rooms/{room_key}")
async def groupup_room_detail(room_key: str, host_token: str = Query(default=""), participant_token: str = Query(default="")):
    room = _groupup_refresh_presence(_groupup_read_room(room_key))
    viewer = "public"
    if host_token and str((room.get("host") or {}).get("host_token", "")) == host_token:
        viewer = "host"
    elif participant_token:
        try:
            _groupup_find_participant(room, participant_token)
            viewer = "self"
        except HTTPException:
            viewer = "public"
    data = _groupup_sanitized_room(room, viewer=viewer)
    if viewer == "host":
        data["host_url"] = _groupup_host_url(room_key, host_token)
        data["room_url"] = _groupup_room_url(room_key, str((room.get("host") or {}).get("participant_token", "")))
    elif viewer == "self":
        data["room_url"] = _groupup_room_url(room_key, participant_token)
    return {"status": "ok", "viewer": viewer, "room": data}


