@app.post("/api/groupup/rooms/{room_key}/assets/upload")
async def groupup_asset_upload(
    room_key: str,
    kind: str = Form(default="logo"),
    host_token: str = Form(default=""),
    participant_token: str = Form(default=""),
    file: UploadFile = File(...),
):
    room = _groupup_read_room(room_key)
    safe_kind = normalize_groupup_key(kind, default="asset")
    content = await file.read()
    if not content:
        raise HTTPException(status_code=400, detail="Uploaded file is empty")
    if len(content) > GROUPUP_UPLOAD_MAX_BYTES:
        raise HTTPException(status_code=413, detail="Uploaded file is too large")
    filename = _groupup_safe_upload_name(file.filename or f"{safe_kind}.png")
    root = _groupup_room_assets_root(room_key)
    viewer = "host"
    if participant_token.strip():
        participant = _groupup_find_participant(room, participant_token)
        viewer = "self"
        target_dir = root / "participants"
        target_dir.mkdir(parents=True, exist_ok=True)
        stored_name = f"{participant['participant_id']}_{safe_kind}_{filename}"
        target = (target_dir / stored_name).resolve()
        target.write_bytes(content)
        asset_url = _groupup_public_asset_url(room_key, f"participants/{stored_name}")
        participant["avatar_asset"] = asset_url
        participant["last_seen_at"] = int(time.time())
    else:
        _groupup_validate_host(room, host_token)
        target_dir = root / "room"
        target_dir.mkdir(parents=True, exist_ok=True)
        stored_name = f"{safe_kind}_{int(time.time())}_{filename}"
        target = (target_dir / stored_name).resolve()
        target.write_bytes(content)
        asset_url = _groupup_public_asset_url(room_key, f"room/{stored_name}")
        overlay = room.setdefault("overlay", {})
        if safe_kind in {"logo", "background", "frame"}:
            overlay[f"{safe_kind}_asset"] = asset_url
        else:
            overlay["logo_asset"] = asset_url
    _groupup_write_room(room)
    return {"status": "ok", "asset_url": asset_url, "room": _groupup_sanitized_room(_groupup_refresh_presence(room), viewer=viewer)}


@app.get("/api/groupup/rooms/{room_key}/assets/{file_path:path}")
async def groupup_asset_file(room_key: str, file_path: str):
    base = _groupup_room_assets_root(room_key)
    target = (base / _site_rel_path(file_path)).resolve()
    if not str(target).startswith(str(base.resolve())):
        raise HTTPException(status_code=400, detail="Invalid GroupUp asset path")
    if not target.exists() or not target.is_file():
        raise HTTPException(status_code=404, detail="GroupUp asset not found")
    return FileResponse(target)


