@app.get("/api/media/jobs/{job_id}/files/{file_path:path}")
async def media_job_file(job_id: str, file_path: str):
    base = _music_job_workspace(job_id)
    target = (base / _site_rel_path(file_path)).resolve()
    if not str(target).startswith(str(base.resolve())):
        raise HTTPException(status_code=400, detail="Invalid media job file path")
    if not target.exists() or not target.is_file():
        raise HTTPException(status_code=404, detail="Media job file not found")
    media_type = mimetypes.guess_type(target.name)[0] or "application/octet-stream"
    return FileResponse(target, media_type=media_type, filename=target.name)

