@app.get("/api/broadcast/overview")
async def broadcast_overview(project_key: str = Query(default="")):
    accounts = await _broadcast_call("GET", f"/accounts?project_key={quote(project_key)}" if project_key else "/accounts")
    overlays = await _broadcast_call("GET", f"/overlays?project_key={quote(project_key)}" if project_key else "/overlays")
    sessions = await _broadcast_call("GET", f"/sessions?project_key={quote(project_key)}" if project_key else "/sessions")
    commentary = await _broadcast_call("GET", f"/commentary?project_key={quote(project_key)}" if project_key else "/commentary")
    providers = await _broadcast_call("GET", "/providers")
    return {
        "status": "ok",
        "project_key": project_key or None,
        "providers": providers.get("providers", providers),
        "accounts": accounts.get("rows", []),
        "overlays": overlays.get("rows", []),
        "sessions": sessions.get("rows", []),
        "commentary": commentary.get("rows", []),
        "summary": {
            "account_count": len(accounts.get("rows", [])),
            "overlay_count": len(overlays.get("rows", [])),
            "session_count": len(sessions.get("rows", [])),
            "commentary_count": len(commentary.get("rows", [])),
        },
    }

