@app.post("/api/workflows/save")
async def workflows_save(req: WorkflowSaveRequest):
    require_control_token(req.token)
    key = normalize_workflow_key(req.workflow_key)
    if not key:
        raise HTTPException(status_code=400, detail="workflow_key is required")
    payload = {
        "workflow_key": key,
        "title": (req.title or key).strip() or key,
        "description": (req.description or "").strip(),
        "nodes": req.nodes if isinstance(req.nodes, list) else [],
        "edges": req.edges if isinstance(req.edges, list) else [],
        "variables": req.variables if isinstance(req.variables, dict) else {},
        "updated_at": int(time.time()),
        "source": "api",
    }
    saved = save_workflow_def(key, payload)
    activity_log("assistant-core", "workflow_save", "ok", f"Workflow saved: {key}", payload.get("description", ""), {"path": saved.get("path")})
    cognition_log("assistant-core", "core", "workflow", f"Workflow saved: {key}", payload.get("description", ""), {"nodes": len(payload.get("nodes", [])), "edges": len(payload.get("edges", []))})
    return {"status": "ok", **saved, "workflow": payload}

@app.post("/api/workflows/run")
async def workflows_run(req: WorkflowRunRequest):
    key = normalize_workflow_key(req.workflow_key)
    wf = read_workflow_def(key)
    run_id = uuid.uuid4().hex[:12]
    max_steps = max(1, min(req.max_steps, 40))
    steps = []
    errors = 0
    for node in (wf.get("nodes", []) if isinstance(wf.get("nodes"), list) else [])[:max_steps]:
        node_id = str(node.get("id", "")).strip() or f"node_{len(steps)+1}"
        node_type = str(node.get("type", "")).strip().lower()
        params = node.get("params", {}) if isinstance(node.get("params"), dict) else {}
        step = {"node_id": node_id, "type": node_type, "status": "noop", "result": None}
        try:
            if node_type == "task":
                step["result"] = await run_internal_tool(
                    "tasks.create",
                    {
                        "goal": str(params.get("goal", "workflow task")).strip(),
                        "project_key": params.get("project_key"),
                        "entails": str(params.get("entails", "")).strip(),
                        "source": "workflow",
                    },
                )
                step["status"] = "ok"
            elif node_type == "tool":
                tool_name = str(params.get("tool", "")).strip()
                tool_args = params.get("args", {}) if isinstance(params.get("args"), dict) else {}
                if not tool_name:
                    raise RuntimeError("tool node missing params.tool")
                step["result"] = await run_internal_tool(tool_name, tool_args)
                step["status"] = "ok"
            elif node_type == "chat":
                prompt = str(params.get("prompt", "")).strip()
                step["result"] = {"response": await quick_chat_response(prompt or "workflow chat node")}
                step["status"] = "ok"
            elif node_type == "model_install":
                model_key = str(params.get("model_key", "")).strip()
                if not model_key:
                    raise RuntimeError("model_install node missing params.model_key")
                model_req = ModelHubInstallRequest(
                    token=CONTROL_TOKEN,
                    model_key=model_key,
                    install_mode=str(params.get("install_mode", "plan")).strip() or "plan",
                    provider=str(params.get("provider", "")).strip(),
                    profile=str(params.get("profile", "")).strip(),
                    model_tag=str(params.get("model_tag", "")).strip(),
                    notes=str(params.get("notes", "")).strip(),
                )
                doc = _model_catalog_doc()
                model_entry = next(
                    (m for m in doc.get("models", []) if isinstance(m, dict) and _normalize_model_key(m.get("model_key")) == _normalize_model_key(model_req.model_key)),
                    None,
                )
                if not model_entry:
                    raise RuntimeError(f"model_key not found: {model_req.model_key}")
                step["result"] = {"plan": _build_install_plan(model_entry, model_req), "model": model_entry}
                step["status"] = "ok"
            elif node_type == "model_infer":
                model = str(params.get("model", "")).strip()
                prompt = str(params.get("prompt", "")).strip()
                provider = str(params.get("provider", "")).strip().lower() or resolve_active_models().get("fast", {}).get("provider", "ollama")
                if not model:
                    raise RuntimeError("model_infer node missing params.model")
                if not prompt:
                    raise RuntimeError("model_infer node missing params.prompt")
                if provider == "openai" and OPENAI_ENABLE and OPENAI_API_KEY:
                    step["result"] = {"provider": "openai", "model": model, "response": await openai_chat_text([{"role": "user", "content": prompt}], model)}
                else:
                    result = await ollama_chat([{"role": "user", "content": prompt}], model=model, stream=False)
                    step["result"] = {"provider": "ollama", "model": model, "response": result.json().get("message", {}).get("content", "")}
                step["status"] = "ok"
            elif node_type in {"generate3dasset", "generate_3d_asset"}:
                prompt = str(params.get("prompt", "")).strip()
                if not prompt:
                    raise RuntimeError("generate3dasset node missing params.prompt")
                step["result"] = await generate_3d_asset_job(
                    prompt=prompt,
                    asset_name=str(params.get("asset_name", "")).strip(),
                    provider=str(params.get("provider", "triposr")).strip() or "triposr",
                    source_image=str(params.get("source_image", "")).strip(),
                )
                step["status"] = "ok"
            elif node_type in {"buildgameproject", "build_game_project", "buildunityproject", "build_unity_project", "buildue5project", "build_ue5_project"}:
                project_key = normalize_project_key(params.get("project_key"))
                if not project_key:
                    raise RuntimeError("buildgameproject node missing params.project_key")
                default_engine = "ue5" if node_type in {"buildue5project", "build_ue5_project"} else "unity6"
                step["result"] = await build_game_project_job(
                    project_key=project_key,
                    title=str(params.get("title", pretty_label(project_key))).strip() or pretty_label(project_key),
                    template=str(params.get("template", "third_person")).strip() or "third_person",
                    engine=str(params.get("engine", default_engine)).strip() or default_engine,
                    notes=str(params.get("notes", "")).strip(),
                )
                step["status"] = "ok"
            elif node_type in {"spingameserver", "spin_game_server"}:
                project_key = normalize_project_key(params.get("project_key"))
                if not project_key:
                    raise RuntimeError("spingameserver node missing params.project_key")
                step["result"] = await spin_game_server_job(
                    project_key=project_key,
                    server_type=str(params.get("server_type", "node")).strip() or "node",
                    notes=str(params.get("notes", "")).strip(),
                )
                step["status"] = "ok"
            elif node_type in {"deploygame", "deploy_game"}:
                project_key = normalize_project_key(params.get("project_key"))
                if not project_key:
                    raise RuntimeError("deploygame node missing params.project_key")
                step["result"] = await deploy_game_job(
                    project_key=project_key,
                    target=str(params.get("target", "docker_tls")).strip() or "docker_tls",
                    notes=str(params.get("notes", "")).strip(),
                )
                step["status"] = "ok"
            elif node_type == "wait":
                seconds = max(0.0, min(float(params.get("seconds", 1) or 1), 30.0))
                await asyncio.sleep(seconds)
                step["result"] = {"slept_seconds": seconds}
                step["status"] = "ok"
            elif node_type == "note":
                text = str(params.get("text", "")).strip()
                step["result"] = {"note": text}
                step["status"] = "ok"
            else:
                step["result"] = {"detail": "unsupported node type (scaffold-safe noop)"}
        except Exception as e:
            errors += 1
            step["status"] = "error"
            step["result"] = {"error": str(e)}
        steps.append(step)
    run_payload = {
        "run_id": run_id,
        "workflow_key": key,
        "status": "completed_with_errors" if errors else "completed",
        "error_count": errors,
        "started_at": int(time.time()),
        "steps": steps,
        "variables": req.variables if isinstance(req.variables, dict) else {},
    }
    run_path = WORKFLOW_RUN_ROOT / f"{run_id}.json"
    run_path.parent.mkdir(parents=True, exist_ok=True)
    run_path.write_text(json.dumps(run_payload, indent=2), encoding="utf-8")
    activity_log("assistant-core", "workflow_run", "ok" if not errors else "warn", f"Workflow run {run_id} for {key}", "", {"error_count": errors})
    return {"status": run_payload["status"], "run_id": run_id, "workflow_key": key, "steps": steps, "error_count": errors}

@app.get("/api/workflows/runs")
async def workflows_runs(workflow_key: str = Query(default="")):
    key = normalize_workflow_key(workflow_key) if (workflow_key or "").strip() else ""
    rows = []
    for p in sorted(WORKFLOW_RUN_ROOT.glob("*.json"), reverse=True)[:200]:
        try:
            data = json.loads(p.read_text(encoding="utf-8"))
            if key and str(data.get("workflow_key", "")).strip() != key:
                continue
            rows.append({
                "run_id": data.get("run_id"),
                "workflow_key": data.get("workflow_key"),
                "status": data.get("status"),
                "error_count": data.get("error_count", 0),
                "started_at": data.get("started_at"),
                "step_count": len(data.get("steps", []) if isinstance(data.get("steps"), list) else []),
                "path": str(p),
            })
        except Exception:
            continue
    return {"status": "ok", "rows": rows, "workflow_key": key or None}

