@app.post("/api/cli/exec")
async def cli_exec(req: CliExecRequest):
    require_control_token(req.token)
    command = " ".join((req.command or "").strip().split())
    if not cli_command_allowed(command):
        raise HTTPException(status_code=400, detail="Command not allowed by maintenance guardrails")
    if command.startswith("docker compose restart") or command.startswith("docker restart"):
        enforce_maintenance_guard("Guarded CLI service action", service_action=True)
    result = await run_shell(command, WORKSPACE_ROOT)
    return {"status": "ok" if result.get("returncode") == 0 else "failed", "command": command, **result}

