@app.post("/api/codex/bridge/session/message")
async def codex_bridge_session_message(req: CodexSessionMessageRequest):
    require_control_token(req.token)
    session = load_codex_session(req.session_id)
    prompt = str(req.prompt or "").strip()
    if not prompt:
        raise HTTPException(status_code=400, detail="prompt is required")
    allow_write = session.get("allow_write") if req.allow_write is None else bool(req.allow_write)
    if allow_write:
        enforce_maintenance_guard("Codex session message", write_intent=True)
    session_messages = [row for row in (session.get("messages") or []) if isinstance(row, dict)]
    session_messages.append({"role": "operator", "content": prompt, "created_at": int(time.time())})
    result = await run_codex_bridge_session(
        goal=prompt,
        project_key=session.get("project_key"),
        task_uid=str(session.get("last_task_uid") or "").strip(),
        mode="conversation",
        scope=(req.scope or "implement").strip() or "implement",
        workdir=str(session.get("workdir") or "").strip(),
        allow_write=bool(allow_write),
        update_task_status_flag=req.update_task_status,
        source="api_codex_session",
        conversation_context=session_messages,
        session_id=str(session.get("session_id") or req.session_id),
    )
    reply = _codex_operator_reply(result)
    session["allow_write"] = bool(allow_write)
    session = _apply_codex_result_to_session(session, prompt, result)
    return {
        "status": result.get("status", "unknown"),
        "reply": reply,
        "session": session,
        "session_preview": codex_session_preview(session),
        "result": result,
    }


