@app.get("/api/memory/explorer")
async def memory_explorer(q: str = Query(default="")):
    stats = {"chat_files": len(list((MEMORY_ROOT / "chat").glob("*.txt")))}
    qdrant_results = await lookup_memory(q, limit=8) if q else []
    chat_files = sorted((MEMORY_ROOT / "chat").glob("*.txt"), reverse=True)[:12]
    chat_history = []
    for p in chat_files:
        preview = _read_text_preview(p, MEMORY_PREVIEW_CHARS)
        if preview:
            chat_history.append(preview)
    return {"stats": stats, "qdrant_results": qdrant_results, "chat_history": chat_history}

