@app.get("/api/processes/live")
async def processes_live():
    summary = {
        "active_agent_runs": len(list((MEMORY_ROOT / 'agent_runs').glob('*.json'))),
        "active_tasks": len(list((MEMORY_ROOT / 'tasks').glob('*.json'))),
        "autonomy_runs": len(list(AUTONOMY_RUN_ROOT.glob("*.json"))),
    }
    autonomy_runs = _list_autonomy_runs(limit=40)
    try:
        conn = db_conn(); cur = conn.cursor(dictionary=True)
        cur.execute("SELECT agent_key, status, title, created_at FROM agent_activity ORDER BY id DESC LIMIT 30")
        activities = cur.fetchall()
        cur.execute("SELECT agent_key, display_name, role_type, status, full_time, last_seen_at FROM agent_registry ORDER BY updated_at DESC LIMIT 20")
        processes = cur.fetchall()
        cur.close(); conn.close()
        return {"summary": summary, "processes": processes, "activities": activities, "autonomy_runs": autonomy_runs}
    except Exception as e:
        return {"summary": summary, "processes": [], "activities": [], "autonomy_runs": autonomy_runs, "error": str(e)}

