@app.post("/api/action/kernel/run")
async def action_kernel_run(req: ActionKernelRunRequest):
    mode = (req.mode or "auto").strip().lower()
    if mode not in {"auto", "plan", "execute"}:
        mode = "auto"
    goal = (req.prompt or "").strip()
    if not goal:
        raise HTTPException(status_code=400, detail="prompt is required")
    scan = action_kernel_scan(goal)
    if mode == "execute":
        require_control_token(req.token)
    elif mode == "auto" and PROACTIVE_REQUIRE_CONTROL and scan.get("scan", {}).get("actionable"):
        require_control_token(req.token)
    force_execute: Optional[bool] = None
    if mode == "execute":
        force_execute = True
    elif mode == "plan":
        force_execute = False
    result = await run_proactive_autonomy(
        goal,
        source=(req.source or "kernel").strip() or "kernel",
        force_execute=force_execute,
        max_steps_override=req.max_steps,
    )
    return {"status": "ok", "scan": scan.get("scan", {}), "mode": mode, "result": result}

