def _supervision_policy_overrides(req: AgentSupervisionReviewRequest) -> dict[str, Any]:
    policy = load_review_cycle_policy_profile()
    supervision = policy.get("agent_supervision") if isinstance(policy.get("agent_supervision"), dict) else {}
    return {
        "stale_after_sec": max(120, int(req.stale_after_sec or supervision.get("stale_after_sec") or 900)),
        "queue_check_sec": max(60, int(req.queue_check_sec or supervision.get("queue_check_sec") or 300)),
        "supervisor_check_sec": max(120, int(req.supervisor_check_sec or supervision.get("supervisor_check_sec") or 900)),
        "self_improvement_allowed": bool(supervision.get("self_improvement_allowed", True)),
        "self_improvement_after_sec": max(300, int(supervision.get("self_improvement_after_sec") or 1800)),
    }

def _employee_queue_snapshot(task_rows: list[dict[str, Any]], project_key: str) -> dict[str, int]:
    pending_statuses = {"queued", "planned", "todo", "open"}
    active_statuses = {"in_progress", "running", "active"}
    pending_count = 0
    in_progress_count = 0
    completed_count = 0
    normalized_project = normalize_project_key(project_key)
    for row in task_rows:
        if not isinstance(row, dict):
            continue
        row_project = normalize_project_key(row.get("project_key"))
        if normalized_project and row_project and row_project != normalized_project:
            continue
        status = str(row.get("status") or "").strip().lower()
        if status in pending_statuses:
            pending_count += 1
        elif status in active_statuses:
            in_progress_count += 1
        elif status == "completed":
            completed_count += 1
    return {"pending_count": pending_count, "in_progress_count": in_progress_count, "completed_count": completed_count}

def _recommend_supervision_action(record: dict[str, Any], queue_snapshot: dict[str, int], pause_state: dict[str, Any], policy: dict[str, Any], now_ts: int) -> tuple[str, str]:
    idle_seconds = max(0, now_ts - max(_employee_int(record.get("heartbeat_at"), 0), _employee_int(record.get("updated_at"), now_ts)))
    current_assignment = str(record.get("current_assignment") or "").strip()
    supervisor_key = str(record.get("supervisor_key") or "").strip()
    followup_due_at = _employee_int(record.get("followup_due_at"), 0)
    if bool(pause_state.get("paused")):
        return "paused", str(pause_state.get("reason") or "Workers are paused.").strip() or "Workers are paused."
    if current_assignment and idle_seconds >= int(policy.get("stale_after_sec") or 900):
        return "nudge_assignee", "Waiting on an assigned worker too long; send a nudge and record a follow-up."
    if followup_due_at > 0 and followup_due_at <= now_ts:
        return "follow_up", "Follow-up window is due; check the outstanding assignment owner."
    if not current_assignment and int(queue_snapshot.get("pending_count") or 0) > 0:
        return "check_queue", "Queue has pending work; pull the next approved assignment."
    if supervisor_key and idle_seconds >= int(policy.get("supervisor_check_sec") or 900):
        return "check_supervisor", "No active assignment; check with the project supervisor."
    if bool(policy.get("self_improvement_allowed")) and idle_seconds >= int(policy.get("self_improvement_after_sec") or 1800):
        return "self_improvement", "No queue work is waiting; run approved eval, cleanup, or tuning work."
    return "hold", "Stay ready and keep watching the queue."

