@app.post("/api/agents/supervision/review")
async def agents_supervision_review(req: AgentSupervisionReviewRequest):
    policy = _supervision_policy_overrides(req)
    pause_state = runtime_worker_pause_state()
    now_ts = int(time.time())
    data = employee_state_doc()
    task_rows = list_project_tasks(project_key=normalize_project_key(req.project_key), status="", limit=500)
    reviewed_rows: list[dict[str, Any]] = []
    for raw in data.get("agents", []):
        record = normalize_employee_agent_record(raw)
        if req.agent_key and str(record.get("agent_key") or "").strip().lower() != str(req.agent_key or "").strip().lower():
            reviewed_rows.append(record)
            continue
        if req.project_key and normalize_project_key(record.get("project_key")) != normalize_project_key(req.project_key):
            reviewed_rows.append(record)
            continue
        queue_snapshot = _employee_queue_snapshot(task_rows, str(record.get("project_key") or req.project_key or ""))
        idle_seconds = max(0, now_ts - max(_employee_int(record.get("heartbeat_at"), 0), _employee_int(record.get("updated_at"), now_ts)))
        recommendation, _reason = _recommend_supervision_action(record, queue_snapshot, pause_state, policy, now_ts)
        reviewed_rows.append(
            normalize_employee_agent_record(
                {
                    **record,
                    "idle_seconds": idle_seconds,
                    "queue_status": queue_snapshot,
                    "queue_check_at": now_ts,
                    "last_review_cycle": now_ts,
                    "stale_assignment_followup_status": recommendation,
                    "updated_at": max(_employee_int(record.get("updated_at"), 0), now_ts if recommendation != "hold" else _employee_int(record.get("updated_at"), 0)),
                }
            )
        )
    data["agents"] = reviewed_rows
    write_employee_state(data)
    limited_rows: list[dict[str, Any]] = []
    for row in reviewed_rows[: max(1, min(int(req.max_items or 80), 200))]:
        limited_rows.append(
            {
                "agent_key": row.get("agent_key"),
                "display_name": row.get("display_name"),
                "project_key": row.get("project_key"),
                "supervisor_key": row.get("supervisor_key"),
                "status": row.get("status"),
                "heartbeat_at": row.get("heartbeat_at"),
                "idle_seconds": row.get("idle_seconds"),
                "current_assignment": row.get("current_assignment"),
                "queue_status": row.get("queue_status"),
                "queue_check_at": row.get("queue_check_at"),
                "followup_due_at": row.get("followup_due_at"),
                "last_review_cycle": row.get("last_review_cycle"),
                "last_supervisor_check_at": row.get("last_supervisor_check_at"),
                "stale_assignment_followup_status": row.get("stale_assignment_followup_status"),
            }
        )
    summary = {
        "count": len(limited_rows),
        "paused": bool(pause_state.get("paused")),
        "pause_reason": str(pause_state.get("reason") or "").strip(),
        "nudge_assignee": len([row for row in limited_rows if row.get("stale_assignment_followup_status") == "nudge_assignee"]),
        "check_queue": len([row for row in limited_rows if row.get("stale_assignment_followup_status") == "check_queue"]),
        "check_supervisor": len([row for row in limited_rows if row.get("stale_assignment_followup_status") == "check_supervisor"]),
        "self_improvement": len([row for row in limited_rows if row.get("stale_assignment_followup_status") == "self_improvement"]),
    }
    _append_runtime_diagnostic_receipt(
        {
            "event": "agent_supervision_review",
            "stage": "review",
            "severity": "warn" if summary["nudge_assignee"] or summary["check_supervisor"] else "info",
            "scene": "assistant-core",
            "route": "agents/supervision/review",
            "connection": {"project": normalize_project_key(req.project_key), "paused": bool(pause_state.get("paused"))},
            "summary": "Agent supervision review completed",
            "details": json.dumps(_json_ready(summary), ensure_ascii=False),
        }
    )
    return {"status": "ok", "policy": policy, "summary": summary, "rows": limited_rows}

@app.get("/api/agents/registry")
async def agents_registry():
    profile_rows = load_olympus_agent_profiles()
    profile_map = {str(row.get("key") or "").strip().lower(): row for row in profile_rows if isinstance(row, dict)}
    employee_rows = [normalize_employee_agent_record(row) for row in employee_state_doc().get("agents", []) if isinstance(row, dict)]
    employee_map = {str(row.get("agent_key") or "").strip().lower(): row for row in employee_rows if str(row.get("agent_key") or "").strip()}
    try:
        conn = db_conn(); cur = conn.cursor(dictionary=True)
        cur.execute("SELECT * FROM agent_registry ORDER BY updated_at DESC LIMIT 100")
        rows = cur.fetchall(); cur.close(); conn.close()
        normalized_rows = []
        seen_keys: set[str] = set()
        for row in rows:
            key = str(row.get("agent_key") or "").strip().lower()
            profile = profile_map.get(key, {})
            employee = employee_map.get(key, {})
            normalized = {**profile, **employee, **row}
            if profile and profile.get("display_name") and not row.get("display_name"):
                normalized["display_name"] = profile.get("display_name")
            if employee and employee.get("display_name") and not normalized.get("display_name"):
                normalized["display_name"] = employee.get("display_name")
            normalized_rows.append(normalized)
            if key:
                seen_keys.add(key)
        all_keys = set(profile_map.keys()) | set(employee_map.keys())
        for key in all_keys:
            if key in seen_keys:
                continue
            profile = profile_map.get(key, {})
            employee = employee_map.get(key, {})
            normalized_rows.append(
                {
                    **employee,
                    "agent_key": profile.get("key") or employee.get("agent_key") or key,
                    "display_name": profile.get("display_name") or profile.get("public_name") or employee.get("display_name") or profile.get("key"),
                    "role_type": profile.get("role_type") or profile.get("rank") or employee.get("role_type") or "agent",
                    "status": employee.get("status") or profile.get("status") or "profile_only",
                    "full_time": 1 if bool(employee.get("full_time", profile.get("full_time", True))) else 0,
                    "goals_text": profile.get("summary") or profile.get("mission") or profile.get("role") or employee.get("notes") or "",
                    "config_json": profile,
                    "profile_path": profile.get("profile_path"),
                }
            )
        return {
            "summary": {
                "count": len(normalized_rows),
                "full_time": len([r for r in normalized_rows if r.get("full_time")]),
                "idle_alerts": len([r for r in normalized_rows if str(r.get("stale_assignment_followup_status") or "").strip() in {"nudge_assignee", "check_supervisor"}]),
            },
            "rows": normalized_rows,
        }
    except Exception as e:
        fallback_rows = [
            {
                **employee_map.get(str(profile.get("key") or "").strip().lower(), {}),
                "agent_key": profile.get("key"),
                "display_name": profile.get("display_name") or profile.get("public_name") or profile.get("key"),
                "role_type": profile.get("role_type") or profile.get("rank") or "agent",
                "status": profile.get("status") or "profile_only",
                "full_time": 1 if bool(profile.get("full_time", True)) else 0,
                "goals_text": profile.get("summary") or profile.get("mission") or profile.get("role") or "",
                "config_json": profile,
                "profile_path": profile.get("profile_path"),
            }
            for profile in profile_rows
            if isinstance(profile, dict)
        ]
        return {
            "summary": {
                "count": len(fallback_rows),
                "full_time": len([r for r in fallback_rows if r.get("full_time")]),
                "idle_alerts": len([r for r in fallback_rows if str(r.get("stale_assignment_followup_status") or "").strip() in {"nudge_assignee", "check_supervisor"}]),
            },
            "rows": fallback_rows,
            "error": str(e),
        }

