@app.get("/api/cognition/owner/stream")
async def cognition_owner_stream(request: Request, room_key: str = Query(default="all"), after_id: int = Query(default=0)):
    require_owner_trace_access()
    wanted_room = str(room_key or "all").strip().lower() or "all"
    async def generate():
        last_seen = max(0, int(after_id or 0))
        while True:
            if await request.is_disconnected():
                break
            rows = owner_trace_entries(limit=80, room_key=wanted_room, after_id=last_seen)
            if rows:
                for row in rows:
                    last_seen = max(last_seen, int(row.get("id") or 0))
                    yield f"event: entry\ndata: {json.dumps(row, ensure_ascii=False)}\n\n"
            else:
                heartbeat = {"ts": int(time.time()), "room_key": wanted_room}
                yield f"event: heartbeat\ndata: {json.dumps(heartbeat)}\n\n"
            await asyncio.sleep(1.0)
    return StreamingResponse(
        generate(),
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )

