@app.post("/api/self/experiment")
async def self_experiment(req: ExperimentRequest):
    live_file = safe_workspace_path(req.relative_path)
    if not live_file.exists() or not live_file.is_file():
        raise HTTPException(status_code=404, detail="Live file not found")
    experiment_id = uuid.uuid4().hex[:12]
    sandbox_root = SANDBOX_ROOT / experiment_id
    copy_workspace_to_sandbox(sandbox_root)
    candidate_file = safe_under(sandbox_root, req.relative_path)
    candidate_file.parent.mkdir(parents=True, exist_ok=True)
    candidate_file.write_text(req.candidate_content, encoding="utf-8")
    baseline, candidate = await asyncio.gather(
        run_shell(req.test_command, WORKSPACE_ROOT),
        run_shell(req.test_command, sandbox_root),
    )
    adopt_recommended = candidate["returncode"] == 0 and (
        baseline["returncode"] != 0 or candidate["duration_sec"] <= baseline["duration_sec"] + 0.25
    )
    record = {
        "experiment_id": experiment_id,
        "relative_path": req.relative_path,
        "test_command": req.test_command,
        "candidate_file": str(candidate_file),
        "live_file": str(live_file),
        "baseline": baseline,
        "candidate": candidate,
        "adopt_recommended": adopt_recommended,
        "created_at": int(time.time()),
    }
    out = MEMORY_ROOT / "experiments" / f"{experiment_id}.json"
    out.write_text(json.dumps(record, indent=2), encoding="utf-8")
    mysql_summary("experiment", f"Experiment {experiment_id}", record)
    return record

@app.post("/api/self/adopt")
async def self_adopt(req: AdoptRequest):
    require_control_token(req.token)
    enforce_maintenance_guard("Self adopt", write_intent=True, self_apply=True)
    record_file = MEMORY_ROOT / "experiments" / f"{req.experiment_id}.json"
    if not record_file.exists():
        raise HTTPException(status_code=404, detail="Experiment not found")
    record = json.loads(record_file.read_text(encoding="utf-8"))
    if not record.get("adopt_recommended"):
        raise HTTPException(status_code=400, detail="Candidate not recommended for adoption")
    candidate_file = Path(record["candidate_file"])
    live_file = Path(record["live_file"])
    backup_path = live_file.with_suffix(live_file.suffix + f".bak_{int(time.time())}")
    shutil.copy2(live_file, backup_path)
    shutil.copy2(candidate_file, live_file)
    return {"status": "adopted", "live_file": str(live_file), "backup_file": str(backup_path)}

