@app.post("/api/accounts/request")
async def accounts_request(req: AccountRequest):
    ensure_accounts_requested_scope_columns()
    provider = (req.provider or "").strip().lower()
    if not provider:
        raise HTTPException(status_code=400, detail="Provider is required")
    purpose = (req.purpose or "").strip()
    if not purpose:
        raise HTTPException(status_code=400, detail="Purpose is required")
    scope = normalize_integration_scope(req.scope)
    project_key = normalize_project_key(req.project_key)
    if scope == "luminax":
        project_key = None
    details = {"requested_via": "ui", "scope": scope}
    if project_key:
        details["project_key"] = project_key
    conn = db_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            "INSERT INTO accounts_requested (provider, purpose, status, integration_scope, project_key, details_json) VALUES (%s,%s,%s,%s,%s,%s)",
            (provider, purpose, "pending", scope, project_key, json.dumps(details)),
        )
    except Exception:
        cur.execute(
            "INSERT INTO accounts_requested (provider, purpose, status, details_json) VALUES (%s,%s,%s,%s)",
            (provider, purpose, "pending", json.dumps(details)),
        )
    conn.commit()
    row_id = cur.lastrowid
    cur.close()
    conn.close()
    note = f"ACCOUNT WORKFLOW REQUEST\nProvider: {provider}\nScope: {scope}\nProject key: {project_key or 'none'}\nPurpose: {purpose}\nHuman verification remains manual."
    await save_memory(note)
    return {"status": "pending", "request_id": row_id, "provider": provider, "purpose": purpose, "scope": scope, "project_key": project_key}

