@app.get("/api/integrations/status")
async def integrations_status(scope: str = Query(default=""), project_key: str = Query(default="")):
    ensure_accounts_requested_scope_columns()
    scope_filter = normalize_integration_scope(scope) if (scope or "").strip() else ""
    project_filter = normalize_project_key(project_key)
    if project_filter and not scope_filter:
        scope_filter = "project"
    rows = []
    by_provider = {}
    by_scope = {}
    try:
        conn = db_conn()
        cur = conn.cursor(dictionary=True)
        clauses = []
        args: list[Any] = []
        if scope_filter:
            clauses.append("integration_scope=%s")
            args.append(scope_filter)
        if project_filter and scope_filter == "project":
            clauses.append("project_key=%s")
            args.append(project_filter)
        where_sql = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        query = (
            "SELECT id, created_at, provider, purpose, status, integration_scope, project_key, details_json "
            f"FROM accounts_requested{where_sql} ORDER BY id DESC LIMIT 200"
        )
        try:
            cur.execute(query, tuple(args))
        except Exception:
            cur.execute("SELECT id, created_at, provider, purpose, status, details_json FROM accounts_requested ORDER BY id DESC LIMIT 200")
        rows = cur.fetchall()
        cur.close()
        conn.close()
    except Exception as e:
        return {"summary": {"error": str(e)}, "rows": []}
    for row in rows:
        row_scope = normalize_integration_scope(row.get("integration_scope"))
        row_project = normalize_project_key(row.get("project_key"))
        row["integration_scope"] = row_scope
        row["project_key"] = row_project
        p = (row.get("provider") or "unknown").strip().lower()
        s = (row.get("status") or "pending").strip().lower()
        if p not in by_provider:
            by_provider[p] = {"provider": p, "total": 0, "pending": 0, "connected": 0, "failed": 0, "rejected": 0}
        by_provider[p]["total"] += 1
        if s in by_provider[p]:
            by_provider[p][s] += 1
        if row_scope not in by_scope:
            by_scope[row_scope] = {"scope": row_scope, "total": 0, "pending": 0, "connected": 0, "failed": 0, "rejected": 0}
        by_scope[row_scope]["total"] += 1
        if s in by_scope[row_scope]:
            by_scope[row_scope][s] += 1
    return {
        "summary": {
            "providers": sorted(by_provider.values(), key=lambda x: x["provider"]),
            "scopes": sorted(by_scope.values(), key=lambda x: x["scope"]),
            "total_rows": len(rows),
            "filters": {"scope": scope_filter or None, "project_key": project_filter},
        },
        "rows": rows,
    }

@app.post("/api/integrations/update")
async def integrations_update(req: IntegrationStatusUpdateRequest):
    require_control_token(req.token)
    ensure_accounts_requested_scope_columns()
    status = (req.status or "").strip().lower()
    if status not in {"pending", "connected", "failed", "rejected"}:
        raise HTTPException(status_code=400, detail="Invalid integration status")
    provider = (req.provider or "").strip().lower()
    if not provider:
        raise HTTPException(status_code=400, detail="Provider is required")
    scope = normalize_integration_scope(req.scope)
    project_key = normalize_project_key(req.project_key)
    if scope == "luminax":
        project_key = None
    details = {"updated_via": "ui", "note": req.note, "scope": scope}
    if project_key:
        details["project_key"] = project_key
    conn = db_conn()
    cur = conn.cursor()
    try:
        if req.request_id:
            cur.execute(
                "UPDATE accounts_requested SET status=%s, details_json=%s WHERE id=%s",
                (status, json.dumps(details), req.request_id),
            )
        else:
            where = ["provider=%s", "status='pending'", "integration_scope=%s"]
            args: list[Any] = [provider, scope]
            if scope == "project" and project_key:
                where.append("project_key=%s")
                args.append(project_key)
            query = f"UPDATE accounts_requested SET status=%s, details_json=%s WHERE {' AND '.join(where)} ORDER BY id DESC LIMIT 1"
            cur.execute(query, tuple([status, json.dumps(details)] + args))
    except Exception:
        if req.request_id:
            cur.execute(
                "UPDATE accounts_requested SET status=%s, details_json=%s WHERE id=%s",
                (status, json.dumps(details), req.request_id),
            )
        else:
            cur.execute(
                "UPDATE accounts_requested SET status=%s, details_json=%s WHERE provider=%s AND status='pending' ORDER BY id DESC LIMIT 1",
                (status, json.dumps(details), provider),
            )
    conn.commit()
    affected = cur.rowcount
    cur.close()
    conn.close()
    await save_memory(
        f"INTEGRATION STATUS UPDATE\nProvider: {provider}\nScope: {scope}\nProject key: {project_key or 'none'}\n"
        f"Status: {status}\nAffected rows: {affected}\nNote: {req.note}"
    )
    return {"status": "ok", "provider": provider, "scope": scope, "project_key": project_key, "updated_status": status, "affected": affected}


