@app.get("/api/brand_accounts/monitors")
async def brand_monitors_list_api(
    token: str = Query(default=""),
    provider: str = Query(default=""),
    account_key: str = Query(default=""),
    status: str = Query(default=""),
):
    require_control_token(token)
    qs = [f"token={quote(token)}"]
    for key, value in [("provider", provider), ("account_key", account_key), ("status", status)]:
        if value:
            qs.append(f"{key}={quote(value)}")
    return await _account_worker_call("GET", f"/brand_accounts/monitors/list?{'&'.join(qs)}")


