@app.get("/api/projects/overview")
async def projects_overview(project_key: str = Query(default="")):
    ensure_accounts_requested_scope_columns()
    ensure_project_tasks_table()
    target_project_key = normalize_project_key(project_key)
    summary = {
        "project_count": 0,
        "task_file_count": len(list((MEMORY_ROOT / "tasks").glob("*.json"))),
        "project_task_count": 0,
        "project_task_status_counts": {},
        "site_count": 0,
        "account_request_count": 0,
        "integration_scope_counts": {"project": 0, "luminax": 0},
        "workflow_count": len(list(WORKFLOW_ROOT.glob("*.json"))),
        "workflow_run_count": len(list(WORKFLOW_RUN_ROOT.glob("*.json"))),
        "model_job_count": len(list(MODEL_HUB_JOBS_ROOT.glob("*.json"))),
    }
    model_catalog = _model_catalog_doc()
    model_rows = [m for m in model_catalog.get("models", []) if isinstance(m, dict)]
    summary["model_count"] = len(model_rows)
    summary["model_status_counts"] = _model_status_summary(model_rows).get("by_status", {})
    recent_projects = _list_project_records(limit=80)
    if target_project_key:
        recent_projects = [row for row in recent_projects if str(row.get("project_key", "")).strip() == target_project_key]
    summary["project_count"] = len(recent_projects)
    recent_tasks = []
    recent_project_tasks: list[dict[str, Any]] = []
    recent_sites = []
    recent_account_requests = []
    for p in sorted((MEMORY_ROOT / "tasks").glob("*.json"), reverse=True)[:30]:
        try:
            recent_tasks.append(json.loads(p.read_text(encoding="utf-8")))
        except Exception:
            continue
    try:
        recent_project_tasks = list_project_tasks(project_key=target_project_key, status="", limit=120)
        summary["project_task_count"] = len(recent_project_tasks)
        for row in recent_project_tasks:
            row_status = normalize_task_status(row.get("status"), default="queued")
            summary["project_task_status_counts"][row_status] = summary["project_task_status_counts"].get(row_status, 0) + 1
        conn = db_conn()
        cur = conn.cursor(dictionary=True)
        cur.execute("SELECT id, created_at, site_name, title, root_path, status FROM site_projects ORDER BY id DESC LIMIT 40")
        recent_sites = cur.fetchall()
        summary["site_count"] = len(recent_sites)
        if target_project_key:
            try:
                cur.execute(
                    "SELECT id, created_at, provider, purpose, status, integration_scope, project_key "
                    "FROM accounts_requested WHERE integration_scope='luminax' OR (integration_scope='project' AND project_key=%s) "
                    "ORDER BY id DESC LIMIT 120",
                    (target_project_key,),
                )
            except Exception:
                cur.execute("SELECT id, created_at, provider, purpose, status FROM accounts_requested ORDER BY id DESC LIMIT 60")
        else:
            try:
                cur.execute("SELECT id, created_at, provider, purpose, status, integration_scope, project_key FROM accounts_requested ORDER BY id DESC LIMIT 120")
            except Exception:
                cur.execute("SELECT id, created_at, provider, purpose, status FROM accounts_requested ORDER BY id DESC LIMIT 60")
        recent_account_requests = cur.fetchall()
        summary["account_request_count"] = len(recent_account_requests)
        for row in recent_account_requests:
            row_scope = normalize_integration_scope(row.get("integration_scope"))
            row["integration_scope"] = row_scope
            row["project_key"] = normalize_project_key(row.get("project_key"))
            summary["integration_scope_counts"][row_scope] = summary["integration_scope_counts"].get(row_scope, 0) + 1
        cur.close()
        conn.close()
    except Exception as e:
        summary["db_error"] = str(e)
    return {
        "summary": summary,
        "recent_projects": recent_projects[:80],
        "recent_tasks": recent_tasks[:25],
        "recent_project_tasks": recent_project_tasks[:80],
        "recent_sites": recent_sites,
        "recent_account_requests": recent_account_requests,
        "model_catalog_preview": model_rows[:60],
        "recent_model_jobs": _list_model_jobs(limit=40),
        "hive_latest": read_latest_hive_debate(),
    }

