@app.get("/api/sites/public/{site_name}")
@app.get("/api/sites/public/{site_name}/{path:path}")
async def sites_public(site_name: str, path: str = ""):
    base = _site_publish_root(site_name)
    if not base.exists():
        raise HTTPException(status_code=404, detail="Published site not found")
    return FileResponse(_resolve_site_asset(base, path))

@app.get("/api/sites/default/public")
@app.get("/api/sites/default/public/{path:path}")
async def sites_default_public(path: str = ""):
    default_root = _effective_default_site_root()
    if not default_root or not default_root.exists():
        raise HTTPException(status_code=404, detail="Default site not published")
    return FileResponse(_resolve_site_asset(default_root, path))

@app.post("/api/chat")
async def chat(req: ChatRequest, background_tasks: BackgroundTasks):
    trace_ctx = trace_request_context(
        room_key=req.room_key,
        room_label=req.room_label,
        room_kind=req.room_kind,
        speaker=req.speaker,
        session_id=req.session_id,
        meta=req.meta,
        default_room_kind="web",
        default_room_label="Command Center Conversation",
        default_source="chat",
    )
    trace = []
    autonomy: dict[str, Any] | None = None
    skip_accuracy_gate = False
    local_companion = is_local_companion_surface(req.meta, req.room_kind)
    skip_post_autonomy = False
    owner_trace_log(
        "command-center",
        "web",
        "user_prompt",
        f"{trace_ctx['speaker']} asked in {trace_ctx['room_label']}",
        req.prompt,
        room_key=trace_ctx["room_key"],
        room_label=trace_ctx["room_label"],
        room_kind=trace_ctx["room_kind"],
        speaker=trace_ctx["speaker"],
        session_id=trace_ctx["session_id"],
        meta={"surface": trace_ctx["meta"].get("surface") or "chat", "phase": "request"},
    )
    if looks_like_capability_query(req.prompt):
        final_text = capability_identity_response()
    elif local_companion:
        final_text, trace, autonomy = await run_local_companion_chat(req.prompt, trace_ctx)
        skip_post_autonomy = True
    elif is_actionable_prompt(req.prompt):
        final_text, trace, orchestration = await compose_actionable_reply(req.prompt, trace_ctx, allow_write=True)
        autonomy = {
            "status": "routed",
            "execution_mode": "project_thread",
            "project_key": orchestration.get("project_key"),
            "task": orchestration.get("task") or {},
            "session_id": orchestration.get("session_id") or "",
            "codex": orchestration.get("codex_result") or {},
            "detail": orchestration.get("codex_error") or "",
        }
    elif looks_like_site_change_prompt(req.prompt):
        final_text = site_change_prompt_response(req.prompt)
        skip_accuracy_gate = True
    elif is_quick_chat_prompt(req.prompt):
        final_text = await quick_chat_response(req.prompt)
    else:
        memories = await lookup_memory(req.prompt)
        if memories:
            owner_trace_log(
                "memory",
                "system",
                "memory_lookup",
                f"Loaded {len(memories)} memory matches",
                "\n".join([_truncate_text(m, 220) for m in memories[:4]]),
                room_key=trace_ctx["room_key"],
                room_label=trace_ctx["room_label"],
                room_kind=trace_ctx["room_kind"],
                speaker=trace_ctx["speaker"],
                session_id=trace_ctx["session_id"],
                meta={"phase": "memory"},
            )
        prompt = f"{req.prompt}\n\nRelevant memory:\n" + "\n".join(memories)
        final_text, trace = await maybe_execute_tools(prompt, max_rounds=3)
    if not skip_accuracy_gate:
        final_text = await apply_accuracy_gate(req.prompt, final_text, trace)
    for item in trace:
        trace_summary, trace_content = summarize_trace_item(item)
        owner_trace_log(
            "tool-router",
            "tool",
            "tool_event",
            trace_summary,
            trace_content,
            room_key=trace_ctx["room_key"],
            room_label=trace_ctx["room_label"],
            room_kind=trace_ctx["room_kind"],
            speaker=trace_ctx["speaker"],
            session_id=trace_ctx["session_id"],
            meta={"phase": "tool"},
        )
    if (not skip_post_autonomy) and autonomy is None and not looks_like_capability_query(req.prompt) and not reply_needs_follow_up(final_text):
        try:
            autonomy = await run_proactive_autonomy(req.prompt, source="chat", seed_response=final_text)
        except Exception as e:
            autonomy = {"status": "error", "detail": str(e)}
    if autonomy and is_actionable_prompt(req.prompt) and str(autonomy.get("execution_mode") or "").strip().lower() not in {"project_thread"}:
        auto_status = str(autonomy.get("status", "unknown"))
        auto_mode = str(autonomy.get("execution_mode", "plan_only"))
        vote_signature = str(autonomy.get("vote_signature", "")).strip()
        friendly_confirmation = str(
            autonomy.get("friendly_confirmation")
            or (autonomy.get("hive") or {}).get("friendly_confirmation")
            or ""
        ).strip()
        queued_uid = (
            ((autonomy.get("task") or {}).get("task_uid"))
            or ((autonomy.get("task") or {}).get("task_id"))
            or ""
        )
        final_text = (
            final_text.strip()
            + f"\n\nAutonomy status: {auto_status} ({auto_mode})."
            + (f" Hive voted {vote_signature}." if vote_signature else "")
            + (f" Task: {queued_uid}." if queued_uid else "")
        )
        if friendly_confirmation:
            final_text += f"\n\n{friendly_confirmation}"
    if autonomy:
        owner_trace_log(
            "autonomy",
            "system",
            "autonomy_follow_up",
            f"Autonomy {autonomy.get('status') or 'completed'}",
            json.dumps(_json_ready(autonomy), ensure_ascii=False),
            room_key=trace_ctx["room_key"],
            room_label=trace_ctx["room_label"],
            room_kind=trace_ctx["room_kind"],
            speaker=trace_ctx["speaker"],
            session_id=trace_ctx["session_id"],
            meta={
                "phase": "autonomy",
                "status": str(autonomy.get("status") or ""),
                "mode": str(autonomy.get("execution_mode") or ""),
            },
        )
    owner_trace_log(
        "luminax",
        "assistant",
        "assistant_reply",
        f"Zeus replied in {trace_ctx['room_label']}",
        final_text,
        room_key=trace_ctx["room_key"],
        room_label=trace_ctx["room_label"],
        room_kind=trace_ctx["room_kind"],
        speaker=trace_ctx["speaker"],
        session_id=trace_ctx["session_id"],
        meta={"surface": trace_ctx["meta"].get("surface") or "chat", "phase": "reply"},
    )
    trace_ready = _json_ready(trace)
    autonomy_ready = _json_ready(autonomy or {})
    background_tasks.add_task(
        save_memory,
        f"USER: {req.prompt}\nASSISTANT: {final_text}\nTRACE: {json.dumps(trace_ready, ensure_ascii=False)}\nAUTONOMY: {json.dumps(autonomy_ready, ensure_ascii=False)}",
    )
    mysql_write("chat", "user", req.prompt, {})
    mysql_write("chat", "assistant", final_text, {"trace": trace_ready, "autonomy": autonomy_ready})
    return {"response": final_text, "trace": trace_ready, "autonomy": autonomy_ready}


@app.post("/api/chat/discord")
async def chat_discord(req: DiscordChatRequest):
    mode = (req.mode or "conversation").strip().lower()
    if mode not in {"conversation", "lookup", "lookup_deep", "voice", "action"}:
        mode = "conversation"
    summary_mode = _normalize_summary_mode(req.summary_mode, req.prompt)
    discord_context = {
        "project_key": req.project_key,
        "channel_policy": req.channel_policy,
        "actor_role": req.actor_role,
        "authorized_capabilities": req.authorized_capabilities,
        "visibility_mode": req.visibility_mode,
        "request_source": req.request_source,
        "summary_mode": summary_mode,
    }
    trace_ctx = trace_request_context(
        room_key=req.room_key,
        room_label=req.room_label,
        room_kind=req.room_kind or "discord",
        speaker=req.speaker,
        session_id=req.session_id,
        meta={**(req.meta or {}), **{k: v for k, v in discord_context.items() if v}},
        default_room_kind="discord",
        default_room_label="Discord Room",
        default_source="discord",
    )
    trace: list[dict[str, Any]] = []
    research_job: dict[str, Any] | None = None
    actionable_receipt = False
    discord_actionable = discord_request_prefers_actionable(
        req.prompt,
        mode=mode,
        project_key=req.project_key,
        actor_role=req.actor_role,
        request_source=req.request_source,
        authorized_capabilities=req.authorized_capabilities,
    )
    discord_allow_write = discord_request_allow_write(
        actor_role=req.actor_role,
        authorized_capabilities=req.authorized_capabilities,
    )
    owner_trace_log(
        "discord",
        "discord",
        "user_prompt",
        f"{trace_ctx['speaker']} spoke in {trace_ctx['room_label']}",
        req.prompt,
        room_key=trace_ctx["room_key"],
        room_label=trace_ctx["room_label"],
        room_kind=trace_ctx["room_kind"],
        speaker=trace_ctx["speaker"],
        session_id=trace_ctx["session_id"],
        meta={"mode": mode, "surface": "discord", "phase": "request"},
    )
    if mode in {"lookup", "lookup_deep"}:
        final_text, trace, research_job = await compose_live_lookup_reply(req.prompt, speaker=req.speaker, deep=mode == "lookup_deep")
    elif discord_actionable:
        actionable_receipt = True
        final_text, trace, orchestration = await compose_actionable_reply(
            req.prompt,
            trace_ctx,
            allow_write=discord_allow_write,
        )
        research_job = {
            "status": "routed",
            "execution_mode": "project_thread",
            "project_key": orchestration.get("project_key"),
            "task": orchestration.get("task") or {},
            "session_id": orchestration.get("session_id") or "",
            "codex": orchestration.get("codex_result") or {},
            "detail": orchestration.get("codex_error") or "",
            "allow_write": bool(discord_allow_write),
        }
        if mode == "action":
            mode = "conversation"
    else:
        final_text = await quick_discord_response(req.prompt, mode=mode, speaker=req.speaker, discord_context=discord_context)
    if not actionable_receipt:
        final_text, summary_mode = await shape_external_response(
            prompt=req.prompt,
            draft=final_text,
            summary_mode=summary_mode,
            disclosure_mode=str(req.visibility_mode or "direct").strip() or "direct",
            surface="discord",
            modality="voice" if mode == "voice" else "text",
            access={
                "project_key": req.project_key,
                "actor_role": req.actor_role,
                "visibility_mode": req.visibility_mode,
            },
        )
    final_text = compact_discord_mode_reply(final_text, mode=mode)
    for item in trace:
        trace_summary, trace_content = summarize_trace_item(item)
        owner_trace_log(
            "discord-tools",
            "discord",
            "tool_event",
            trace_summary,
            trace_content,
            room_key=trace_ctx["room_key"],
            room_label=trace_ctx["room_label"],
            room_kind=trace_ctx["room_kind"],
            speaker=trace_ctx["speaker"],
            session_id=trace_ctx["session_id"],
            meta={"mode": mode, "surface": "discord", "phase": "tool"},
        )
    owner_trace_log(
        "luminax",
        "discord",
        "assistant_reply",
        f"Zeus replied in {trace_ctx['room_label']}",
        final_text,
        room_key=trace_ctx["room_key"],
        room_label=trace_ctx["room_label"],
        room_kind=trace_ctx["room_kind"],
        speaker=trace_ctx["speaker"],
        session_id=trace_ctx["session_id"],
        meta={"mode": mode, "surface": "discord", "phase": "reply"},
    )
    return {"response": final_text, "trace": trace, "mode": mode, "research_job": research_job, "summary_mode_used": summary_mode}

@app.post("/api/chat/stream")
async def chat_stream(req: ChatRequest):
    trace_ctx = trace_request_context(
        room_key=req.room_key,
        room_label=req.room_label,
        room_kind=req.room_kind,
        speaker=req.speaker,
        session_id=req.session_id,
        meta=req.meta,
        default_room_kind="web",
        default_room_label="Command Center Conversation",
        default_source="chat_stream",
    )
    async def generate():
        trace: list[dict[str, Any]] = []
        streamed_tokens = False
        skip_accuracy_gate = False
        autonomy: dict[str, Any] | None = None
        local_companion = is_local_companion_surface(req.meta, req.room_kind)
        skip_post_autonomy = False
        owner_trace_log(
            "command-center",
            "web",
            "user_prompt",
            f"{trace_ctx['speaker']} asked in {trace_ctx['room_label']}",
            req.prompt,
            room_key=trace_ctx["room_key"],
            room_label=trace_ctx["room_label"],
            room_kind=trace_ctx["room_kind"],
            speaker=trace_ctx["speaker"],
            session_id=trace_ctx["session_id"],
            meta={"surface": trace_ctx["meta"].get("surface") or "chat_stream", "phase": "request"},
        )
        if looks_like_capability_query(req.prompt):
            final_text = capability_identity_response()
            final_text = await apply_accuracy_gate(req.prompt, final_text, [])
            for token in final_text.split():
                yield f"data: {json.dumps({'token': token + ' '})}\n\n"
                await asyncio.sleep(0.006)
            yield f"data: {json.dumps({'narration': '[capability profile loaded]'})}\n\n"
            owner_trace_log(
                "luminax",
                "assistant",
                "assistant_reply",
                f"Zeus replied in {trace_ctx['room_label']}",
                final_text,
                room_key=trace_ctx["room_key"],
                room_label=trace_ctx["room_label"],
                room_kind=trace_ctx["room_kind"],
                speaker=trace_ctx["speaker"],
                session_id=trace_ctx["session_id"],
                meta={"surface": trace_ctx["meta"].get("surface") or "chat_stream", "phase": "reply"},
            )
            await save_memory(f"USER: {req.prompt}\nASSISTANT: {final_text}\nTRACE: []")
            mysql_write("chat", "user", req.prompt, {})
            mysql_write("chat", "assistant", final_text, {"trace": []})
            yield "data: [DONE]\n\n"
            return
        elif local_companion:
            final_text, trace, autonomy = await run_local_companion_chat(req.prompt, trace_ctx)
            skip_post_autonomy = True
        elif is_actionable_prompt(req.prompt):
            final_text, trace, orchestration = await compose_actionable_reply(req.prompt, trace_ctx, allow_write=True)
            autonomy = {
                "status": "routed",
                "execution_mode": "project_thread",
                "project_key": orchestration.get("project_key"),
                "task": orchestration.get("task") or {},
                "session_id": orchestration.get("session_id") or "",
                "codex": orchestration.get("codex_result") or {},
                "detail": orchestration.get("codex_error") or "",
            }
            if not skip_accuracy_gate:
                final_text = await apply_accuracy_gate(req.prompt, final_text, trace)
        elif looks_like_site_change_prompt(req.prompt):
            final_text = site_change_prompt_response(req.prompt)
            skip_accuracy_gate = True
            for token in final_text.split():
                yield f"data: {json.dumps({'token': token + ' '})}\n\n"
                await asyncio.sleep(0.008)
            streamed_tokens = True
            yield f"data: {json.dumps({'narration': '[site change clarification ready]'})}\n\n"
        elif is_quick_chat_prompt(req.prompt):
            final_text = await quick_chat_response(req.prompt)
            final_text = await apply_accuracy_gate(req.prompt, final_text, [])
            for token in final_text.split():
                yield f"data: {json.dumps({'token': token + ' '})}\n\n"
                await asyncio.sleep(0.008)
            streamed_tokens = True
            yield f"data: {json.dumps({'narration': '[fast voice path complete]'})}\n\n"
        else:
            memories = await lookup_memory(req.prompt)
            if memories:
                owner_trace_log(
                    "memory",
                    "system",
                    "memory_lookup",
                    f"Loaded {len(memories)} memory matches",
                    "\n".join([_truncate_text(m, 220) for m in memories[:4]]),
                    room_key=trace_ctx["room_key"],
                    room_label=trace_ctx["room_label"],
                    room_kind=trace_ctx["room_kind"],
                    speaker=trace_ctx["speaker"],
                    session_id=trace_ctx["session_id"],
                    meta={"phase": "memory"},
                )
            prompt = f"{req.prompt}\n\nRelevant memory:\n" + "\n".join(memories)
            final_text, trace = await maybe_execute_tools(prompt, max_rounds=3)
            if not skip_accuracy_gate:
                final_text = await apply_accuracy_gate(req.prompt, final_text, trace)
        if trace:
            for item in trace:
                trace_summary, trace_content = summarize_trace_item(item)
                owner_trace_log(
                    "tool-router",
                    "tool",
                    "tool_event",
                    trace_summary,
                    trace_content,
                    room_key=trace_ctx["room_key"],
                    room_label=trace_ctx["room_label"],
                    room_kind=trace_ctx["room_kind"],
                    speaker=trace_ctx["speaker"],
                    session_id=trace_ctx["session_id"],
                    meta={"phase": "tool"},
                )
                yield f"data: {json.dumps({'tool': item})}\n\n"
        if not streamed_tokens:
            for token in final_text.split():
                yield f"data: {json.dumps({'token': token + ' '})}\n\n"
                await asyncio.sleep(0.01)
        if (not skip_post_autonomy) and autonomy is None and not reply_needs_follow_up(final_text):
            try:
                autonomy = await run_proactive_autonomy(req.prompt, source="chat_stream", seed_response=final_text)
            except Exception as e:
                autonomy = {"status": "error", "detail": str(e)}
        if autonomy:
            owner_trace_log(
                "autonomy",
                "system",
                "autonomy_follow_up",
                f"Autonomy {autonomy.get('status') or 'completed'}",
                json.dumps(_json_ready(autonomy), ensure_ascii=False),
                room_key=trace_ctx["room_key"],
                room_label=trace_ctx["room_label"],
                room_kind=trace_ctx["room_kind"],
                speaker=trace_ctx["speaker"],
                session_id=trace_ctx["session_id"],
                meta={
                    "phase": "autonomy",
                    "status": str(autonomy.get("status") or ""),
                    "mode": str(autonomy.get("execution_mode") or ""),
                },
            )
            yield f"data: {json.dumps({'autonomy': autonomy})}\n\n"
        yield f"data: {json.dumps({'narration': '[tools checked, response completed]'})}\n\n"
        owner_trace_log(
            "luminax",
            "assistant",
            "assistant_reply",
            f"Zeus replied in {trace_ctx['room_label']}",
            final_text,
            room_key=trace_ctx["room_key"],
            room_label=trace_ctx["room_label"],
            room_kind=trace_ctx["room_kind"],
            speaker=trace_ctx["speaker"],
            session_id=trace_ctx["session_id"],
            meta={"surface": trace_ctx["meta"].get("surface") or "chat_stream", "phase": "reply"},
        )
        await save_memory(
            f"USER: {req.prompt}\nASSISTANT: {final_text}\nTRACE: {json.dumps(trace)}\nAUTONOMY: {json.dumps(autonomy or {}, ensure_ascii=False)}"
        )
        mysql_write("chat", "user", req.prompt, {})
        mysql_write("chat", "assistant", final_text, {"trace": trace, "autonomy": autonomy or {}})
        yield "data: [DONE]\n\n"
    return StreamingResponse(generate(), media_type="text/event-stream")


